  ui_story_5053_50530102_3_dialog_content = "¿Cómo la oscuridad Angel encontrarnos aquí? ¡Pensé que habíamos reiniciado todo!",
  ui_story_5053_50530102_4_dialog_content = "E-Esa es la voz de mi hermana...",
  ui_story_5053_50530102_5_dialog_content = "¡Aqui!",
  ui_story_5053_50530102_6_dialog_content = "¡Noche Blanca! ¡Protegernos!",
  ui_story_5053_50530102_7_dialog_content = "¡No pierdas tu enfoque en la batalla, Caleb!",
  ui_story_5053_50530102_8_dialog_content = "¡No recibo órdenes tuyas! Que está pasando aqui...",
  ui_story_5053_50530102_9_dialog_content = "¡Bajen sus armas, intrusos!",
  ui_story_5053_50530102_10_dialog_content = "¡¿Cómo te atreves a iniciar una pelea en la residencia del Señor de la Ciudad?!",
  ui_story_5053_50530102_11_dialog_content = "¡Hola!",
  ui_story_5053_50530102_12_dialog_content = "¿Monstruo AA? ¡¿Qué diablos es eso?!",
  ui_story_5053_50530102_13_dialog_content = "¡Ve a levantarte!",
  ui_story_5053_50530102_14_dialog_content = "Bien bien...",
  ui_story_5053_50530102_15_dialog_content = "Sch... verruga...!",
  ui_story_5053_50530102_16_dialog_content = "...",
  ui_story_5053_50530102_17_dialog_content = "¿Por qué la oscuridad Angel ir detrás de mi padre todo el tiempo?",
  ui_story_5053_50530102_18_dialog_content = "Y sigue llamando el nombre de tu familia. ¿Los conoce a ustedes?",
  ui_story_5053_50530102_19_dialog_content = "Pero no lo reconozco en absoluto...",
  ui_story_5053_50530102_20_dialog_content = "¡Aaaah—!",
  ui_story_5053_50530102_21_dialog_content = "¡La Espada del Soberano!",
  ui_story_5053_50530102_22_dialog_content = "Oh...",
  ui_story_5053_50530102_23_dialog_content = "Tu poder ha disminuido mucho desde nuestra primera batalla.",
  ui_story_5053_50530102_24_dialog_content = "¡Hola!",
  ui_story_5053_50530102_25_dialog_content = "Sin embargo, sigue siendo una molestia.",
  ui_story_5053_50530102_26_dialog_content = "¡Por favor déjame tomar el mando! ¡Aunque mi habilidad psíquica es mucho más débil ahora, todavía puedo coordinarme!",
  ui_story_5053_50530102_27_dialog_content = "Gracias, pero tengo otra perspectiva en mente.",
  ui_story_5053_50530102_28_dialog_content = "Deberías saber cómo manejar esto, ¿verdad? Mia?",
  ui_story_5053_50530102_29_dialog_content = "¿A mí? ¿Me estás dando la orden...?",
  ui_story_5053_50530102_30_dialog_content = "Tómalo con calma. Piensa en mí como una pieza de ajedrez en tu mano.",
  ui_story_5053_50530102_31_dialog_content = "Dime, ¿dónde debo ir?",
  ui_story_5053_50530102_32_dialog_content = "Tal vez... ¿puedes seguir atrayendo al ángel y luego puedo atacarlo por la espalda?",
  ui_story_5053_50530102_33_dialog_content = "¡Insuficiente!",
  ui_story_5053_50530102_34_dialog_content = "Bueno, eh...",
  ui_story_5053_50530102_35_dialog_content = "¡Tienes más de una pieza de ajedrez en tus manos!",
  ui_story_5053_50530102_36_dialog_content = "Lo siento, no puedo...",
  ui_story_5053_50530102_37_dialog_content = "Relajarse, Mia, ¡puedes hacerlo!",
  ui_story_5053_50530102_38_dialog_content = "PlayerName...",
  ui_story_5053_50530102_39_dialog_content = "(Esto es prácticamente un entrenamiento de caballero. ¿Estás tratando de guiarme, padre?)",
  ui_story_5053_50530102_40_dialog_content = "(No puedo defraudarlo... ¡Y no puedo deshonrar a los caballeros!)",
  ui_story_5053_50530102_41_dialog_content = "Sí, creo que tengo esto...",
  ui_story_5053_50530102_42_dialog_content = "Mientras mi padre distrae a la Oscuridad Angel... Jakine atacará por un lado y, tío, tú atacas por el otro.",
  ui_story_5053_50530102_43_dialog_content = "Lancemos una ofensiva triangular para rodear al ángel... Eso debería funcionar, ¿verdad?",
  ui_story_5053_50530102_44_dialog_content = "¡Suena bien! Muy profesional, me gusta.",
  ui_story_5053_50530102_45_dialog_content = "No es un mal plan. Vamos a hacerlo.",
  ui_story_5053_50530102_46_dialog_content = "Aqui...",
  ui_story_5053_50530102_47_dialog_content = "¿Qué vas a? ¿Por qué nos persigues?",
  ui_story_5053_50530102_48_dialog_content = "Sch... verruga...!!!",
  ui_story_5053_50530102_49_dialog_content = "(¿Se está conteniendo? ¡Esta es la mejor ventana para atacar!)",
  ui_story_5053_50530102_50_dialog_content = "¡Ahora, todos!",
  ui_story_5053_50530102_51_dialog_content = "Lo siento...!",
  ui_story_5053_50530102_52_dialog_content = "¡Actívate, Bola de Cristal!",
  ui_story_5053_50530102_53_dialog_content = "¡Conoce mi poder!",
  ui_story_5053_50530102_54_dialog_content = "Argh-!",
  ui_story_5053_50530102_55_dialog_content = "Todo golpeó. ¡Somos simplemente increíbles!",
  ui_story_5053_50530102_56_dialog_content = "¡Duele... duele...!",
  ui_story_5053_50530102_57_dialog_content = "Parece estar en agonía...",
  ui_story_5053_50530102_58_dialog_content = "No te pongas suave conmigo ahora. La oscuridad Angel nos ha estado atacando sin razón!",
  ui_story_5053_50530102_59_dialog_content = "Tienes razón, no hay piedad en la batalla.",
  ui_story_5053_50530102_60_dialog_content = "¿Funcionó nuestro ataque?",
  ui_story_5053_50530102_61_dialog_content = "Agh... ¡Aaaaaaagh!",
  ui_story_5053_50530102_62_dialog_content = "Vaya, qué chillido espeluznante.",
  ui_story_5053_50530102_63_dialog_content = "¡Oh, no, se está encendiendo y está a punto de apagarse!",
  ui_story_5053_50530102_64_dialog_content = "¡¿Q-Qué ahora...?!",
  ui_story_5053_50530102_65_dialog_content = "Lo hiciste bien, Mia. Me haré cargo ahora.",
  ui_story_5053_50530102_66_dialog_content = "Padre...?",
  ui_story_5053_50530102_67_dialog_content = "¡Todos ustedes, retírense!",
  ui_story_5053_50530102_68_dialog_content = "Sch...",
  ui_story_5053_50530102_69_dialog_content = "Sch... verruga...!!!",
  ui_story_5053_50530102_70_dialog_content = "¿Estás tan desesperado por pelear conmigo uno a uno?",
  ui_story_5053_50530102_71_dialog_content = "Entonces te concederé tu deseo.",
  ui_story_5053_50530102_72_dialog_content = "¡Ahora, toma tu epitafio—!",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5053_50530102_74_dialog_content = "Uf... Uf...",
  ui_story_5053_50530102_75_dialog_content = "¿A dónde fue?",
  ui_story_5053_50530102_76_dialog_content = "Probablemente huyó por un camino exterior.",
  ui_story_5053_50530102_77_dialog_content = "Eso fue maravilloso, Señor Schwartz!",
  ui_story_5053_50530102_78_dialog_content = "No importa cuán poderoso sea, el ángel debe estar gravemente herido. Dudo que pueda llegar muy lejos.",
  ui_story_5053_50530102_79_dialog_content = "...",
  ui_story_5053_50530102_80_dialog_content = "¿Todavía te preocupa la oscuridad? Angel, ¿Tío?",
  ui_story_5053_50530102_81_dialog_content = "Su voz... No importa, mi hermana nunca podría ser un monstruo.",
  ui_story_5053_50530102_82_dialog_content = "Tómate el tiempo ahora para lanzar tu hechizo, Jakine.",
  ui_story_5053_50530102_83_dialog_content = "Eh... ¡Oh, sí! Ahora que el ángel entrometido finalmente se ha ido, ¡puedo sacar a todos!",
  ui_story_5053_50530102_84_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_85_dialog_content = "¡Volvamos a la realidad!",
  ui_story_5053_50530102_86_dialog_content = "¡Abracadabra!",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530102_88_dialog_content = "no creo que eso haya funcionado...",
  ui_story_5053_50530102_89_dialog_content = "¡Déjame intentar de nuevo!",
  ui_story_5053_50530102_90_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_91_dialog_content = "¡Volvamos a la realidad! ¡Abracadabra!",
  ui_story_5053_50530102_92_dialog_content = "Seguro que tienes las palabras correctas, Jakine?",
  ui_story_5053_50530102_93_dialog_content = "¡Por supuesto! ¿Están todos tomados de la mano? Déjame comprobar... ¡Sí!",
  ui_story_5053_50530102_94_dialog_content = "Pensé que falló la última vez porque fue tan caótico que nuestras manos no pudieron estar unidas.",
  ui_story_5053_50530102_95_dialog_content = "Pero, ¿cómo es que todavía no funcionó esta vez?",
  ui_story_5053_50530102_96_dialog_content = "Tenías el Cristal de este reino cuando lanzaste el hechizo la última vez. ¿Olvidaste esta vez?",
  ui_story_5053_50530102_97_dialog_content = "No, <color=#FFB400>solo lo necesitas cuando rebobinas el tiempo</color>... Esa es la caja de seguridad de emergencia que montó mi mamá.",
  ui_story_5053_50530102_98_dialog_content = "¡No es necesario para una salida estándar como esta!",
  ui_story_5053_50530102_99_dialog_content = "¿Hay otras posibilidades?",
  ui_story_5053_50530102_100_dialog_content = "A menos que... <color=#FFB400>No todos estamos aquí</color>.",
  ui_story_5053_50530102_101_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5053_50530102_102_dialog_content = "Por cuestiones de seguridad, una persona debe activar el Cristal para ingresar y todos deben estar presentes para que todo el grupo se vaya.",
  ui_story_5053_50530102_103_dialog_content = "Aunque accidentalmente rompí esa regla con mi hechizo cuando entramos, ¡no puedo estar haciendo eso al salir!",
  ui_story_5053_50530102_104_dialog_content = "Todos estamos aquí, ¿verdad? no echo de menos a nadie...",
  ui_story_5053_50530102_105_dialog_content = "¿Podría alguien más haber sido arrastrado junto con nosotros?",
  ui_story_5053_50530102_106_dialog_content = "O tal vez, antes de que entráramos, alguien entró por otros medios.",
  ui_story_5053_50530102_107_dialog_content = "Pero el activador falleció hace mucho tiempo, así que eso es imposible, ¿verdad?",
  ui_story_5053_50530102_108_dialog_content = "...",
  ui_story_5053_50530102_109_dialog_content = "¡¿Mi señor, ha venido en persona?!",
  ui_story_5053_50530102_110_dialog_content = "Mis disculpas que nuestra incompetencia haya perturbado su paz.",
  ui_story_5053_50530102_111_dialog_content = "Todo está bien. ¿Me puedes decir que es lo que paso?",
  ui_story_5053_50530102_112_dialog_content = "Por supuesto. Varios individuos desconocidos invadieron el jardín y lucharon contra un monstruo.",
  ui_story_5053_50530102_113_dialog_content = "Uno de los intrusos se veía y vestía muy parecido a la Princesa Verónica, pero no estoy seguro...",
  ui_story_5053_50530102_114_dialog_content = "¿Verónica? Veo. Estás haciendo un buen trabajo.",
  ui_story_5053_50530201_1_dialog_content = "Entonces, ¿ustedes no quieren probar estos bocadillos? Los terminaré si no lo haces.",
  ui_story_5053_50530201_2_dialog_content = "No puedo creer que todavía estés de humor para eso.",
  ui_story_5053_50530201_3_dialog_content = "Acabamos de pelear en el jardín de Lady Joshua. No tengo idea de cómo decírselo.",
  ui_story_5053_50530201_4_dialog_content = "¡Relájate, relájate! ¡Estresarse no nos llevará a ninguna parte!",
  ui_story_5053_50530201_5_dialog_content = "Te envidio por tu optimismo.",
  ui_story_5053_50530201_6_dialog_content = "Joshua no es alguien que cumpliría con duros castigos.",
  ui_story_5053_50530201_7_dialog_content = "Dado que ordenó que nos trajeran aquí e incluso nos ofreció postre, muestra claramente que nos está tratando con respeto, no con hostilidad.",
  ui_story_5053_50530201_8_dialog_content = "Realmente deberíamos regocijarnos.",
  ui_story_5053_50530201_9_dialog_content = "Si <color=#FFB400>alguien más</color> también hubiera estado presente, probablemente ya estaríamos encarcelados.",
  ui_story_5053_50530201_10_dialog_content = "¿Alguien más? ¿De qué estás hablando?",
  ui_story_5053_50530201_11_dialog_content = "...",
  ui_story_5053_50530201_12_dialog_content = "Se refiere a mí, el yo más joven.",
  ui_story_5053_50530201_13_dialog_content = "No estás tan lleno de ti mismo después de todo, Señor Schwartz.",
  ui_story_5053_50530201_14_dialog_content = "A-De todos modos, aquí viene la Dama Joshua de este mundo",
  ui_story_5053_50530201_15_dialog_content = "Eso al menos prueba que la Oscuridad Angel no es dama Joshua.",
  ui_story_5053_50530201_16_dialog_content = "No deberíamos preocuparnos por eso en este momento. Jakine, ¿sabes cómo averiguar quién más ha entrado en el Cristal?",
  ui_story_5053_50530201_17_dialog_content = "Siempre hay una manera, por supuesto.",
  ui_story_5053_50530201_18_dialog_content = "Solo necesitamos el Cristal de la Memoria Eterna para este mundo.",
  ui_story_5053_50530201_19_dialog_content = "Aparte de usarlo para rebobinar el tiempo, podemos <color=#FFB400>ver quién es una ilusión y quién es real con el Cristal</color>.",
  ui_story_5053_50530201_20_dialog_content = "A pesar de que todavía no puede identificar ubicaciones exactas...",
  ui_story_5053_50530201_21_dialog_content = "Pero el problema con eso es que lleva mucho tiempo. Solo puede verificar una persona a la vez.",
  ui_story_5053_50530201_22_dialog_content = "Hay mucha gente en Lumopolis...",
  ui_story_5053_50530201_23_dialog_content = "¡Está bien! ¡Mientras tengamos la seguridad en la mano, podemos seguir rebobinando para ganar tiempo!",
  ui_story_5053_50530201_24_dialog_content = "Aunque eso agotará a Lumina manteniendo el mundo, así que no podemos hacerlo indiscriminadamente.",
  ui_story_5053_50530201_25_dialog_content = "Entonces nuestra máxima prioridad es encontrar el Cristal de la Memoria Eterna. Deberíamos poner la Oscuridad Angel asunto en espera por ahora.",
  ui_story_5053_50530201_26_dialog_content = "¿Es esto lo que estás buscando?",
  ui_story_5053_50530201_27_dialog_content = "¿Es ese el Cristal de la Eterna Memoria que tienes en la mano, Señora? Joshua?",
  ui_story_5053_50530201_28_dialog_content = "¿Escuchó nuestra conversación, señora? Joshua? ¿Cómo sabías que estábamos buscando el Cristal?",
  ui_story_5053_50530201_29_dialog_content = "Jejeje, no te preocupes por eso, mi querida niña, y echa un vistazo al Cristal.",
  ui_story_5053_50530201_30_dialog_content = "Espera... ¡¿Cómo es esto posible?!",
  ui_story_5053_50530201_31_dialog_content = "Dama Joshua... Eres un <color=#FFB400>auroriano real</color>!",
  ui_story_5053_50530201_32_dialog_content = "!!!",
  ui_story_5053_50530201_33_dialog_content = "Hermana... Pero... ¿Eres realmente tú?",
  ui_story_5053_50530201_34_dialog_content = "¿Quién más sería yo, mi querido pequeño genio?",
  ui_story_5053_50530201_35_dialog_content = "...",
  ui_story_5053_50530201_36_dialog_content = "¿Estás seguro, Jakine?",
  ui_story_5053_50530201_37_dialog_content = "¡Seguro como nunca lo estaré! ¡A menos que haya un problema con mis ojos!",
  ui_story_5053_50530201_38_dialog_content = "Madre... ¿esto es real?",
  ui_story_5053_50530201_39_dialog_content = "Por supuesto que es.",
  ui_story_5053_50530201_40_dialog_content = "Todavía te ves muy parecido a cuando te uniste a los caballeros, tal como lo recordaba.",
  ui_story_5053_50530201_41_dialog_content = "*Sniff* Eso es... Eso es porque...",
  ui_story_5053_50530201_42_dialog_content = "Es porque Forsakin modificó el cuerpo de Veronica... Mia y la hizo para siempre 13 físicamente.",
  ui_story_5053_50530201_43_dialog_content = "Pero espera, vi con mis propios ojos que tú...",
  ui_story_5053_50530201_44_dialog_content = "¿Qué quieres decir?",
  ui_story_5053_50530201_45_dialog_content = "En Schwartz Día de la Familia hace doce años, los Eclipsites plantaron una Semilla en Mia... en Veronica, durante una misión para los caballeros.",
  ui_story_5053_50530201_46_dialog_content = "Luego la enviaron a un laboratorio de Illumina para el llamado \"tratamiento\", que en realidad era una trampa tendida por Eclipsites y traidores.",
  ui_story_5053_50530201_47_dialog_content = "Para salvar a Verónica, Joshua fue a luchar contra ellos por su cuenta.",
  ui_story_5053_50530201_48_dialog_content = "El rescate fue un éxito, pero de alguna manera plantaron una Semilla en Joshua también...",
  ui_story_5053_50530201_49_dialog_content = "Más tarde, después de mucho sufrimiento...",
  ui_story_5053_50530201_50_dialog_content = "Ella <color=#FFB400>optó por acabar con su propia vida</color>.",
  ui_story_5053_50530201_51_dialog_content = "Sin embargo, aquí estás en el Cristal. Tal vez podrías explicar eso.",
  ui_story_5053_50530201_52_dialog_content = "Schwartz, ¿es así como le hablas a la esposa que no has visto en doce años?",
  ui_story_5053_50530201_53_dialog_content = "Está bien, Caleb. Daniel está haciendo lo correcto para proteger a todos.",
  ui_story_5053_50530201_54_dialog_content = "Bien, si tú lo dices.",
  ui_story_5053_50530201_55_dialog_content = "Entonces debería continuar donde lo dejó Daniel.",
  ui_story_5053_50530201_56_dialog_content = "Era cierto que me atormentaba la agonía...",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>Schwartz Manor, hace varios años</color>",
  ui_story_5053_50530201_58_dialog_content = "*Tose* Sólo mátame, Daniel.",
  ui_story_5053_50530201_59_dialog_content = "No escucharé tal pedido de ti, Joshua...",
  ui_story_5053_50530201_60_dialog_content = "Cuanto más me resisto a la Semilla, más me tortura.",
  ui_story_5053_50530201_61_dialog_content = "Puedo sentir que está peleando conmigo por el control de mi cuerpo.",
  ui_story_5053_50530201_62_dialog_content = "¡Hay una manera de liberarte, créeme!",
  ui_story_5053_50530201_63_dialog_content = "¿Recuerdas a Juan el médico? Sí, podemos pedirle ayuda.",
  ui_story_5053_50530201_64_dialog_content = "¡Enviaré gente para localizarlo inmediatamente!",
  ui_story_5053_50530201_65_dialog_content = "Tómatelo con calma y espérame.",
  ui_story_5053_50530201_66_dialog_content = "No tiene sentido, Daniel, no tiene sentido...",
  ui_story_5053_50530201_67_dialog_content = "Urgh—",
  ui_story_5053_50530201_68_dialog_content = "Deja de luchar y ríndete a mí.",
  ui_story_5053_50530201_69_dialog_content = "¡Nunca!",
  ui_story_5053_50530201_70_dialog_content = "¡Nunca entregaré mi cuerpo, incluso si tengo que apuñalarme en el corazón!",
  ui_story_5053_50530201_71_dialog_content = "¡No, suelta esa daga!",
  ui_story_5053_50530201_72_dialog_content = "¡Nunca!",
  ui_story_5053_50530201_73_dialog_content = "¡¡¡Déjalo caer!!!",
  ui_story_5053_50530201_74_dialog_content = "Urgh...",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5053_50530201_76_dialog_content = "¿El Cristal de la Memoria Eterna...?",
  ui_story_5053_50530201_77_dialog_content = "¿Qué estás haciendo? ¡¡¡No!!!",
  ui_story_5053_50530201_78_dialog_content = "Revivamos los días dorados del pasado...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5053_50530201_80_dialog_content = "Estás bien, Joshua? ¿Qué fue ese ruido fuerte?",
  ui_story_5053_50530201_81_dialog_content = "¿Cómo es que no estás respondiendo? Deja de asustarme. Estoy entrando.",
  ui_story_5053_50530201_82_dialog_content = "J-Joshua...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>¡¡¡Hermana!!!</size>",
  ui_story_5053_50530201_84_dialog_content = "La Semilla me dividió en <color=#FFB400>dos personalidades diferentes</color>.",
  ui_story_5053_50530201_85_dialog_content = "Uno es el yo normal, pero el otro es un monstruo irracional y trastornado.",
  ui_story_5053_50530201_86_dialog_content = "A medida que crecía, comenzó a tratar de apoderarse de mí y lastimar a quienes me rodeaban.",
  ui_story_5053_50530201_87_dialog_content = "No podía permitir eso, así que comencé a luchar.",
  ui_story_5053_50530201_88_dialog_content = "El choque constante entre las personalidades estaba destrozando mi mente todos los días.",
  ui_story_5053_50530201_89_dialog_content = "No afectó al monstruo en absoluto, por lo que poco a poco ganó ventaja...",
  ui_story_5053_50530201_90_dialog_content = "Estaba al borde del colapso y sabía que estaba a punto de perder.",
  ui_story_5053_50530201_91_dialog_content = "Así que pensé en una solución que no me dejaría ganar, pero que derrotaría completamente al monstruo—",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>Y eso fue para atraparnos a ambos en el Cristal de la Eterna Memoria</color>.",
  ui_story_5053_50530201_93_dialog_content = "Con un deseo de muerte, me envié a mí y al monstruo a este mundo.",
  ui_story_5053_50530201_94_dialog_content = "Somos uno, así que mientras no me vaya, tiene que quedarse aquí conmigo.",
  ui_story_5053_50530201_95_dialog_content = "Luchamos entre nosotros durante mucho, mucho tiempo.",
  ui_story_5053_50530201_96_dialog_content = "Después de que el reloj marcara la medianoche, nos convertimos en parte de este mundo desde que rompimos la regla.",
  ui_story_5053_50530201_97_dialog_content = "Perdimos nuestra memoria y nos recombinamos para convertirnos en los de este mundo. Joshua, y hemos estado reviviendo este mismo día una y otra vez durante todo este tiempo.",
  ui_story_5053_50530201_98_dialog_content = "Hasta que llegaste.",
  ui_story_5053_50530201_99_dialog_content = "Tu llegada despertó nuestros recuerdos.",
  ui_story_5053_50530201_100_dialog_content = "El monstruo despierto luchó y se separó de mí.",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>Ella me robó todo mi poder</color> y huyó, tratando de salir del Cristal.",
  ui_story_5053_50530201_102_dialog_content = "La situación es grave, pero esta vez...",
  ui_story_5053_50530201_103_dialog_content = "No soy el mismo yo solitario que solía ser.",
  ui_story_5053_50530201_104_dialog_content = "...",
  ui_story_5053_50530201_105_dialog_content = "Q-Qué maravillosa historia... Así que el <color=#FFB400>Oscuro Angel la que nos atacó fue otra señora Joshua</color>?",
  ui_story_5053_50530201_106_dialog_content = "Oscuro Angel? ¿Lo nombraste...? De todos modos, sí, se podría decir eso.",
  ui_story_5053_50530201_107_dialog_content = "Solo Joshua y yo estábamos al tanto de esa conversación, y los detalles coincidían exactamente.",
  ui_story_5053_50530201_108_dialog_content = "realmente eres tu, Joshua...",
  ui_story_5053_50530201_109_dialog_content = "Es genial que finalmente me creas.",
  ui_story_5053_50530201_110_dialog_content = "Oh, Madre... Eres real...",
  ui_story_5053_50530201_111_dialog_content = "Estás llorando otra vez, pequeña.",
  ui_story_5053_50530201_112_dialog_content = "No puedo creer que estés aquí, Joshua. He estado buscando... y nunca te encontré...",
  ui_story_5053_50530201_113_dialog_content = "Qué maravilloso es volver a hablar contigo después de doce años...",
  ui_story_5053_50530201_114_dialog_content = "(La Semilla, dos personalidades... Eso suena muy similar a lo que le pasó a Mia.)",
  ui_story_5053_50530201_115_dialog_content = "(Las personalidades de Mia son amigas y dependen unas de otras, pero es el polo opuesto para Lady Joshua.)",
  ui_story_5053_50530201_116_dialog_content = "(Las semillas tienen efectos tan diferentes en diferentes personas).",
  ui_story_5053_50530201_117_dialog_content = "Hablando de eso, mencionaste algo hace unos doce años.",
  ui_story_5053_50530201_118_dialog_content = "¿He estado aquí durante doce años?",
  ui_story_5053_50530201_119_dialog_content = "Correcto.",
  ui_story_5053_50530201_120_dialog_content = "Con razón te ves totalmente diferente, Daniel.",
  ui_story_5053_50530201_121_dialog_content = "Probablemente no te reconocería si no fuera porque otros te llaman por tu nombre.",
  ui_story_5053_50530201_122_dialog_content = "Pero, ¿qué pasó con tus ojos y tu cara?",
  ui_story_5053_50530201_123_dialog_content = "He pasado por demasiadas guerras y turbulencias para recordar los orígenes de mis cicatrices.",
  ui_story_5053_50530201_124_dialog_content = "Pero aún recuerdo el día que me dejaste, y lo fría que estaba al tacto la daga en tu pecho...",
  ui_story_5053_50530201_125_dialog_content = "Daniel...",
  ui_story_5053_50530201_126_dialog_content = "Hablando de eso, el cuerpo de Lady Joshua fue enterrado, ¿verdad?",
  ui_story_5053_50530201_127_dialog_content = "¿Puede ella o la oscuridad Angel dejar el cristal entonces?",
  ui_story_5053_50530201_128_dialog_content = "Sí.",
  ui_story_5053_50530201_129_dialog_content = "porque su cuerpo <color=#FFB400>nunca fue enterrado</color>.",
  ui_story_5053_50530201_130_dialog_content = "¿Qué quieres decir?",
  ui_story_5053_50530201_131_dialog_content = "Hmph, cuando la encontré, aún no estaba muerta.",
  ui_story_5053_50530201_132_dialog_content = "Saqué algunas cosas y la llevé a casa para recibir tratamiento.",
  ui_story_5053_50530201_133_dialog_content = "¿Qué? Pero escuché que toda la ciudad fue testigo del funeral, así que qué hiciste...",
  ui_story_5053_50530201_134_dialog_content = "Manejé personalmente el funeral de Joshua, por lo que no pudo haber ningún paso en falso.",
  ui_story_5053_50530201_135_dialog_content = "A menos que la exhumaras.",
  ui_story_5053_50530201_136_dialog_content = "Cielos... ¡Dime qué hiciste, hermanito!",
  ui_story_5053_50530201_137_dialog_content = "Ya que preguntas... Sí, te exhumé.",
  ui_story_5053_50530201_138_dialog_content = "Para evitar ser detectado, cavé un túnel a la cripta desde la distancia, para que nadie se diera cuenta.",
  ui_story_5053_50530201_139_dialog_content = "¿Lo cavaste tú mismo? Seré honesto, no esperaba que fueras capaz de trabajar así.",
  ui_story_5053_50530201_140_dialog_content = "Estoy dispuesto a hacer cualquier cosa por mi hermana.",
  ui_story_5053_50530201_141_dialog_content = "Pero, ¿cómo engañaste al médico y al forense? ¿Los sobornaste...?",
  ui_story_5053_50530201_142_dialog_content = "No, solo usé una poción.",
  ui_story_5053_50530201_143_dialog_content = "También me sorprendió que los grandes médicos de Lumopolis Gardens fueran engañados por mis pequeños trucos.",
  ui_story_5053_50530201_144_dialog_content = "Con razón no pudieron curar a mi hermana.",
  ui_story_5053_50530201_145_dialog_content = "Nunca fuiste tan humilde cuando discutías con los instructores en Dawn Academia, Caleb.",
  ui_story_5053_50530201_146_dialog_content = "Eres el tipo de genio con el que la Academia se encuentra quizás una vez por siglo. Espero que apliques tu inteligencia a las cosas correctas.",
  ui_story_5053_50530201_147_dialog_content = "¿Por qué tuviste que actuar por tu propia voluntad, Caleb...",
  ui_story_5053_50530201_148_dialog_content = "Porque nunca quisiste irte Schwartz y los niños, mientras él te hacía la vida cada vez más difícil.",
  ui_story_5053_50530201_149_dialog_content = "Solo quería protegerte.",
  ui_story_5053_50530201_150_dialog_content = "Lamento mucho haberte hecho sentir tan agobiado.",
  ui_story_5053_50530201_151_dialog_content = "Es así porque siempre lo has mimado.",
  ui_story_5053_50530201_152_dialog_content = "Revisaremos esto después de que salgamos de aquí, Caleb.",
  ui_story_5053_50530201_153_dialog_content = "Entonces, podemos irnos de aquí y revivir a Madre si derrotamos a la Oscuridad. Angel?",
  ui_story_5053_50530201_154_dialog_content = "Por lo que hemos reunido hasta ahora, ese es el caso.",
  ui_story_5053_50530201_155_dialog_content = "Entonces, ¿cómo está el cuerpo de Joshua ahora? ¿Puede soportar el impacto de un resurgimiento abrupto?",
  ui_story_5053_50530201_156_dialog_content = "Está perfectamente conservado, por supuesto. Desde que entró en coma, he dedicado todo mi tiempo y esfuerzo a ella.",
  ui_story_5053_50530201_157_dialog_content = "En cuanto al resultado, <color=#FFB400>solo mírame</color>.",
  ui_story_5053_50530201_158_dialog_content = "¿Mírate? ¿Para qué?",
  ui_story_5053_50530201_159_dialog_content = "Caleb, aunque sea por Joshua, te prohíbo experimentos poco éticos.",
  ui_story_5053_50530201_160_dialog_content = "¿Qué es para ti?",
  ui_story_5053_50530201_161_dialog_content = "Espera, estoy perdido. ¿Que está pasando aqui?",
  ui_story_5053_50530201_162_dialog_content = "Cuantos años crees que tengo, Jakine?",
  ui_story_5053_50530201_163_dialog_content = "¿Veinti algo?",
  ui_story_5053_50530201_164_dialog_content = "¿Ves lo que quiero decir?",
  ui_story_5053_50530201_165_dialog_content = "Uh, si no recuerdo mal, el tío debería estar acercándose a los 40...",
  ui_story_5053_50530201_166_dialog_content = "Eh-?!",
  ui_story_5053_50530201_167_dialog_content = "Qué-?!",
  ui_story_5053_50530201_168_dialog_content = "Aquí pensé que el tío nació así o simplemente bueno con el maquillaje... No esperaba que fuera el resultado de experimentos...",
  ui_story_5053_50530201_169_dialog_content = "Nunca usaría una poción no probada en mi hermana.",
  ui_story_5053_50530201_170_dialog_content = "Tampoco lastimaría a personas inocentes como esos nobles, así que la única opción era probarlo en mí mismo.",
  ui_story_5053_50530201_171_dialog_content = "Dios mío, Caleb...",
  ui_story_5053_50530201_172_dialog_content = "¿Estás bien, madre? no te ves bien...",
  ui_story_5053_50530201_173_dialog_content = "Estoy bien... Estoy acostumbrado, probablemente...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>Pero PlayerName, Caleb también actúa de manera muy inmadura, ¿eso significa que su investigación podría mantener a las personas para siempre jóvenes, mentalmente?</size>",
  ui_story_5053_50530201_175_dialog_content = "Escuché eso, Jakine!",
  ui_story_5053_50530201_176_dialog_content = "Si bien su cuerpo está bien, Lumina en ella tiende a perder el control.",
  ui_story_5053_50530201_177_dialog_content = "Todavía necesito investigar más sobre esto ya que aún no he encontrado una solución.",
  ui_story_5053_50530201_178_dialog_content = "¿Lúmina? ¡Por eso me preguntaste dónde estaba el Lumina de Lady Joshua!",
  ui_story_5053_50530201_179_dialog_content = "Obviamente. Mi intención era encontrar su Lumina residual para un tratamiento experimental.",
  ui_story_5053_50530201_180_dialog_content = "Pero, ¿quién podría haber adivinado que ella estuvo en el Cristal todo el tiempo? Y es por eso que la Lumina en su cuerpo seguía perdiendo el control.",
  ui_story_5053_50530201_181_dialog_content = "Mi teoría estaba completamente equivocada...",
  ui_story_5053_50530201_182_dialog_content = "Deberías habérmelo dicho antes, Caleb.",
  ui_story_5053_50530201_183_dialog_content = "¿Te lo dije? ¿Para que pudieras seguir torturándola?",
  ui_story_5053_50530201_184_dialog_content = "¿Por qué estás discutiendo de nuevo? No hagamos esto delante de los demás.",
  ui_story_5053_50530201_185_dialog_content = "Lo siento hermana.",
  ui_story_5053_50530201_186_dialog_content = "Dado que su cuerpo aún está en buenas condiciones, deberíamos sacarla lo antes posible.",
  ui_story_5053_50530201_187_dialog_content = "Volvamos al tema y averigüemos qué hacer con la Oscuridad. Angel.",
  ui_story_5053_50530201_188_dialog_content = "Si hagamos eso.",
  ui_story_5053_50530201_189_dialog_content = "No puedo vencerlo por mi cuenta.",
  ui_story_5053_50530201_190_dialog_content = "porque compartimos <color=#FFB400>el mismo cuerpo y han vivido una vida</color>, solo un tercero podría destruirlo.",
  ui_story_5053_50530201_191_dialog_content = "Pero debes tener cuidado ya que también te está cazando.",
  ui_story_5053_50530201_192_dialog_content = "¿Cazarnos?",
  ui_story_5053_50530201_193_dialog_content = "Sí. Se ha cansado de nuestros conflictos y quiere ser independiente, tomando mi cuerpo para sí mismo.",
  ui_story_5053_50530201_194_dialog_content = "Sería muy difícil en el mundo real.",
  ui_story_5053_50530201_195_dialog_content = "Pero como una parte de mí que activó el Cristal de la Memoria Eterna, puede <color=#FFB400>matar a todas las demás personas vivas para que Lumina se vuelva completa</color> aquí.",
  ui_story_5053_50530201_196_dialog_content = "Es eso cierto, Jakine?",
  ui_story_5053_50530201_197_dialog_content = "Sí. Puede parecer una tontería, pero es posible dentro del Cristal.",
  ui_story_5053_50530201_198_dialog_content = "El Crystal puede parecer un dispositivo de reproducción de memoria, pero el principio detrás de él va mucho más allá.",
  ui_story_5053_50530201_199_dialog_content = "Es por eso que mamá solo hizo uno por orden de la Reina, luego ocultó todo al respecto después de...",
  ui_story_5053_50530201_200_dialog_content = "Entonces, básicamente, hay dos resultados posibles.",
  ui_story_5053_50530201_201_dialog_content = "Una es que destruyamos la Oscuridad Angel y traer señora Joshua con nosotros fuera de aquí.",
  ui_story_5053_50530201_202_dialog_content = "el otro es la oscuridad Angel nos mata y se suelta en el mundo real?",
  ui_story_5053_50530201_203_dialog_content = "Eso es correcto. Qué niño tan brillante. Estás PlayerName, ¿bien?",
  ui_story_5053_50530201_204_dialog_content = "Sí. Por cierto, sabes mi nombre y el de Jakine, y el nombre Mia no parece sorprenderte.",
  ui_story_5053_50530201_205_dialog_content = "¿Tienes recuerdos de antes del reinicio también?",
  ui_story_5053_50530201_206_dialog_content = "si, desde <color=#FFB400>estaba contigo</color> cuando paso.",
  ui_story_5053_50530201_207_dialog_content = "Y no quiero estar lejos de mi familia otra vez...",
  ui_story_5053_50530201_208_dialog_content = "Juro que destruiré la oscuridad Angel y sacarte de aquí, así que no te preocupes.",
  ui_story_5053_50530201_209_dialog_content = "Yo también...! ¡Te liberaré de este lugar!",
  ui_story_5053_50530201_210_dialog_content = "De hecho, tengo fe en todos ustedes.",
  ui_story_5053_50530201_211_dialog_content = "La oscuridad Angel carece de habilidades de razonamiento, pero es tortuoso.",
  ui_story_5053_50530201_212_dialog_content = "Necesitamos cebo para sacarlo.",
  ui_story_5053_50530201_213_dialog_content = "¿Te importa, Daniel?",
  ui_story_5053_50530201_214_dialog_content = "Ningún problema. Es mejor que asuma un papel tan vital y peligroso de todos modos.",
  ui_story_5053_50530201_215_dialog_content = "Pero, ¿cómo lo atraigo hacia mí?",
  ui_story_5053_50530201_216_dialog_content = "No tienes que hacer nada, ya que ese monstruo... <color=#FFB400>más bien te odia</color>.",
  ui_story_5053_50530201_217_dialog_content = "Si no fueras lo suficientemente fuerte para ahuyentarlo, te habría destrozado.",
  ui_story_5053_50530201_218_dialog_content = "Eso también se aplica a los jóvenes que están en este mundo. Es probable que lo ataque en la celebración.",
  ui_story_5053_50530201_219_dialog_content = "A pesar de que matar una ilusión no hará nada por ella, todavía no puede resistirse.",
  ui_story_5053_50530201_220_dialog_content = "Veo. En ese caso, solo tengo que encontrar a mi yo joven y esperar a que aparezca.",
  ui_story_5053_50530201_221_dialog_content = "Espera, ¿no será peligroso, padre? ¿Qué pasa si te lastimas?",
  ui_story_5053_50530201_222_dialog_content = "Siempre estás tan preocupado por nuestra familia, Vonnie.",
  ui_story_5053_50530201_223_dialog_content = "Pero, nuestra situación actual es urgente y debemos enfocar nuestras prioridades.",
  ui_story_5053_50530201_224_dialog_content = "Confía en tu padre, ¿quieres?",
  ui_story_5053_50530201_225_dialog_content = "Está bien.",
  ui_story_5053_50530201_226_dialog_content = "Después del desfile debe ser la ceremonia de apertura en la plaza.",
  ui_story_5053_50530201_227_dialog_content = "¿Deberíamos apostar allí?",
  ui_story_5053_50530201_228_dialog_content = "Buena idea, pero debes quedarte conmigo. Jakine.",
  ui_story_5053_50530201_229_dialog_content = "¿Por qué? No me desaires, soy mucho mejor luchador que PlayerName!",
  ui_story_5053_50530201_230_dialog_content = "Ejem...",
  ui_story_5053_50530201_231_dialog_content = "Sí, lo sé, pero tú manejas el Cristal.",
  ui_story_5053_50530201_232_dialog_content = "Si los demás resultan heridos, siempre podemos retroceder el tiempo para restaurar todo.",
  ui_story_5053_50530201_233_dialog_content = "Pero si te llegara a pasar algo, sería irreversible.",
  ui_story_5053_50530201_234_dialog_content = "T-tienes razón...",
  ui_story_5053_50530201_235_dialog_content = "Así que tenemos al Señor de la Ciudad como cebo. Mia, PlayerName y me dirigiré a la plaza juntos para detener la Oscuridad Angel.",
  ui_story_5053_50530201_236_dialog_content = "Jakine y mi hermana se quedará aquí y esperará las buenas noticias.",
  ui_story_5053_50530201_237_dialog_content = "Asegúrate de cuidarla bien, Jakine.",
  ui_story_5053_50530201_238_dialog_content = "¡Lo tengo! ¿Por qué todos dudan de mí...",
  ui_story_5053_50530201_239_dialog_content = "Estoy sorprendido, Caleb. Pensé que insistirías en quedarte con tu hermana.",
  ui_story_5053_50530201_240_dialog_content = "matando a la oscuridad Angel y sacar a mi hermana de aquí es lo más importante en este momento. ¿Crees que no entiendo eso?",
  ui_story_5053_50530201_241_dialog_content = "U-Um, deberíamos irnos.",
  ui_story_5053_50530201_242_dialog_content = "¡Si, vamos!",
  ui_story_5053_50530201_243_dialog_content = "Dejen de presionarme, ustedes dos.",
  ui_story_5053_50530201_244_dialog_content = "¡Ten un viaje seguro!",
  ui_story_5053_50530201_245_dialog_content = "no te volveré a perder, Joshua, Prometo.",
  ui_story_5053_50530201_246_dialog_content = "Si, te creo.",
  ui_story_5053_50530201_247_dialog_content = "no lo harás",
  ui_story_5053_50530301_1_dialog_content = "El desfile ha terminado y la celebración comenzará pronto.",
  ui_story_5053_50530301_2_dialog_content = "¿Todavía hay buenos lugares disponibles para verlo?",
  ui_story_5053_50530301_3_dialog_content = "¡Date prisa, vamos a comprobarlo!",
  ui_story_5053_50530301_4_dialog_content = "¿Qué hay para ver? Todo es solo una farsa.",
  ui_story_5053_50530301_5_dialog_content = "Está lleno por todas partes. ¿Cómo vamos a detectar la oscuridad? Angel cuando apenas podemos ver?",
  ui_story_5053_50530301_6_dialog_content = "Acércate al puesto y espera.",
  ui_story_5053_50530301_7_dialog_content = "Ya que ambos pueden atraer a la Oscuridad Angel para nosotros, ¿no tendríamos una mejor oportunidad si ambos subieran allí?",
  ui_story_5053_50530301_8_dialog_content = "Bueno, creo que es mejor que me vaya, ya que la gente de aquí todavía me reconoce.",
  ui_story_5053_50530301_9_dialog_content = "Si Padre se va, podría provocar demasiado caos...",
  ui_story_5053_50530301_10_dialog_content = "Verdadero. pero si el Angel ataca el puesto, ¿puedes luchar solo? Mia?",
  ui_story_5053_50530301_11_dialog_content = "Yo... no estoy solo.",
  ui_story_5053_50530301_12_dialog_content = "Padre en este mundo también me ayudará.",
  ui_story_5053_50530301_13_dialog_content = "Sin mencionar que tendré una mejor vista allí arriba. Puedo transmitirte la posición del Ángel cuando lo vea...",
  ui_story_5053_50530301_14_dialog_content = "Hmm... ¡Me mudaré a un lugar donde todos puedan verme y enviaré una señal!",
  ui_story_5053_50530301_15_dialog_content = "Oh, lo siento, padre... ¿Quizás mi idea es demasiado ingenua?",
  ui_story_5053_50530301_16_dialog_content = "Lo cubriste todo. Procederemos como usted sugirió.",
  ui_story_5053_50530301_17_dialog_content = "¿Qué? ¿En serio?",
  ui_story_5053_50530301_18_dialog_content = "Gracias Padre. ¡Me iré ahora, solo espera mi señal!",
  ui_story_5053_50530301_19_dialog_content = "Solo ha pasado un día y Mia es tan valiente e independiente ya. Es bueno ver eso.",
  ui_story_5053_50530301_20_dialog_content = "Ahora no es tiempo de alabanzas, PlayerName. ¡Mantén tus ojos abiertos para el demonio que arruinó a mi hermana!",
  ui_story_5053_50530301_21_dialog_content = "¡Sí, voy enseguida!",
  ui_story_5053_50530301_22_dialog_content = "La celebración comenzará pronto, Carleen. Regresa a tu asiento.",
  ui_story_5053_50530301_23_dialog_content = "Sí, padre.",
  ui_story_5053_50530301_24_dialog_content = "Padre, Carleen.",
  ui_story_5053_50530301_25_dialog_content = "¡¿Verónica?! ¡Padre, Verónica está aquí!",
  ui_story_5053_50530301_26_dialog_content = "¿Verónica? ¿Qué estás haciendo aquí?",
  ui_story_5053_50530301_27_dialog_content = "M-Madre me dijo que volviera a casa para la celebración del Día de la Familia.",
  ui_story_5053_50530301_28_dialog_content = "¿Viste a tu madre?",
  ui_story_5053_50530301_29_dialog_content = "Sí... Ella no se sentía bien pero dijo que no deberíamos preocuparnos.",
  ui_story_5053_50530301_30_dialog_content = "¿No es esta la princesa Verónica? Ha sido un largo tiempo. ¿Cómo estás?",
  ui_story_5053_50530301_31_dialog_content = "¿No se unió la princesa Verónica a los caballeros y los siguió hasta Umbraton?",
  ui_story_5053_50530301_32_dialog_content = "Quería volver para la celebración, así que solicité tiempo libre.",
  ui_story_5053_50530301_33_dialog_content = "Veo. Y deberías, ya que es Schwartz Día de la familia, después de todo.",
  ui_story_5053_50530301_34_dialog_content = "Lástima que mi familia todavía está estacionada en Umbraton y no tiene el privilegio.",
  ui_story_5053_50530301_35_dialog_content = "Verónica es miembro de House Schwartz ¡así que tiene derecho a regresar para nuestro Día de la Familia!",
  ui_story_5053_50530301_36_dialog_content = "Tranquilizarse, Carleeny sé respetuoso con el duque Hermes.",
  ui_story_5053_50530301_37_dialog_content = "no culpes Carleen, Padre. Regresé sin avisar.",
  ui_story_5053_50530301_38_dialog_content = "Y ya que el Duque Hermes está aquí, ¿cómo está la Sra. Hermes últimamente?",
  ui_story_5053_50530301_39_dialog_content = "Lo está haciendo muy bien, como siempre.",
  ui_story_5053_50530301_40_dialog_content = "He estado muy preocupado desde que su nieto siempre se ausentaba y decía que la Sra. Hermes estaba en mal estado.",
  ui_story_5053_50530301_41_dialog_content = "Es bueno saber que ella está bien.",
  ui_story_5053_50530301_42_dialog_content = "... Sí, gracias por la consideración, su alteza.",
  ui_story_5053_50530301_43_dialog_content = "Deberías tomarte el tiempo para pasarlo con tu familia de vez en cuando, duque Hermes.",
  ui_story_5053_50530301_44_dialog_content = "La princesa Verónica ha madurado. Los Caballeros deben haberla entrenado bien.",
  ui_story_5053_50530301_45_dialog_content = "Quizás, pero espero que no se le suba a la cabeza.",
  ui_story_5053_50530301_46_dialog_content = "Oh Señor Schwartz, no tienes que ser tan duro solo con la princesa Veronica.",
  ui_story_5053_50530301_47_dialog_content = "Gracias, duque Troy. Padre tiene razón, debo permanecer humilde y seguir aprendiendo.",
  ui_story_5053_50530301_48_dialog_content = "Ya veo, Princesa Verónica... De hecho, has crecido trabajando con los caballeros.",
  ui_story_5053_50530301_49_dialog_content = "La celebración está comenzando. Por favor, tomen asiento, todos.",
  ui_story_5053_50530301_50_dialog_content = "¡Estuviste genial, Verónica! ¡Esos nobles del Consejo de Ancianos no te asustaron en absoluto!",
  ui_story_5053_50530301_51_dialog_content = "¿Crees que sí? Estaba nervioso, para ser honesto...",
  ui_story_5053_50530301_52_dialog_content = "también fuiste valiente, Carleen, uniéndote al desfile con Padre por ti mismo.",
  ui_story_5053_50530301_53_dialog_content = "No, yo tampoco quería separarme de mamá...",
  ui_story_5053_50530301_54_dialog_content = "Cuando subí al carruaje, papá dijo que mamá no se sentía bien y quería que fuera solo a la celebración...",
  ui_story_5053_50530301_55_dialog_content = "(Ya veo, la madre usó la enfermedad como una excusa para obtener Carleen y Padre lejos para que ella pudiera vernos.)",
  ui_story_5053_50530301_56_dialog_content = "(Eso debe haber herido los sentimientos de la pequeña Carleen, pero al menos nada de esto es real).",
  ui_story_5053_50530301_57_dialog_content = "(Prioridades, prioridades... No, simplemente no puedo hacerlo.)",
  ui_story_5053_50530301_58_dialog_content = "¿Qué tal si volvemos con la madre, Carleen?",
  ui_story_5053_50530301_59_dialog_content = "¿Podemos? ¿No la molestará?",
  ui_story_5053_50530301_60_dialog_content = "Por supuesto que no. Mamá te ama y mejorará contigo.",
  ui_story_5053_50530301_61_dialog_content = "¡Amo a mamá y a ti también! ¡Y padre!",
  ui_story_5053_50530301_62_dialog_content = "¡Le traeré fruta y le contaré sobre el desfile cuando regresemos!",
  ui_story_5053_50530301_63_dialog_content = "Jeje, buena chica.",
  ui_story_5053_50530301_64_dialog_content = "(Es tan maravilloso ver Carleen alegre de nuevo.)",
  ui_story_5053_50530301_65_dialog_content = "¿Que ves?",
  ui_story_5053_50530301_66_dialog_content = "Mia está allá arriba, pero no puedo verla ahora... Aunque es joven Schwartz está listo para hablar.",
  ui_story_5053_50530301_67_dialog_content = "Sin vista de la oscuridad Angel todavía.",
  ui_story_5053_50530301_68_dialog_content = "Apenas podemos ver desde aquí. Deberíamos probar en otro lugar.",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>¡Grieta! ¡Grieta!</color>",
  ui_story_5053_50530301_70_dialog_content = "Eso suena como...",
  ui_story_5053_50530301_71_dialog_content = "No creo que necesitemos probar en otro lugar, Caleb.",
  ui_story_5053_50530301_72_dialog_content = "¡Pato, ustedes dos!",
  ui_story_5053_50530301_73_dialog_content = "¡Aqui!",
  ui_story_5053_50530302_1_dialog_content = "Por la presente declaro el comienzo de la Schwartz ¡Celebración del día de la familia!",
  ui_story_5053_50530302_2_dialog_content = "Ahora, ¡que comience la Ceremonia de Enfrentamiento!",
  ui_story_5053_50530302_3_dialog_content = "(¿Cómo es que aún no han aparecido...?)",
  ui_story_5053_50530302_4_dialog_content = "(Deberían estar allí, pero no puedo verlos en absoluto...)",
  ui_story_5053_50530302_5_dialog_content = "(No me digas la Oscuridad Angel ya rastreado PlayerName y los otros abajo?)",
  ui_story_5053_50530302_6_dialog_content = "(¿Debería encontrar una excusa y marcharme?)",
  ui_story_5053_50530302_7_dialog_content = "¿Estás buscando algo, Vonnie?",
  ui_story_5053_50530302_8_dialog_content = "N-No, Carleen... Mira, el enfrentamiento ha comenzado allí. Parece que va a ser emocionante.",
  ui_story_5053_50530302_9_dialog_content = "¿Cuándo me dejarán participar? Soy tan bueno como ellos.",
  ui_story_5053_50530302_10_dialog_content = "Eso es raro, los dos duelistas simplemente se detuvieron...",
  ui_story_5053_50530302_11_dialog_content = "Y están caminando en nuestra dirección...",
  ui_story_5053_50530302_12_dialog_content = "¿Vamos a tener un programa extra o algo así?",
  ui_story_5053_50530302_13_dialog_content = "¿Qué?",
  ui_story_5053_50530302_14_dialog_content = "(El padre está confundido, como si no supiera lo que está pasando).",
  ui_story_5053_50530302_15_dialog_content = "(Yo no estaba aquí en ese entonces, así que no tengo idea de lo que va a pasar ahora, pero esto no se siente bien).",
  ui_story_5053_50530302_16_dialog_content = "...",
  ui_story_5053_50530302_17_dialog_content = "(Puede ser esto...?!)",
  ui_story_5053_50530302_18_dialog_content = "¡Padre, el asesinato se adelantó!",
  ui_story_5053_50530302_19_dialog_content = "¿Cómo sabes eso? ¿Y que está... movido?",
  ui_story_5053_50530302_20_dialog_content = "Es una larga historia...",
  ui_story_5053_50530302_21_dialog_content = "¿Qué estás haciendo aquí? ¡Este no es el lugar para ti!",
  ui_story_5053_50530302_22_dialog_content = "...",
  ui_story_5053_50530302_23_dialog_content = "¡Qué insolente de tu parte no responderme!",
  ui_story_5053_50530302_24_dialog_content = "No vienen en son de paz... ¡Atrás, duque Hermes!",
  ui_story_5053_50530302_25_dialog_content = "Mantener Carleen a salvo, Verónica!",
  ui_story_5053_50530302_26_dialog_content = "¡Cuidado, padre!",
  ui_story_5053_50530302_27_dialog_content = "¡Hah!",
  ui_story_5053_50530302_28_dialog_content = "¿Es esto todo lo que tienes?",
  ui_story_5053_50530302_29_dialog_content = "¡Un tajo de soberano!",
  ui_story_5053_50530302_30_dialog_content = "Oh...",
  ui_story_5053_50530302_31_dialog_content = "¿Te gustaría probar suerte tú también?",
  ui_story_5053_50530302_32_dialog_content = "¡Hah!",
  ui_story_5053_50530302_33_dialog_content = "¡Toma esto!",
  ui_story_5053_50530302_34_dialog_content = "Oh...",
  ui_story_5053_50530302_35_dialog_content = "¿Sobreviviste a mi espada? Dime, ¿quién te envió?",
  ui_story_5053_50530302_36_dialog_content = "Espera—",
  ui_story_5053_50530302_37_dialog_content = "¡Es demasiado tarde para pedir misericordia ahora!",
  ui_story_5053_50530302_38_dialog_content = "Verónica, ¿por qué el padre le susurra al chico malo?",
  ui_story_5053_50530302_39_dialog_content = "No, no creo que sea Padre quien lo esté amenazando... tiene a Padre con su arma.",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5053_50530302_41_dialog_content = "¿Ah?",
  ui_story_5053_50530302_42_dialog_content = "¡Jajaja! Pronto...",
  ui_story_5053_50530302_43_dialog_content = "¿Por qué su cara se ha vuelto tan contorsionada?",
  ui_story_5053_50530302_44_dialog_content = "¿Y por qué se ríe cuando está herido? Qué está sucediendo...",
  ui_story_5053_50530302_45_dialog_content = "¿Cómo es esto...? ¿Qué tipo de poder es este? <color=#FFB400>No puedo liberar mi arma</color>!",
  ui_story_5053_50530302_46_dialog_content = "En este caso, Sovereign's...",
  ui_story_5053_50530302_47_dialog_content = "Aquí viene...",
  ui_story_5053_50530302_48_dialog_content = "¡Mira hacia arriba, Padre! ¡El cielo!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>Rugido-!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "¿Qué?",
  ui_story_5053_50530302_51_dialog_content = "¡E-El viento es demasiado fuerte! ¡Me va a dejar boquiabierto!",
  ui_story_5053_50530302_52_dialog_content = "Estoy aquí, Carleen!",
  ui_story_5053_50530302_53_dialog_content = "Dragón... Un <color=#FFB400>continuar</color>? Los Kartimas... ¡¿También van a destruir el stand?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>Rugido-!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "Carleen, Verónica!",
  ui_story_5053_50530302_56_dialog_content = "¡Corre rápidamente!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>Auge-!!!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "¡Agh!",
  ui_story_5053_50530401_2_dialog_content = "¡Eres peor de lo que pareces!",
  ui_story_5053_50530401_3_dialog_content = "¿Cómo se atreve una simple Semilla a engañarme imitando la voz de mi hermana...?",
  ui_story_5053_50530401_4_dialog_content = "¡Haré que pagues por sus sufrimientos con sangre!",
  ui_story_5053_50530401_5_dialog_content = "¡Hah!",
  ui_story_5053_50530401_6_dialog_content = "...",
  ui_story_5053_50530401_7_dialog_content = "¡No seas precipitado, Caleb!",
  ui_story_5053_50530401_8_dialog_content = "¡Tiempo de morir!",
  ui_story_5053_50530401_9_dialog_content = "¡Agh!",
  ui_story_5053_50530401_10_dialog_content = "¡¿Qué?!",
  ui_story_5053_50530401_11_dialog_content = "Caleb!!!",
  ui_story_5053_50530401_12_dialog_content = "Ca...leb...?",
  ui_story_5053_50530401_13_dialog_content = "Mantén mi nombre fuera de tus labios...",
  ui_story_5053_50530401_14_dialog_content = "¡Ahora!",
  ui_story_5053_50530401_15_dialog_content = "Sacudiré cada estrella—!!!",
  ui_story_5053_50530401_16_dialog_content = "¡¡¡Puaj!!!",
  ui_story_5053_50530401_17_dialog_content = "Sch... verruga...",
  ui_story_5053_50530401_18_dialog_content = "Sch...",
  ui_story_5053_50530401_19_dialog_content = "¿Todo parece volver a la normalidad?",
  ui_story_5053_50530401_20_dialog_content = "Se ha ido... ¿Significa que está muerto?",
  ui_story_5053_50530401_21_dialog_content = "No, algo anda mal. Mira allá.",
  ui_story_5053_50530401_22_dialog_content = "Argh-!",
  ui_story_5053_50530401_23_dialog_content = "¡Corre!",
  ui_story_5053_50530401_24_dialog_content = "La multitud huye de la plaza... ¿Ha comenzado la rebelión?",
  ui_story_5053_50530401_25_dialog_content = "no puede ser Sin nuestra interferencia, habría comenzado después del asesinato...",
  ui_story_5053_50530401_26_dialog_content = "No...",
  ui_story_5053_50530401_27_dialog_content = "¡Mira, arriba en el cielo!",
  ui_story_5053_50530401_28_dialog_content = "Rugido-!",
  ui_story_5053_50530401_29_dialog_content = "¿El dragón Kartima?",
  ui_story_5053_50530401_30_dialog_content = "¿Qué está haciendo en la ciudad?",
  ui_story_5053_50530401_31_dialog_content = "Oh cielos, ¿qué está haciendo tal cosa en Lumopolis...?",
  ui_story_5053_50530401_32_dialog_content = "¿No deberían ustedes, los guardias, protegernos en momentos como este? ¿Que estas esperando?",
  ui_story_5053_50530401_33_dialog_content = "...",
  ui_story_5053_50530401_34_dialog_content = "H-Oye, ¿qué estás haciendo?",
  ui_story_5053_50530401_35_dialog_content = "Matar... Matar... Matar...",
  ui_story_5053_50530401_36_dialog_content = "¡Aaah—!",
  ui_story_5053_50530401_37_dialog_content = "¡La Espada del Soberano!",
  ui_story_5053_50530401_38_dialog_content = "¿Qué clase de caballeros sois para dañar a las personas indefensas? ¿Es este el nivel al que se ha rebajado Kartimas?",
  ui_story_5053_50530401_39_dialog_content = "Oh...",
  ui_story_5053_50530401_40_dialog_content = "¡E-Este todavía está vivo!",
  ui_story_5053_50530401_41_dialog_content = "Matar...",
  ui_story_5053_50530401_42_dialog_content = "¿Matar? ¿Qué estás diciendo?",
  ui_story_5053_50530401_43_dialog_content = "Sch... verruga...",
  ui_story_5053_50530401_44_dialog_content = "Mata... Mata... ¡Mata a los intrusos!",
  ui_story_5053_50530401_45_dialog_content = "Fuera del camino, PlayerName!",
  ui_story_5053_50530401_46_dialog_content = "¿Por qué, qué le pasa a ella...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>¡Auge!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "Una onda de choque tan poderosa. ¿Ahora que?",
  ui_story_5053_50530401_49_dialog_content = "¡La explosión viene del stand!",
  ui_story_5053_50530401_50_dialog_content = "¡El Señor de la Ciudad ha sido atacado!",
  ui_story_5053_50530401_51_dialog_content = "¡Corran por sus vidas!",
  ui_story_5053_50530401_52_dialog_content = "atacado? Mia...!",
  ui_story_5053_50530401_53_dialog_content = "Si Mia todavía estaba en el estrado... No, no puede ser...",
  ui_story_5053_50530401_54_dialog_content = "Mi hermana todavía está en el Schwartz mansión. Si los rebeldes la encuentran...",
  ui_story_5053_50530401_55_dialog_content = "PlayerName¡Vete con Caleb!",
  ui_story_5053_50530401_56_dialog_content = "si no vuelvo con Mia, decir Jakine para rebobinar inmediatamente!",
  ui_story_5053_50530401_57_dialog_content = "Caballero Schwartz!!!",
  ui_story_5053_50530401_58_dialog_content = "(¿Qué está pasando? ¿Está roto el Cristal de la Memoria Eterna?)",
  ui_story_5053_50530401_59_dialog_content = "(O tal vez la oscuridad Angel todavía está viva y todo esto es obra suya...?)",
  ui_story_5053_50530401_60_dialog_content = "¡No te quedes ahí parado! ¡Tenemos que salir de aquí!",
  ui_story_5053_50530401_61_dialog_content = "Matar... Matar... Matar...",
  ui_story_5053_50530402_1_dialog_content = "¡Hah!",
  ui_story_5053_50530402_2_dialog_content = "Oh...",
  ui_story_5053_50530402_3_dialog_content = "Malditos sean los rebeldes... Gracias por la ayuda, viejo.",
  ui_story_5053_50530402_4_dialog_content = "¿Dónde están las altezas?",
  ui_story_5053_50530402_5_dialog_content = "¿Las altezas? Deberías estar pensando en mantenerte con vida.",
  ui_story_5053_50530402_6_dialog_content = "¿Qué quieres decir con eso?",
  ui_story_5053_50530402_7_dialog_content = "Princesa Carleen, la Princesa Verónica y el Señor de la Ciudad fueron atacados por el dragón... <color=#FFB400>estan muertos</color>!",
  ui_story_5053_50530402_8_dialog_content = "¿Dónde? ¿Dónde está la princesa Verónica?",
  ui_story_5053_50530402_9_dialog_content = "Todavía en el estrado. ¿No me digas que quieres ir a recoger sus restos en un momento como este?",
  ui_story_5053_50530402_10_dialog_content = "Gracias.",
  ui_story_5053_50530402_11_dialog_content = "Tonto... Aferrarte a lo que ya has perdido solo te costará la vida.",
  ui_story_5053_50530402_12_dialog_content = "Josué!",
  ui_story_5053_50530402_13_dialog_content = "Dama Joshua! Jakine! ¿Dónde estás?",
  ui_story_5053_50530402_14_dialog_content = "por que no responden... Joshua!",
  ui_story_5053_50530402_15_dialog_content = "Estoy aquí, Caleb.",
  ui_story_5053_50530402_16_dialog_content = "¡Gracias a Dios que estás bien! Pensé que te había perdido otra vez...",
  ui_story_5053_50530402_17_dialog_content = "La insurgencia se movió hacia arriba. Tenemos que llevarte a un lugar seguro.",
  ui_story_5053_50530402_18_dialog_content = "donde esta Jakine? ¿Adónde en el mundo ha ido en un momento como este?",
  ui_story_5053_50530402_19_dialog_content = "Mantén la calma, Caleb, una cosa a la vez.",
  ui_story_5053_50530402_20_dialog_content = "Estás sudando por todas partes, incluso tu cuello está arrugado. Aquí, déjame arreglarlo por ti.",
  ui_story_5053_50530402_21_dialog_content = "¿Eh? Uh, puedo manejar eso yo mismo...",
  ui_story_5053_50530402_22_dialog_content = "G-Gracias, hermana.",
  ui_story_5053_50530402_23_dialog_content = "Dama Joshua está bien, pero ¿dónde Jakine huir a?",
  ui_story_5053_50530402_24_dialog_content = "Dónde estás, Jakine?!!",
  ui_story_5053_50530402_25_dialog_content = "Oh...",
  ui_story_5053_50530402_26_dialog_content = "Si... s...?",
  ui_story_5053_50530402_27_dialog_content = "¿Qué pasa, Caleb?",
  ui_story_5053_50530402_28_dialog_content = "E-Esto...",
  ui_story_5053_50530402_29_dialog_content = "¿Pero por qué?",
  ui_story_5053_50530402_30_dialog_content = "¿Tu pecho, Caleb?",
  ui_story_5053_50530402_31_dialog_content = "¿Te lastimaste en el camino? N-No, no puede ser...",
  ui_story_5053_50530402_32_dialog_content = "¿Por qué te sigue gustando sentarte en el suelo a tu edad?",
  ui_story_5053_50530402_33_dialog_content = "Todavía inmaduro como siempre, Caleb.",
  ui_story_5053_50530402_34_dialog_content = "Que decepcionante.",
  ui_story_5053_50530402_35_dialog_content = "Por qué...",
  ui_story_5053_50530402_36_dialog_content = "hermana...",
  ui_story_5053_50530402_37_dialog_content = "Mia...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_39_dialog_content = "Sé que podemos rebobinar el tiempo...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_41_dialog_content = "Pero no quiero que pases por esto...",
  ui_story_5053_50530402_42_dialog_content = "Incluso si me odias por alejarte de mí, estaré en paz sabiendo que estás sano y salvo...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>Rugido-!</size>",
  ui_story_5053_50530402_45_dialog_content = "¿Quieres matarme todavía, después de matar a mi familia?",
  ui_story_5053_50530402_46_dialog_content = "Te devolveré el doble del dolor que les has infligido...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>Rugido-!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>¡¡¡Ahora muere!!!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>golpe, golpe...</color>",
  ui_story_5053_50530402_50_dialog_content = "(¡¿Por qué, por qué, por qué?!)",
  ui_story_5053_50530402_51_dialog_content = "(¿Por qué la señora Joshua matar a Caleb, su propio hermano?!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>Ton, ton, ton...</color>",
  ui_story_5053_50530402_53_dialog_content = "(¿Todos en este mundo se han vuelto locos?)",
  ui_story_5053_50530402_54_dialog_content = "(¿O estoy atrapado en una pesadilla interminable?)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>Ton, ton, ton...</color>",
  ui_story_5053_50530402_56_dialog_content = "(¿Se ha ido?)",
  ui_story_5053_50530402_57_dialog_content = "(Pero no puedo esconderme debajo de la mesa para siempre... ¿Qué voy a hacer?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>golpe, golpe.</color>",
  ui_story_5053_50530402_59_dialog_content = "(Los pasos se detuvieron...)",
  ui_story_5053_50530402_60_dialog_content = "¡TE ENCONTRÉ!",
  ui_story_5053_50530402_61_dialog_content = "¡¿Qué?!",
  ui_story_5053_50530402_62_dialog_content = "Oh, querido, ni siquiera Carleen todavía juega al escondite.",
  ui_story_5053_50530402_63_dialog_content = "ya no eres un niño, PlayerName. ¿Cuánto tiempo quieres que siga jugando contigo?",
  ui_story_5053_50530402_64_dialog_content = "Buf... buf...",
  ui_story_5053_50530402_65_dialog_content = "Deja de correr. Eso solo hará que tu muerte sea más agonizante.",
  ui_story_5053_50530402_66_dialog_content = "Mia, Caleb... Su Lumina es agradable. Nunca me había sentido tan vigorizado.",
  ui_story_5053_50530402_67_dialog_content = "Me pregunto qué sucede si tomo Lumina de Caelestite. ¿Tal vez yo también pueda leer la mente de los demás?",
  ui_story_5053_50530402_68_dialog_content = "¡No dejaré que te salgas con la tuya!",
  ui_story_5053_50530402_69_dialog_content = "Bueno, ya puedo controlar a la gente en este mundo.",
  ui_story_5053_50530402_70_dialog_content = "Seguro que hace las cosas simples y fáciles, ¿no es así?",
  ui_story_5053_50530402_71_dialog_content = "Buf... buf...",
  ui_story_5053_50530402_72_dialog_content = "(Solo una puerta delante de mí... ¡Por favor, no dejes que sea un callejón sin salida!)",
  ui_story_5053_50530402_73_dialog_content = "Eso es... Bueno, supongo que es el instinto de The Last Caelestite.",
  ui_story_5053_50530402_74_dialog_content = "Buena selección.",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_77_dialog_content = "Jakine?!",
  ui_story_5053_50530402_78_dialog_content = "Jakine! Su cuerpo está frío y no respira...",
  ui_story_5053_50530402_79_dialog_content = "Seguro que sabes cómo elegir un lugar, PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "La vidente de Northland podía controlar el Cristal, así que, naturalmente, ella fue la primera a la que maté.",
  ui_story_5053_50530402_81_dialog_content = "¿Por qué más le habría pedido que se quedara conmigo?",
  ui_story_5053_50530402_82_dialog_content = "no lo entiendo señora Joshua, ¿Por qué estás haciendo esto?",
  ui_story_5053_50530402_83_dialog_content = "¿Por qué matarías? Jakine y tu hermano... ¿Y yo también?",
  ui_story_5053_50530402_84_dialog_content = "¿Es tan difícil de entender? Necesito tus poderes.",
  ui_story_5053_50530402_85_dialog_content = "No os guardo mala voluntad, pero vuestros sacrificios son necesarios.",
  ui_story_5053_50530402_86_dialog_content = "No entiendo, ¿eres tú el verdadero? Joshua?",
  ui_story_5053_50530402_87_dialog_content = "¿Qué eres, realmente?",
  ui_story_5053_50530402_88_dialog_content = "Soy Joshua, el Real Joshua!",
  ui_story_5053_50530402_89_dialog_content = "Abre bien los ojos y míralo bien. Recuerda esto antes de morir.",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5053_50530402_91_dialog_content = "¿Qué?",
  ui_story_5053_50530402_92_dialog_content = "Ven a mí, PlayerName...",
  ui_story_5053_50530402_93_dialog_content = "Jakine?!",
  ui_story_5053_50530402_94_dialog_content = "¿Estas vivo? Pensé que eras...",
  ui_story_5053_50530402_95_dialog_content = "¿Has olvidado? He sido un adivino errante desde que era pequeño...",
  ui_story_5053_50530402_96_dialog_content = "¿Qué es un pequeño truco? ... (Empieza a toser)",
  ui_story_5053_50530402_97_dialog_content = "Jakine!",
  ui_story_5053_50530402_98_dialog_content = "¿Dónde están los otros?",
  ui_story_5053_50530402_99_dialog_content = "...",
  ui_story_5053_50530402_100_dialog_content = "Maldiciones...!",
  ui_story_5053_50530402_101_dialog_content = "Proyectando ilusiones con la magia de Northland... No es de extrañar que ustedes pudieran crear algo como el Cristal de la Memoria Eterna.",
  ui_story_5053_50530402_102_dialog_content = "Que repugnante inteligencia.",
  ui_story_5053_50530402_103_dialog_content = "Lo siento, siempre he sido un niño travieso.",
  ui_story_5053_50530402_104_dialog_content = "¡Entonces déjame mostrarte algo de disciplina!",
  ui_story_5053_50530402_105_dialog_content = "¡En guardia, bola de cristal!",
  ui_story_5053_50530402_106_dialog_content = "Trae ese Cristal de la Memoria Eterna por aquí, PlayerName.",
  ui_story_5053_50530402_107_dialog_content = "Pon tu mano en él. Incluso si no puedo hacerlo...",
  ui_story_5053_50530402_108_dialog_content = "No debes dejarlo ir.",
  ui_story_5053_50530402_109_dialog_content = "¡Entendido!",
  ui_story_5053_50530402_110_dialog_content = "¡Reditus, reditus, reditus!",
  ui_story_5053_50530402_111_dialog_content = "Rebobinar hasta el principio...",
  ui_story_5053_50530402_112_dialog_content = "Abracadabra—¡Uf!",
  ui_story_5053_50530402_113_dialog_content = "Oh no...",
  ui_story_5053_50530402_114_dialog_content = "Jakine... Jakine—!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>Después del segundo reinicio—</color>",
  ui_story_5053_50530501_1_dialog_content = "Todo está listo, mi señor.",
  ui_story_5053_50530501_2_dialog_content = "El carruaje espera afuera y está listo para partir en cualquier momento.",
  ui_story_5053_50530501_3_dialog_content = "...",
  ui_story_5053_50530501_4_dialog_content = "Mi señor, ¿sigue preocupado por su esposa?",
  ui_story_5053_50530501_5_dialog_content = "Joshua siempre ha gozado de buena salud y por lo general no se quejaría de sentirse mal. Especialmente no en un día como este.",
  ui_story_5053_50530501_6_dialog_content = "Ha estado bastante ocupada últimamente, defendiendo las nuevas políticas a las esposas de los nobles. Imagino que le ha pasado factura.",
  ui_story_5053_50530501_7_dialog_content = "Tenga la seguridad, mi señor. La cuidaré bien.",
  ui_story_5053_50530501_8_dialog_content = "Urgh...",
  ui_story_5053_50530501_9_dialog_content = "Dónde estoy...?",
  ui_story_5053_50530501_10_dialog_content = "Espera, este lugar... ¿Todavía es de día afuera?",
  ui_story_5053_50530501_11_dialog_content = "Me perseguían y me encontré Jakine, entonces...",
  ui_story_5053_50530501_12_dialog_content = "(Gracias por salvarme, Jakine...)",
  ui_story_5053_50530501_13_dialog_content = "(Pero no la veo por aquí... ¿Será que nos separamos, como cuando llegamos por primera vez al Cristal?)",
  ui_story_5053_50530501_14_dialog_content = "(¿Y por qué la señora Joshua atacarnos así? ¿Es posible que ella no fuera la verdadera? Joshua?)",
  ui_story_5053_50530501_15_dialog_content = "(No, ella era <color=#FFB400>una persona real</color>, como el resto de nosotros. Jakine lo probó usando el Cristal de la Memoria Eterna.)",
  ui_story_5053_50530501_16_dialog_content = "Soy Joshua, el Real Joshua.",
  ui_story_5053_50530501_17_dialog_content = "(La forma en que enfatizó su identidad... ¿qué se suponía que significaba eso?)",
  ui_story_5053_50530501_18_dialog_content = "(Estoy tan confundido, pero eso no es importante en este momento. Si algo realmente anda mal con Joshua, ¿cómo se supone que vamos a volver?)",
  ui_story_5053_50530501_19_dialog_content = "(Aaah... Están pasando tantas cosas que no entiendo, ¡¿y por qué soy el único aquí?!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>Pozo, pat, pozo, pat—</color>",
  ui_story_5053_50530501_21_dialog_content = "¡Ese sonido! Es eso...?",
  ui_story_5053_50530501_22_dialog_content = "Aquí...?",
  ui_story_5053_50530501_23_dialog_content = "¿Cómo la oscuridad Angel encontrarnos aquí? ¡Pensé que habíamos reiniciado todo!",
  ui_story_5053_50530501_24_dialog_content = "E-Esa es la voz de mi hermana...",
  ui_story_5053_50530501_25_dialog_content = "... ¡Aquí!",
  ui_story_5053_50530501_26_dialog_content = "¡Noche Blanca, protégenos!",
  ui_story_5053_50530501_27_dialog_content = "¡No pierdas tu enfoque en la batalla, Caleb!",
  ui_story_5053_50530501_28_dialog_content = "¡Aaaah—!",
  ui_story_5053_50530501_29_dialog_content = "¡La Espada del Soberano!",
  ui_story_5053_50530501_30_dialog_content = "Odio...",
  ui_story_5053_50530501_31_dialog_content = "¡Urgh!",
  ui_story_5053_50530501_32_dialog_content = "¡Eso es rápido! Ten cuidado, Señor Schwartz!",
  ui_story_5053_50530501_33_dialog_content = "¿Estás tan desesperado por pelear conmigo uno a uno?",
  ui_story_5053_50530501_34_dialog_content = "Entonces te concederé tu deseo.",
  ui_story_5053_50530501_35_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530501_36_dialog_content = "Mia y los demás están luchando contra esa Oscuridad Angel otra vez... ¡Así que logramos comenzar la memoria de nuevo!",
  ui_story_5053_50530501_37_dialog_content = "¡Tengo que ir allí y ayudarlos!",
  ui_story_5053_50530501_38_dialog_content = "Tú, ahí... Alto.",
  ui_story_5053_50530501_39_dialog_content = "¿Un guardia? ¡Tiempo perfecto! Mira, yo...",
  ui_story_5053_50530501_40_dialog_content = "Sospechar... Exterminar...",
  ui_story_5053_50530501_41_dialog_content = "(¿Eh? ¿Algo parece raro en estas personas?)",
  ui_story_5053_50530501_42_dialog_content = "¿De qué están hablan ustedes dos?",
  ui_story_5053_50530501_43_dialog_content = "Dama Joshua... alguien... intrusos?",
  ui_story_5053_50530501_44_dialog_content = "Intrusos... ¡Deben capturar... y matar!",
  ui_story_5053_50530501_45_dialog_content = "(¡Algo anda definitivamente mal con sus mentes! ¡Son como las personas de la plaza central!)",
  ui_story_5053_50530501_46_dialog_content = "¡¡¡Aaaah!!!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_5053_50530502_2_dialog_content = "Ugh... Tos, tos...",
  ui_story_5053_50530502_3_dialog_content = "¿A dónde fue?",
  ui_story_5053_50530502_4_dialog_content = "Probablemente huyó por un sendero hacia el exterior...",
  ui_story_5053_50530502_5_dialog_content = "Eso fue maravilloso, Señor Schwartz!",
  ui_story_5053_50530502_6_dialog_content = "El ángel debe estar lastimado, tan poderoso como es, y probablemente no pueda ir demasiado lejos.",
  ui_story_5053_50530502_7_dialog_content = "...",
  ui_story_5053_50530502_8_dialog_content = "¿Todavía te preocupa la oscuridad? Angel, ¿Tío?",
  ui_story_5053_50530502_9_dialog_content = "Su voz... No importa, mi hermana nunca podría ser un monstruo.",
  ui_story_5053_50530502_10_dialog_content = "Espera, ¿no nos estamos olvidando de algo? Oh no, ¿dónde está PlayerName?!",
  ui_story_5053_50530502_11_dialog_content = "¡Oye, tienes razón! donde lo hizo PlayerName huir a?!",
  ui_story_5053_50530502_12_dialog_content = "¡Ahí están todos!",
  ui_story_5053_50530502_13_dialog_content = "Uf... ¿Los perdí?",
  ui_story_5053_50530502_14_dialog_content = "Por allí... ¡Por allí!",
  ui_story_5053_50530502_15_dialog_content = "¡Mata al intruso!",
  ui_story_5053_50530502_16_dialog_content = "(¡Mierda! ¡Aunque ahora no tienen sentido, estos guardias son imposibles de sacudir!)",
  ui_story_5053_50530502_17_dialog_content = "No... ¡Justo ahí!",
  ui_story_5053_50530502_18_dialog_content = "(... ¡Espera, lo tengo!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5053_50530502_20_dialog_content = "(¿Qué es este carro, de todos modos? Debe ser para las vacaciones... De cualquier manera, creo que no me verán aquí).",
  ui_story_5053_50530502_21_dialog_content = "No allí... ¿Dónde?",
  ui_story_5053_50530502_22_dialog_content = "Esa calle... Vaya...",
  ui_story_5053_50530502_23_dialog_content = "Esos guardias están actuando de manera tan extraña. ¿Están detrás de alguien?",
  ui_story_5053_50530502_24_dialog_content = "No estoy seguro, pero ¿quién querría causar problemas en un día como este? ¡El desfile también está a punto de comenzar!",
  ui_story_5053_50530502_25_dialog_content = "¡No puedo esperar a verlo!",
  ui_story_5053_50530502_26_dialog_content = "(¡Uf! Finalmente logré perderlos...)",
  ui_story_5053_50530502_27_dialog_content = "(Según esa chica, parece que el desfile aún no ha comenzado).",
  ui_story_5053_50530502_28_dialog_content = "(Bien. Eso me da algo de tiempo para ordenar mis pensamientos y descubrir mi próximo movimiento).",
  ui_story_5053_50530502_29_dialog_content = "(Tengo algunas preguntas serias que considerar ahora mismo...)",
  ui_story_5053_50530502_30_option_content = "La situación actual",
  ui_story_5053_50530502_31_dialog_content = "(El desfile aún no ha comenzado, y todos deberían haber visto a Lady Joshua por ahora.)",
  ui_story_5053_50530502_32_dialog_content = "(Eso significa que hay dos escenarios posibles en este momento, los cuales dependen de <color=#FFB400>si todos recuerdan o no el reinicio de la hora</color>.)",
  ui_story_5053_50530502_33_dialog_content = "(Si todos aún recuerdan, entonces ya deben haber peleado contra Lady Joshua y escapó.)",
  ui_story_5053_50530502_34_dialog_content = "(Si ese es el caso, los demás deberían estar buscándome ahora mismo. Todavía no estoy muy familiarizado con Lumopolis, así que debería mantener la cabeza gacha y esperar a que me encuentren).",
  ui_story_5053_50530502_35_dialog_content = "(Pero si nadie recuerda el reinicio del tiempo, entonces probablemente cayeron en la trampa de Joshua...)",
  ui_story_5053_50530502_36_dialog_content = "(Si es así, entonces todo debería suceder exactamente como sucedió antes del reinicio. Jakine se quedará atrás, y los demás se dirigirán a la plaza central.)",
  ui_story_5053_50530502_37_dialog_content = "(Yo también estoy bastante cerca de la plaza. Parece que lo mejor que puedo hacer es sentarme aquí y esperar a que lleguen todos).",
  ui_story_5053_50530502_38_dialog_content = "(Pero luego hay Jakine... ¡Maldita sea! ¡No podremos rescatarla hasta que lleguen los demás!)",
  ui_story_5053_50530502_39_option_content = "La memoria\"",
  ui_story_5053_50530502_40_dialog_content = "(De acuerdo a Jakine, el uso de la adivinación por cualquier razón requiere una <color=#FFB400>cumplimiento estricto de sus normas</color>.)",
  ui_story_5053_50530502_41_dialog_content = "(Durante el primer reinicio, Jakine seguía diciéndonos que <color=#FFB400>agarrarse fuerte de las manos</color>.)",
  ui_story_5053_50530502_42_dialog_content = "(Joshua También dijo que esta era la razón por la que podía recordar los eventos del primer reinicio. Fue porque ella estaba con nosotros cuando sucedió.)",
  ui_story_5053_50530502_43_dialog_content = "(¿Eso significa que se las arregló para tomar nuestras manos sin que nos diéramos cuenta?)",
  ui_story_5053_50530502_44_dialog_content = "(Durante el segundo reinicio, los únicos que se aferraron al Cristal de la Memoria Eterna fueron Jakine y yo.)",
  ui_story_5053_50530502_45_dialog_content = "(Eso significaría Joshua y los demás no recuerdan el segundo reinicio, ¿verdad?)",
  ui_story_5053_50530502_46_dialog_content = "(Jakine y yo debería ser el único que recuerda todo lo que ha pasado desde que llegamos aquí...)",
  ui_story_5053_50530502_47_dialog_content = "(O al menos eso espero).",
  ui_story_5053_50530502_48_option_content = "El dragón, los soldados y la oscuridad. Angel",
  ui_story_5053_50530502_49_dialog_content = "(¿Cuál fue el trato con esos guardias en este momento? ¿Por qué estaban tratando de capturarme?)",
  ui_story_5053_50530502_50_dialog_content = "(Estaban tan locos como la gente de la plaza central. Es como si hubieran contraído alguna enfermedad misteriosa... O estuvieran siendo controlados mentalmente).",
  ui_story_5053_50530502_51_dialog_content = "(Dado lo decididos que estaban a cazarme, diría que estaban tratando de mantenerme alejado de los demás. Siguieron persiguiéndome, obligándome a abandonar la mansión).",
  ui_story_5053_50530502_52_dialog_content = "(No puedo usar mis poderes psíquicos dentro del Cristal de la memoria eterna, así que no tenía forma de saber qué estaba pasando arriba mientras todos peleaban).",
  ui_story_5053_50530502_53_dialog_content = "(Y terminé perdiendo la oportunidad de reunirme con ellos...)",
  ui_story_5053_50530502_54_dialog_content = "(Si Joshua todavía tiene sus recuerdos, entonces debe haber enviado a esos soldados para silenciarme.)",
  ui_story_5053_50530502_55_dialog_content = "(Pero si no lo hace, entonces debe haberles ordenado que simplemente maten a los rezagados).",
  ui_story_5053_50530502_56_dialog_content = "(Al igual que la primera vez que nos separamos de Jakine.)",
  ui_story_5053_50530502_57_dialog_content = "(Lucha contra la oscuridad Angel debe ser parte de su plan también. De esa manera, ella puede separarnos y acabar con Jakine!)",
  ui_story_5053_50530502_58_dialog_content = "(En este punto, está claro que los guardias que me persiguieron están trabajando para ella...)",
  ui_story_5053_50530502_59_dialog_content = "(Probablemente sea seguro asumir que los locos de la plaza y ese dragón negro también están bajo su control).",
  ui_story_5053_50530502_60_dialog_content = "(Lo que significa que todo lo que pasamos desde el primer reinicio fue parte de su plan... Qué aterrador).",
  ui_story_5053_50530502_61_dialog_content = "(Pero ¿qué pasa con la oscuridad Angel? ¿Cuál es su conexión con Joshua?)",
  ui_story_5053_50530502_62_dialog_content = "(¿Están los dos trabajando juntos? ¿O hay más en la historia que eso...?)",
  ui_story_5053_50530502_63_dialog_content = "(Simplemente no tengo suficiente información para trabajar en este momento).",
  ui_story_5053_50530502_64_dialog_content = "(Suspiro... dicho todo eso, sentarme aquí y esperar a los demás sigue siendo mi mejor curso de acción).",
  ui_story_5053_50530502_65_dialog_content = "(Le diré a todos la verdad una vez que me encuentren, para que podamos ir a salvar Jakine...)",
  ui_story_5053_50530502_66_dialog_content = "(¡Solo espero que estén todos bien!)",
  ui_story_5053_50530601_1_dialog_content = "Así que estás diciendo...",
  ui_story_5053_50530601_2_dialog_content = "Podemos destruir la Oscuridad Angel y traer señora Joshua con nosotros fuera de aquí....",
  ui_story_5053_50530601_3_dialog_content = "... o la oscuridad Angel nos mata y se suelta en el mundo real?",
  ui_story_5053_50530601_4_dialog_content = "Eso es correcto, si.",
  ui_story_5053_50530601_5_dialog_content = "...",
  ui_story_5053_50530601_6_dialog_content = "Entiendo perfectamente bien nuestro plan de escape, pero...",
  ui_story_5053_50530601_7_dialog_content = "Dónde es PlayerName? Realmente estoy empezando a preocuparme por él.",
  ui_story_5053_50530601_8_dialog_content = "Ha estado separado de nosotros durante demasiado tiempo. ¡Algo debe haberle pasado!",
  ui_story_5053_50530601_9_dialog_content = "No estoy seguro de su situación actual, pero no te preocupes, enviaré un equipo de guardias para buscarlo.",
  ui_story_5053_50530601_10_dialog_content = "Nos estamos quedando sin tiempo. Si deseamos escapar de este lugar con seguridad, la prioridad es derrotar a ese monstruo.",
  ui_story_5053_50530601_11_dialog_content = "Entonces vamos a cazar a esa Oscuridad Angel!",
  ui_story_5053_50530601_12_dialog_content = "No, Jakine. Tienes que quedarte aquí conmigo.",
  ui_story_5053_50530601_13_dialog_content = "¿Eh? Pero ¿cómo es que? ¡Mi bola de cristal también es bastante útil en una pelea!",
  ui_story_5053_50530601_14_dialog_content = "Sí, lo sé, pero tú manejas el Cristal.",
  ui_story_5053_50530601_15_dialog_content = "Si los demás resultan heridos, siempre podemos retroceder el tiempo para restaurar todo.",
  ui_story_5053_50530601_16_dialog_content = "Pero si te llegara a pasar algo, sería irreversible.",
  ui_story_5053_50530601_17_dialog_content = "S-Si tu lo dices...",
  ui_story_5053_50530601_18_dialog_content = "¿Madre? yo-si tu y Jakine se van a quedar aquí, entonces Carleen debería volver también.",
  ui_story_5053_50530601_19_dialog_content = "No quiero que ella y mi padre se sientan solos sin nosotros allí.",
  ui_story_5053_50530601_20_dialog_content = "Muy bien. Haré que un guardia la llame a su habitación para que descanse un poco.",
  ui_story_5053_50530601_21_dialog_content = "¿No la quieres aquí con nosotros, madre? Ha estado esperando este día durante tanto tiempo, ¿por qué enviarla de regreso a su habitación sola?",
  ui_story_5053_50530601_22_dialog_content = "¿No se sentirá mal si se pierde el desfile...?",
  ui_story_5053_50530601_23_dialog_content = "Mi dulce Vonnie... Nada de esto es real. El mundo dentro del Cristal de la Memoria Eterna no es más que una ilusión.",
  ui_story_5053_50530601_24_dialog_content = "Debemos seguir el curso predeterminado de los acontecimientos. No dejes que preocupaciones innecesarias te distraigan de tu objetivo.",
  ui_story_5053_50530601_25_dialog_content = "Oh...",
  ui_story_5053_50530601_26_dialog_content = "mi hermana tiene razon Mia. Todo esto es una fantasía, así que no dejes que tus emociones te superen.",
  ui_story_5053_50530601_27_dialog_content = "A-Muy bien. Lo siento por ser tan inmaduro...",
  ui_story_5053_50530601_28_dialog_content = "...",
  ui_story_5053_50530601_29_dialog_content = "Joshua hace un punto válido. La seguridad de todos debería ser nuestra máxima prioridad, por lo que Caleb también debería quedarse aquí.",
  ui_story_5053_50530601_30_dialog_content = "voy a buscar PlayerName mí mismo. Por ahora, todos los demás deben permanecer juntos.",
  ui_story_5053_50530601_31_dialog_content = "Eso no será necesario. Un equipo de guardias puede encontrar PlayerName con la misma rapidez, si no más.",
  ui_story_5053_50530601_32_dialog_content = "Además, necesitamos la fuerza de todos si esperamos tener una oportunidad contra ese monstruo.",
  ui_story_5053_50530601_33_dialog_content = "Creo que sabes tan bien como yo cuál de estos asuntos es más importante. Usa tu sentido común, Daniel.",
  ui_story_5053_50530601_34_dialog_content = "Je, tu juicio es tan agudo como siempre, Joshua. Debo decir que esto realmente me lleva de vuelta a nuestros viejos tiempos.",
  ui_story_5053_50530601_35_dialog_content = "...",
  ui_story_5053_50530601_36_dialog_content = "¿Es este realmente un buen momento para la nostalgia, ustedes dos? Todavía estamos en una carrera contrarreloj.",
  ui_story_5053_50530601_37_dialog_content = "En cualquier caso, soy perfectamente capaz de sopesar las opciones por mí mismo.",
  ui_story_5053_50530601_38_dialog_content = "Vamos, Mia.",
  ui_story_5053_50530601_39_dialog_content = "S-Sí, padre.",
  ui_story_5053_50530601_40_dialog_content = "¡¿Qué pasa con ese hombre, actuando tan extraño de repente?!",
  ui_story_5053_50530601_41_dialog_content = "...",
  ui_story_5053_50530601_42_dialog_content = "es algo sobre Joshua molestándote, Mia?",
  ui_story_5053_50530601_43_dialog_content = "¡Ay! Um, bueno... M-Tal vez un poco...",
  ui_story_5053_50530601_44_dialog_content = "Probablemente sea solo yo, pero... después de estar lejos de ella durante tanto tiempo, mamá se siente un poco desconocida.",
  ui_story_5053_50530601_45_dialog_content = "Dime, ¿qué tipo de persona es Joshua ¿A usted?",
  ui_story_5053_50530601_46_dialog_content = "M-Madre es... Madre es la persona más amable y paciente que he conocido, y ama a los niños más que a nada.",
  ui_story_5053_50530601_47_dialog_content = "Sí el Joshua en mi corazón también hay una mujer cálida y de buen corazón, una de las personas más firmes y sinceras que he conocido.",
  ui_story_5053_50530601_48_dialog_content = "Padre...!",
  ui_story_5053_50530601_49_dialog_content = "Creer en ti mismo, Mia. Y cree en la hermosa imagen de tu madre que guardas en tu corazón.",
  ui_story_5053_50530601_50_dialog_content = "¿Cree en mi?",
  ui_story_5053_50530601_51_dialog_content = "A pesar de tu torpeza habitual, has mostrado un lado más fuerte y valiente de ti mismo a lo largo de esta prueba.",
  ui_story_5053_50530601_52_dialog_content = "Creo que es hora de que acepte que has crecido.",
  ui_story_5053_50530601_53_dialog_content = "De ahora en adelante, prometo respetar tus opiniones en lugar de decirte cómo te sientes.",
  ui_story_5053_50530601_54_dialog_content = "No hay necesidad de dudar más, Mia. Ya sea que tenga que ver con tu madre, o Carleen, O algo más...",
  ui_story_5053_50530601_55_dialog_content = "Haz lo que creas que es correcto, y hazlo con valentía. Siempre tendré fe en ti.",
  ui_story_5053_50530601_56_dialog_content = "(¿Padre... me está animando?)",
  ui_story_5053_50530601_57_dialog_content = "(Nunca lo había escuchado decir algo así antes. Se siente... agradable).",
  ui_story_5053_50530601_58_dialog_content = "Gracias Padre. Prometo ser más decisivo a partir de ahora.",
  ui_story_5053_50530601_59_dialog_content = "Estaré en el estrado para vigilar, tal como lo planeamos. Si veo alguna señal de la Oscuridad Angel, se lo haré saber a todo el mundo.",
  ui_story_5053_50530601_60_dialog_content = "Bien. Estar en guardia, Mia.",
  ui_story_5053_50530601_61_dialog_content = "(Mia debería estar a salvo allí por el momento. PlayerName, por otro lado... ¿Dónde podría estar ahora mismo?)",
  ui_story_5053_50530601_62_dialog_content = "(Su ausencia se siente extremadamente sospechosa ahora, pero ¿por qué...?)",
  ui_story_5053_50530601_63_dialog_content = "Aqui...",
  ui_story_5053_50530601_64_dialog_content = "... ¡Aquí!",
  ui_story_5053_50530601_65_dialog_content = "Esa voz.",
  ui_story_5053_50530601_66_dialog_content = "Sch... Schwartz...!!!",
  ui_story_5053_50530601_67_dialog_content = "¡¡¡Aaaaaah!!!",
  ui_story_5053_50530601_68_dialog_content = "Así que aquí es donde has estado.",
  ui_story_5053_50530601_69_dialog_content = "Bien. Mientras estés aquí, nadie más está en peligro.",
  ui_story_5053_50530601_70_dialog_content = "¡Duele! ¡¡¡Muere muere!!!",
  ui_story_5053_50530601_71_dialog_content = "No me engañarás haciéndote pasar por Joshua.",
  ui_story_5053_50530701_1_dialog_content = "Urgh... ¡Aaaaah!",
  ui_story_5053_50530701_2_dialog_content = "(Sin Mia o Caleb aquí, parece que estamos igualados. Desafortunadamente, estos eclipses están inclinando la balanza ligeramente a su favor).",
  ui_story_5053_50530701_3_dialog_content = "\"¡Noche Blanca, protégenos!\"",
  ui_story_5053_50530701_4_dialog_content = "Yo diría que hemos llegado a un punto muerto. ¿Estás satisfecho ahora?",
  ui_story_5053_50530701_5_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530701_6_dialog_content = "Te odio...!",
  ui_story_5053_50530701_7_dialog_content = "Por qué...",
  ui_story_5053_50530701_8_dialog_content = "¡Duele mucho! ¡¿Por qué... por qué... traicionarme?!",
  ui_story_5053_50530701_9_dialog_content = "Dijiste... ¡Construimos... un futuro juntos! Prometiste...!",
  ui_story_5053_50530701_10_dialog_content = "Entonces, ¿por qué... sacrificar... familia?",
  ui_story_5053_50530701_11_dialog_content = "El dolor... es insoportable!!!",
  ui_story_5053_50530701_12_dialog_content = "¿Qué estás diciendo?",
  ui_story_5053_50530701_13_dialog_content = "Si tan solo... Si tan solo supiera...",
  ui_story_5053_50530701_14_dialog_content = "Yo nunca... amaría...",
  ui_story_5053_50530701_15_dialog_content = "Y... te eligió a ti!!!",
  ui_story_5053_50530701_16_dialog_content = "¡¿?!",
  ui_story_5053_50530701_17_dialog_content = "Joshua...?!",
  ui_story_5053_50530701_18_dialog_content = "Pero, ¿cómo podría ser esto?",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "Ah...! METRO... Mia... peligro...",
  ui_story_5053_50530701_21_dialog_content = "¡¿A dónde crees que vas?!",
  ui_story_5053_50530701_22_dialog_content = "Graah-!",
  ui_story_5053_50530701_23_dialog_content = "¡Fuera de mi camino, criaturas repugnantes!",
  ui_story_5053_50530701_24_dialog_content = "(Joven Schwartz acaba de terminar su discurso, lo que significa que el duelo está por comenzar.)",
  ui_story_5053_50530701_25_dialog_content = "(Si todo sale como se espera, el dragón aparecerá pronto y la gente entrará en pánico, junto con los guardias...)",
  ui_story_5053_50530701_26_dialog_content = "(¡Una vez que eso suceda, puedo aprovechar el caos y correr al estrado! Tengo que reunirme con los demás y contarles sobre Joshua ¡Antes de que sea demasiado tarde!)",
  ui_story_5053_50530701_27_dialog_content = "Rugido-!",
  ui_story_5053_50530701_28_dialog_content = "¡¡¡Aaaah!!!",
  ui_story_5053_50530701_29_dialog_content = "¡¿Q-Qué es esa cosa?!",
  ui_story_5053_50530701_30_dialog_content = "¡Correr! ¡¡¡Ayúdame!!!",
  ui_story_5053_50530701_31_dialog_content = "¡Está bien! Ahora es mi oportunidad de buscar al Señor Schwartz y los otros-",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5053_50530701_33_dialog_content = "¡Guau...! ¡¿Q-Qué fue eso?!",
  ui_story_5053_50530701_34_dialog_content = "Rugido-!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>¡¡¡BOOM!!!</color>",
  ui_story_5053_50530701_36_dialog_content = "¡Aaaah...! ¡¡¡Urgh!!!",
  ui_story_5053_50530701_37_dialog_content = "La oscuridad Angel?! ¡¿Qué está sucediendo?!",
  ui_story_5053_50530701_38_dialog_content = "¿Qué está haciendo ella en el cielo? ¿Está bloqueando el ataque del dragón?",
  ui_story_5053_50530701_39_dialog_content = "¿Un dragón volador?",
  ui_story_5053_50530701_40_dialog_content = "¡Viva el dragón! ¡¡¡Viva el dragón!!!",
  ui_story_5053_50530701_41_dialog_content = "¿Casa Kartima? ¿Así que ellos son los traidores todo el tiempo?",
  ui_story_5053_50530701_42_dialog_content = "Qué audaces de su parte mostrar sus verdaderos colores en un momento como este.",
  ui_story_5053_50530701_43_dialog_content = "(¿Pero qué es ese otro monstruo en el cielo...?)",
  ui_story_5053_50530701_44_dialog_content = "¡H-hermana! ¿Lo que está sucediendo?",
  ui_story_5053_50530701_45_dialog_content = "¡Ponte detrás de mí, Carleen!",
  ui_story_5053_50530701_46_dialog_content = "(Es la oscuridad Angel! Pero ¿por qué está ella aquí?)",
  ui_story_5053_50530701_47_dialog_content = "¡¿Qué diablos es...?!",
  ui_story_5053_50530701_48_dialog_content = "¡Verónica! Carleen! ¡Quedarse atrás!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>Aplastar-!</color>",
  ui_story_5053_50530701_50_dialog_content = "(¡Fue golpeada por las llamas del dragón! No, espera... ¡Parece que está bloqueando sus ataques!)",
  ui_story_5053_50530701_51_dialog_content = "Pero ¿por qué ella...",
  ui_story_5053_50530701_52_dialog_content = "¡Veronica, parece que nos está ayudando a defendernos del dragón!",
  ui_story_5053_50530701_53_dialog_content = "¿P-Perdió el conocimiento?",
  ui_story_5053_50530701_54_dialog_content = "La oscuridad Angel... No entiendo...",
  ui_story_5053_50530701_55_dialog_content = "Mia!!!",
  ui_story_5053_50530701_56_dialog_content = "¡Mia! ¡¿Estás bien?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? ¡Estoy bien, no te preocupes! ¿Dónde has estado todo este tiempo?",
  ui_story_5053_50530701_58_dialog_content = "¡A-Aquí...!",
  ui_story_5053_50530701_59_dialog_content = "Mata... ¡Mata al intruso!",
  ui_story_5053_50530701_60_dialog_content = "¡Maldita sea! ¡No ellos otra vez!",
  ui_story_5053_50530701_61_dialog_content = "¡¿Qué les pasa a esos guardias?!",
  ui_story_5053_50530701_62_dialog_content = "¡Viva el dragón! ¡¡¡Viva el dragón!!!",
  ui_story_5053_50530701_63_dialog_content = "¡Ataque!",
  ui_story_5053_50530701_64_dialog_content = "Estar atento, PlayerName! ¡Los rebeldes también se unen a la lucha!",
  ui_story_5053_50530701_65_dialog_content = "Tendré que explicar las cosas más tarde, Mia. ¡En este momento, debemos prepararnos para la pelea!",
  ui_story_5053_50530701_66_dialog_content = "¡No importa cuántos monstruos voladores o escoria traidora decidan mostrar sus rostros hoy! A nombre de Casa Schwartz¡Todos ustedes serán castigados por arruinar este día!",
  ui_story_5053_50530701_67_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5053_50530701_68_dialog_content = "¡Ten cuidado! deja la oscuridad Angel sola por el momento.",
  ui_story_5053_50530701_69_dialog_content = "Nuestro enemigo es diferente que antes. No esperes vencerlo tan fácilmente.",
  ui_story_5053_50530701_70_dialog_content = "Y tú quién eres...?",
  ui_story_5053_50530701_71_dialog_content = "¡Enfoca tus ataques en el dragón y ayúdame a derribarlo!",
  ui_story_5053_50530701_72_dialog_content = "Hmph. Incluso un dragón volador no es rival para mí.",
  ui_story_5053_50530701_73_dialog_content = "¡Luz de la Noche Blanca!",
  ui_story_5053_50530701_74_dialog_content = "Rugido-!!!",
  ui_story_5053_50530701_75_dialog_content = "¡¿Qué?! ¡Perforé su garganta, pero sanó casi instantáneamente!",
  ui_story_5053_50530701_76_dialog_content = "Regeneración rápida... o algún tipo de invulnerabilidad.",
  ui_story_5053_50530701_77_dialog_content = "¿Pero cómo? ¿Quién podría haberle otorgado este tipo de poder? ¿Podría ser esto obra de Mime?",
  ui_story_5053_50530701_78_dialog_content = "...",
  ui_story_5053_50530701_79_dialog_content = "¡En guardia! ¡Se está preparando para atacar de nuevo!",
  ui_story_5053_50530801_1_dialog_content = "Buf... buf...",
  ui_story_5053_50530801_2_dialog_content = "Mata... Mata a los intrusos... ¡Mátalos a todos!",
  ui_story_5053_50530801_3_dialog_content = "¡Ahhh! ¡¡¡Matarlos a todos!!!",
  ui_story_5053_50530801_4_dialog_content = "¡Tonterías! ¡¿Por qué aparecen cada vez más de estos guardias locos?! ¿Todavía puedes pelear? Mia?",
  ui_story_5053_50530801_5_dialog_content = "Estos tipos son horribles... ¡Sus ojos están completamente blancos y sus caras están todas contorsionadas!",
  ui_story_5053_50530801_6_dialog_content = "Estoy bien, ¡pero el número de enemigos solo está creciendo!",
  ui_story_5053_50530801_7_dialog_content = "Las personas que huían hace un momento se han unido a sus filas... ¡Incluso los rebeldes caídos están de su lado!",
  ui_story_5053_50530801_8_dialog_content = "Es como una especie de plaga...",
  ui_story_5053_50530801_9_dialog_content = "Mantén tu distancia de ellos, Mia! ¡Lo que sea que los controle parece propagarse a través de sus ataques!",
  ui_story_5053_50530801_10_dialog_content = "¡Pero no duraremos mucho más a este ritmo...!",
  ui_story_5053_50530801_11_dialog_content = "¿Es esto parte de su plan también? Caballero Schwartz, ¡necesitamos ayuda!",
  ui_story_5053_50530801_12_dialog_content = "¡Padre está demasiado ocupado luchando contra el dragón!",
  ui_story_5053_50530801_13_dialog_content = "(Padre... ¿Qué debo hacer?)",
  ui_story_5053_50530801_14_dialog_content = "No hay necesidad de dudar más, Mia. Ya sea que tenga que ver con tu madre, o Carleen, O algo más...",
  ui_story_5053_50530801_15_dialog_content = "Haz lo que creas que es correcto, y hazlo con valentía. Siempre tendré fe en ti.",
  ui_story_5053_50530801_16_dialog_content = "(Creer en ti mismo, Mia! ¡Confía en tu juicio!)",
  ui_story_5053_50530801_17_dialog_content = "¡Hipoca—!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>¡¡¡BOOM!!!</color>",
  ui_story_5053_50530801_19_dialog_content = "¡E-Tan poderoso!",
  ui_story_5053_50530801_20_dialog_content = "Hipoca! Gracias... ¡Gracias por responder a mi llamada! ¡Te prometo que nunca más te abandonaré!",
  ui_story_5053_50530801_21_dialog_content = "Eso fue increible, Mia! ¡Eliminaste a todos y cada uno de esos guardias infectados de una sola vez!",
  ui_story_5053_50530801_22_dialog_content = "¡Me alegro de que haya funcionado! ¡Vamos, vamos a ayudar a mi padre!",
  ui_story_5053_50530801_23_dialog_content = "Mia... Esperar...",
  ui_story_5053_50530801_24_dialog_content = "Jadeo, jadeo, jadeo...",
  ui_story_5053_50530801_25_dialog_content = "V-Verónica...",
  ui_story_5053_50530801_26_dialog_content = "C-Carleen, tu cabeza esta sangrando!!",
  ui_story_5053_50530801_27_dialog_content = "¿Alguno de esos guardias logró lastimarte? Carleen? ¿Significa eso que ella...?",
  ui_story_5053_50530801_28_dialog_content = "Aléjate de ella, Mia! ¡¡Sus ojos están empezando a ponerse blancos, al igual que los demás!!",
  ui_story_5053_50530801_29_dialog_content = "Ven aquí, Carleen... Sólo baja la lanza, ¿quieres?",
  ui_story_5053_50530801_30_dialog_content = "¿Por favor?",
  ui_story_5053_50530801_31_dialog_content = "...",
  ui_story_5053_50530801_32_dialog_content = "Verónica... Me duele...",
  ui_story_5053_50530801_33_dialog_content = "no tengas miedo, Carleen. Deja tu arma y déjame vendar tus heridas, ¿de acuerdo?",
  ui_story_5053_50530801_34_dialog_content = "¡No! ¡Me duele la cabeza...!",
  ui_story_5053_50530801_35_dialog_content = "Hay una voz extraña... ¡Sigue diciéndome que te mate! ¡No, no lo haré!",
  ui_story_5053_50530801_36_dialog_content = "Sé que no lo harás Carleen. ¡Te protegeré, así que no tengas miedo!",
  ui_story_5053_50530801_37_dialog_content = "¡¡Quedarse atrás!!",
  ui_story_5053_50530801_38_dialog_content = "Yo soy Carleen Delaware Schwartz... Hija orgullosa de House Schwartz, y defensor de Lumopolis...",
  ui_story_5053_50530801_39_dialog_content = "¡Y nunca lastimaré a nadie en mi familia! ¡Nunca!",
  ui_story_5053_50530801_40_dialog_content = "¡Urgh! ¡No quiero lastimarte, Verónica! Es por eso...",
  ui_story_5053_50530801_41_dialog_content = "Tengo que poner fin a esto, aquí y ahora... Lo siento, hermana... Adiós.",
  ui_story_5053_50530801_42_dialog_content = "no lo hagas, Carleen! Baja tu arma!!",
  ui_story_5053_50530801_43_dialog_content = "¡¡¡Carleen!!!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530801_45_dialog_content = "Se atravesó el cuello con su propia lanza...",
  ui_story_5053_50530801_46_dialog_content = "Carleen... Como pudiste...",
  ui_story_5053_50530801_47_dialog_content = "...",
  ui_story_5053_50530801_48_dialog_content = "No no...!",
  ui_story_5053_50530801_49_dialog_content = "Aaaaaahhhh!!!!",
  ui_story_5053_50530801_50_dialog_content = "Carleen!! ¡¡¡Nooooooo!!!",
  ui_story_5053_50530801_51_dialog_content = "Animarse, Mia! Esto no es real, ¿recuerdas? El Carleen en este mundo es sólo una ilusión!",
  ui_story_5053_50530801_52_dialog_content = "no quiero perderte, Carleen!!! Por favor... no me dejes solo... por favor, Carleen...",
  ui_story_5053_50530801_53_dialog_content = "Cálmate, Mia! ¡¿Me estás escuchando?! ¡¡Ey!!",
  ui_story_5053_50530801_54_dialog_content = "(Mia está demasiado angustiada para escucharme... ¡¿No me digas que va a perder el control otra vez?!)",
  ui_story_5053_50530801_55_dialog_content = "¡¡¡Waaaaaaah!!!",
  ui_story_5053_50530801_56_dialog_content = "¡¡¡Eso es caliente!!!",
  ui_story_5053_50530801_57_dialog_content = "¡¡El poder de Mia está a punto de volverse loco!!",
  ui_story_5053_50530801_58_dialog_content = "...",
  ui_story_5053_50530801_59_dialog_content = "¡¿Q-Qué crees que estás haciendo...?!",
  ui_story_5053_50530801_60_dialog_content = "no llores...",
  ui_story_5053_50530801_61_dialog_content = "No llores... Mi dulce, pequeña... Vonnie...",
  ui_story_5053_50530801_62_dialog_content = "Todo va a estar bien...",
  ui_story_5053_50530801_63_dialog_content = "Ah...",
  ui_story_5053_50530801_64_dialog_content = "Elige una rosa... solo para mi bebé... ♪",
  ui_story_5053_50530801_65_dialog_content = "La brisa en tu rostro... tu sonrisa es todo lo que necesito... ♪",
  ui_story_5053_50530801_66_dialog_content = "Escoge un ramo de rosas... para mi querido padre y madre... ♪",
  ui_story_5053_50530801_67_dialog_content = "Aunque el mundo pueda cambiar... Nuestro amor siempre será el mismo... ♪",
  ui_story_5053_50530801_68_dialog_content = "Vonnie... Mira... Es mami...",
  ui_story_5053_50530801_69_dialog_content = "¿M-Madre...? ¡Madre!",
  ui_story_5053_50530801_70_dialog_content = "Waaaaaaaaah!!!",
  ui_story_5053_50530801_71_dialog_content = "¡Madre! Es Carleen... Ella es...",
  ui_story_5053_50530801_72_dialog_content = "Sus manos... sus manos eran tan cálidas... y ahí está su sangre...",
  ui_story_5053_50530801_73_dialog_content = "Madre... por favor...",
  ui_story_5053_50530801_74_dialog_content = "Esto es... solo un mal sueño...",
  ui_story_5053_50530801_75_dialog_content = "Mi pequeño Vonnie... Todo esto es... solo un mal sueño...",
  ui_story_5053_50530801_76_dialog_content = "Puedes llorar... si quieres...",
  ui_story_5053_50530801_77_dialog_content = "Mami... está aquí...",
  ui_story_5053_50530801_78_dialog_content = "...",
  ui_story_5053_50530801_79_dialog_content = "Su cálido abrazo... y esa canción de cuna de hace un momento...",
  ui_story_5053_50530801_80_dialog_content = "Realmente eres tú, madre...",
  ui_story_5053_50530801_81_dialog_content = "Te he extrañado mucho...",
  ui_story_5053_50530801_82_dialog_content = "Como yo... mi amor...",
  ui_story_5053_50530801_83_dialog_content = "(La oscuridad Angel... Ella es reconfortante Mia?!)",
  ui_story_5053_50530801_84_dialog_content = "(¡Pero pensé que ella era solo un monstruo sin sentido! No, espera... Joshua fue quien dijo eso, y no se puede confiar en nada de lo que dice).",
  ui_story_5053_50530801_85_dialog_content = "... Estás bien, Mia? ¿Todavía puedes estar de pie?",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... Lo siento, no pude controlarme en este momento.",
  ui_story_5053_50530801_87_dialog_content = "No te lastimé, ¿verdad...?",
  ui_story_5053_50530801_88_dialog_content = "¡Por supuesto que no! ¿Ver? Estoy perfectamente bien, y parece que tú también estás bien.",
  ui_story_5053_50530801_89_dialog_content = "Entonces, ¿cuál es el trato con este oscuro? Angel? Estoy completamente perdido ahora...",
  ui_story_5053_50530801_90_dialog_content = "Ella es mi madre, de eso no hay duda.",
  ui_story_5053_50530801_91_dialog_content = "Estás diciendo que esta es la verdadera Dama Joshua...?!",
  ui_story_5053_50530801_92_dialog_content = "Sé que es difícil de entender, pero mi corazón me dice que ella es mi verdadera madre...",
  ui_story_5053_50530801_93_dialog_content = "El otro nos dijo que la Oscuridad Angel no tiene conciencia y solo existe para destruir... Pero su abrazo de hace un momento me dijo lo contrario.",
  ui_story_5053_50530801_94_dialog_content = "En cuanto a la Madre que conocimos en la mansión, siempre he sentido algo extraño en ella...",
  ui_story_5053_50530801_95_dialog_content = "... No, lo entiendo completamente. De hecho, esto respondería muchas preguntas.",
  ui_story_5053_50530801_96_dialog_content = "¿Eh? Qué quieres decir, PlayerName?",
  ui_story_5053_50530801_97_dialog_content = "No hay suficiente tiempo para explicar en este momento. Jakine está en grave peligro y tenemos que ir a salvarla.",
  ui_story_5053_50530801_98_dialog_content = "¡Te contaré más en el camino!",
  ui_story_5053_50530801_99_dialog_content = "Jakine? No creo que tengas nada de qué preocuparte. Después de todo, el tío Caleb está con ella.",
  ui_story_5053_50530801_100_dialog_content = "¿Caleb está con ella?",
  ui_story_5053_50530801_101_dialog_content = "Así es. Padre le dijo que se quedara atrás, pero no estoy del todo seguro de por qué.",
  ui_story_5053_50530801_102_dialog_content = "Cualesquiera que sean sus razones, no hará la diferencia con solo Caleb allí.",
  ui_story_5053_50530801_103_dialog_content = "El Joshua de la mansión está conspirando para matar a cada uno de nosotros. No se puede confiar en ella.",
  ui_story_5053_50530801_104_dialog_content = "¡¿De qué estás hablando?!",
  ui_story_5053_50530801_105_dialog_content = "Esta no es la primera vez que todo esto sucede, Mia!",
  ui_story_5053_50530801_106_dialog_content = "!!!",
  ui_story_5053_50530801_107_dialog_content = "Caleb... Peligro...",
  ui_story_5053_50530801_108_dialog_content = "M... Mi hermano... Caleb...",
  ui_story_5053_50530801_109_dialog_content = "Hermano... peligro...",
  ui_story_5053_50530801_110_dialog_content = "Entonces, ¿estás diciendo que ocurrió otro reinicio después del primero?",
  ui_story_5053_50530801_111_dialog_content = "¡Entonces tenemos que encontrar a mi padre y regresar de inmediato!",
  ui_story_5053_50530801_112_dialog_content = "¡Padre!",
  ui_story_5053_50530801_113_dialog_content = "Caballero Schwartz, Caleb y Jakine están en grave peligro! ¡Date prisa, te explicaré todo en el camino!",
  ui_story_5053_50530801_114_dialog_content = "Sch... Schwartz...",
  ui_story_5053_50530801_115_dialog_content = "... Parece que las cosas son más complicadas de lo que había imaginado.",
  ui_story_5053_50530801_116_dialog_content = "Desafortunadamente, no tengo forma de irme de este lugar ahora mismo.",
  ui_story_5053_50530801_117_dialog_content = "El dragón cura inmediatamente cualquier herida que le hayan infligido, incluso las más graves.",
  ui_story_5053_50530801_118_dialog_content = "Solo puedo describir este rasgo ominoso como un tipo de invulnerabilidad.",
  ui_story_5053_50530801_119_dialog_content = "Uno que solo dentro del mundo creado por el Cristal de la Memoria Eterna.",
  ui_story_5053_50530801_120_dialog_content = "Pero, ¿cómo podría ser esto...?",
  ui_story_5053_50530801_121_dialog_content = "creo que el otro Joshua debe tener algo que ver. Caballero Schwartz, ¿puedes seguir defendiéndote del dragón por el momento?",
  ui_story_5053_50530801_122_dialog_content = "Joshua... Muy bien entonces. Dejaré el resto en tus manos.",
  ui_story_5053_50530801_123_dialog_content = "¿Verónica? ¡¿Por qué no te refugias del dragón?! Y quienes son esas personas...?",
  ui_story_5053_50530801_124_dialog_content = "...",
  ui_story_5053_50530801_125_dialog_content = "Padre... Tengo algo urgente que hacer en la mansión. Por favor, no intentes detenerme.",
  ui_story_5053_50530801_126_dialog_content = "Nada podría ser más urgente que nuestra situación actual, Veronica.",
  ui_story_5053_50530801_127_dialog_content = "Es más, te prohíbo que te involucres con estos extraños.",
  ui_story_5053_50530801_128_dialog_content = "Difícilmente nos considero extraños, Señor de la Ciudad, dado que hemos estado luchando en el mismo bando desde hace algún tiempo.",
  ui_story_5053_50530801_129_dialog_content = "Este no es el momento ni el lugar para demandas paternalistas.",
  ui_story_5053_50530801_130_dialog_content = "...",
  ui_story_5053_50530801_131_dialog_content = "Tengan la seguridad, como aliados de Verónica, PlayerName y juro protegerla a toda costa.",
  ui_story_5053_50530801_132_dialog_content = "Tienes la obligación de proteger a la gente de Lumopolis, y ahora te necesitan más que nunca.",
  ui_story_5053_50530801_133_dialog_content = "Suficiente. Mi socia, la Sra. Rot, es más que capaz de defender a mi familia, y mi esposa tampoco es ajena al combate. Difícilmente necesitamos protección exterior, y mucho menos de completos extraños.",
  ui_story_5053_50530801_134_dialog_content = "Además, no tengo motivos para confiar en un grupo que considera a un monstruo como uno de los suyos.",
  ui_story_5053_50530801_135_dialog_content = "...",
  ui_story_5053_50530801_136_dialog_content = "Esto no es un monstruo, de eso puedes estar seguro. Ella es mi esposa.",
  ui_story_5053_50530801_137_dialog_content = "¡¿Qué...?!",
  ui_story_5053_50530801_138_dialog_content = "¡...!",
  ui_story_5053_50530801_139_dialog_content = "(¡El padre también cree que ella es la verdadera madre!)",
  ui_story_5053_50530801_140_dialog_content = "Ejem... Debo decir que tus gustos son únicos.",
  ui_story_5053_50530801_141_dialog_content = "Entonces dejémoslo así.",
  ui_story_5053_50530801_142_dialog_content = "No hay tiempo que perder. Mia, PlayerName, el resto depende de usted. ¡Ahora ve!",
  ui_story_5053_50530801_143_dialog_content = "¡Sí!",
  ui_story_5053_50530801_144_dialog_content = "Caleb...",
  ui_story_5053_50530801_145_dialog_content = "¿Quieres venir también, madre?",
  ui_story_5053_50530801_146_dialog_content = "Protege... a Caleb...",
  ui_story_5053_50530801_147_dialog_content = "Entiendo. ¡Lo haremos juntos, ahora vamos!",
  ui_story_5053_50530901_1_dialog_content = "¿Cómo se ve afuera, Caleb?",
  ui_story_5053_50530901_2_dialog_content = "Tengo un mal presentimiento sobre ese rugido que escuchamos antes.",
  ui_story_5053_50530901_3_dialog_content = "Acordado. Por alguna razón, el dragón apareció mucho antes de lo esperado.",
  ui_story_5053_50530901_4_dialog_content = "La plaza central debería estar en completo desorden en este momento.",
  ui_story_5053_50530901_5_dialog_content = "Entonces, ¿eso no significaría que todos están en peligro en este momento?",
  ui_story_5053_50530901_6_dialog_content = "Caballero Schwartz, Mia, y PlayerName, que todavía no ha aparecido por ningún lado...",
  ui_story_5053_50530901_7_dialog_content = "No es para preocuparse. Estoy seguro de que Daniel puede con todo.",
  ui_story_5053_50530901_8_dialog_content = "En cuanto a nosotros... Bien, llegaste justo a tiempo.",
  ui_story_5053_50530901_9_dialog_content = "...",
  ui_story_5053_50530901_10_dialog_content = "¿Ver? Mi hermana siempre ha sido de las que piensan en el futuro y se preparan.",
  ui_story_5053_50530901_11_dialog_content = "Tú y los demás estáis a salvo, Jakine. Prometo.",
  ui_story_5053_50530901_12_dialog_content = "Bien...",
  ui_story_5053_50530901_13_dialog_content = "Ahora bien, ¿serías tan amable de cerrar la puerta para nosotros? Jakine?",
  ui_story_5053_50530901_14_dialog_content = "¡Oh, por supuesto! ¡Después de todo, incluso una simple cerradura puede hacer maravillas por nuestra seguridad!",
  ui_story_5053_50530901_15_dialog_content = "Déjame hacerte una pregunta, Caleb. ¿Por qué quieres rescatarme?",
  ui_story_5053_50530901_16_dialog_content = "¿Mmm? ¡Porque eres mi hermana, por supuesto! ¿Qué hermano no querría ayudar a su propia hermana?",
  ui_story_5053_50530901_17_dialog_content = "Así que es por nuestro parentesco... ¿es eso?",
  ui_story_5053_50530901_18_dialog_content = "Así es. El mundo puede cambiar a nuestro alrededor, pero los lazos entre nosotros... Entre usted, nuestro padre y yo...",
  ui_story_5053_50530901_19_dialog_content = "Esos nunca cambiarán. No importa cuántos años pasen, siempre me sentiré así.",
  ui_story_5053_50530901_20_dialog_content = "¿Es eso así? Independientemente de tus motivos, debo agradecerte por rescatar mi cuerpo.",
  ui_story_5053_50530901_21_dialog_content = "Lo has hecho bien, Caleb.",
  ui_story_5053_50530901_22_dialog_content = "Joshua...!",
  ui_story_5053_50530901_23_dialog_content = "Es cierto que el mundo es un lugar en constante cambio, pero hay algunas cosas que ni siquiera el tiempo puede cambiar...",
  ui_story_5053_50530901_24_dialog_content = "Dime, ¿cómo es Lumopolis después de doce años?",
  ui_story_5053_50530901_25_dialog_content = "Nada ha cambiado. Esos aristócratas parásitos son tan tercos y desvergonzados como siempre.",
  ui_story_5053_50530901_26_dialog_content = "Después de engordarse con la gloria de Lumopolis, todo lo que queda es un sistema podrido cubierto solo por una fina capa.",
  ui_story_5053_50530901_27_dialog_content = "Ya veo... Y lo de House Schwartz?",
  ui_story_5053_50530901_28_dialog_content = "Schwartz? Es el más repugnante de todos.",
  ui_story_5053_50530901_29_dialog_content = "Te hizo tantas promesas en el pasado que nunca pudo cumplir.",
  ui_story_5053_50530901_30_dialog_content = "Incluso juró que convertiría a Lumopolis en un faro de libertad e igualdad...",
  ui_story_5053_50530901_31_dialog_content = "En este punto, podría luchar contra la aristocracia corrupta hasta su último aliento, y aún así nada cambiaría.",
  ui_story_5053_50530901_32_dialog_content = "Su debilidad es también la razón por la que tu familia quedó en ruinas. ¡Tú y tus hijas nunca debieron haber sufrido como lo hicieron, y lo desprecio aún más por eso!",
  ui_story_5053_50530901_33_dialog_content = "Puede que no sepa mucho de política, pero suenas un poco extremo, Caleb.",
  ui_story_5053_50530901_34_dialog_content = "creo que señor Schwartz merece más crédito que eso. Incluso con todos esos nobles codiciosos que constantemente conspiran contra él, todavía mantiene una apariencia tan honorable a la vista del público.",
  ui_story_5053_50530901_35_dialog_content = "¿Qué sabrías sobre el funcionamiento interno de Lumopolis, Jakine? Lo único que usted y el resto del mundo pueden ver es su llamada \"apariencia honorable\".",
  ui_story_5053_50530901_36_dialog_content = "P-Pero incluso Queen Bethlehem piensa... ¡Uf, no importa! ¡Solo voy a charlar con los guardias!",
  ui_story_5053_50530901_37_dialog_content = "¿Qué hay de mí, Caleb? ¿Me ves como un fracaso al elegir a Daniel como mi esposo?",
  ui_story_5053_50530901_38_dialog_content = "¡N-En absoluto! ¡Fuiste otra víctima de las grandiosas mentiras de Schwartz!",
  ui_story_5053_50530901_39_dialog_content = "Y si... fíjate, esto es puramente hipotético, pero si lo dejaras... Nuestra casa siempre estará abierta para ti.",
  ui_story_5053_50530901_40_dialog_content = "Y si alguna vez te cansaste de Lumopolis y su inmundicia, ¡siempre podríamos vivir en otro lugar!",
  ui_story_5053_50530901_41_dialog_content = "Eso no será necesario, Caleb. No tengo intención de dejar que Lumopolis se pudra. Cambiaré esta ciudad en mi vida, aunque sea lo último que haga.",
  ui_story_5053_50530901_42_dialog_content = "...",
  ui_story_5053_50530901_43_dialog_content = "Pero tienes razón al decir que Schwartz está más allá del ahorro. He perdido toda esperanza en él.",
  ui_story_5053_50530901_44_dialog_content = "Joshua... ¡¿Finalmente estás dispuesto a divorciarte de él?!",
  ui_story_5053_50530901_45_dialog_content = "Caleb, quedan tan pocas personas que están dispuestas a oponerse Schwartz.",
  ui_story_5053_50530901_46_dialog_content = "Parece que nuestros esfuerzos por criarte no fueron en vano, después de todo.",
  ui_story_5053_50530901_47_dialog_content = "¿Nuestro? Joshua, ¿acaso estás hablando de nuestro padre? ¿Qué tiene que ver él con esto? ¿Y por qué diría tal cosa...?",
  ui_story_5053_50530901_48_dialog_content = "Parece que ha llegado el momento de decirte la verdad, Caleb. Guardias, apoderaos de ella.",
  ui_story_5053_50530901_49_dialog_content = "...",
  ui_story_5053_50530901_50_dialog_content = "¡¡¡Ay!!! Oigan, ¿qué están haciendo ustedes?",
  ui_story_5053_50530901_51_dialog_content = "¿Qué quieres decir con la verdad, Joshua? ¿Y qué estás haciendo para Jakine??",
  ui_story_5053_50530901_52_dialog_content = "Caleb... <color=#FFB400>no soy tu hermana de sangre</color>.",
  ui_story_5053_50530901_53_dialog_content = "¿Qué...?",
  ui_story_5053_50530901_54_dialog_content = "Hace muchos años, mi familia se negó a someterse a House Schwartz y su dominio despótico. Como resultado, mi familia fue erradicada por el padre de Daniel, el anterior señor de la ciudad.",
  ui_story_5053_50530901_55_dialog_content = "Muchas otras familias también compartieron nuestro destino. Solo unos pocos de nosotros sobrevivimos y yo era solo un niño en ese entonces.",
  ui_story_5053_50530901_56_dialog_content = "Todos llegamos a despreciar House Schwartz, y juramos vengarnos de cada uno de ellos.",
  ui_story_5053_50530901_57_dialog_content = "Eventualmente, encontré mi camino hacia los Jardines de Lumopolis. Una familia afligida de nobles que habían perdido a su hija por la tiranía de Schwartz me aceptó como uno de los suyos.",
  ui_story_5053_50530901_58_dialog_content = "Espera... Una familia en duelo... ¿Quién? <color=#FFB400>perdió a su hija por Schwartz</color>...",
  ui_story_5053_50530901_59_dialog_content = "Así es, fue <color=#FFB400>Joshua</color>, tu hermana. Tu hermana de sangre y tu madre fueron asesinadas hace mucho tiempo.",
  ui_story_5053_50530901_60_dialog_content = "Nunca tuvieron ninguna pelea con House. Schwartz. Simplemente estaban visitando a un amigo, un opositor político de Schwartz cuya familia había sido marcada para su eliminación.",
  ui_story_5053_50530901_61_dialog_content = "... Y Padre, ¿sabía él de esto...?",
  ui_story_5053_50530901_62_dialog_content = "Por supuesto que lo hizo. Tu padre fue quien me pidió que tomara el lugar de su hija y buscara venganza contra House. Schwartz.",
  ui_story_5053_50530901_63_dialog_content = "¡I-Imposible! ¿Cómo podría un hombre amable y honesto como mi padre...",
  ui_story_5053_50530901_64_dialog_content = "El odio puede llevar incluso a las personas más compasivas a hacer cosas malvadas, Caleb.",
  ui_story_5053_50530901_65_dialog_content = "Fue la venganza, no el amor, lo que nos motivó a convertirte en el hombre que eres hoy.",
  ui_story_5053_50530901_66_dialog_content = "Cuando el intento de asesinato de tu padre fracasó, se quitó la vida no solo para protegernos, sino también para proteger las brasas de la venganza.",
  ui_story_5053_50530901_67_dialog_content = "Cuando vi la sinceridad de Daniel hace tantos años, le di una última oportunidad de cambiar de casa. Schwartz y Lumopolis para mejor.",
  ui_story_5053_50530901_68_dialog_content = "Le ofrecí mi apoyo inquebrantable en su campaña para convertirse en el próximo Señor de la Ciudad.",
  ui_story_5053_50530901_69_dialog_content = "Me dije a mí mismo que era mejor que su padre, que nunca me rebajaría tanto como para matar a personas inocentes, solo para salirme con la mía.",
  ui_story_5053_50530901_70_dialog_content = "Pero estaba equivocado. Daniel era demasiado incompetente para cambiar nada, así que me di cuenta de que era hora de que House Schwartz para sufrir nuestra ira.",
  ui_story_5053_50530901_71_dialog_content = "Caleb, deshazte de <color=#FFB400>Jakine</color>.",
  ui_story_5053_50530901_72_dialog_content = "... ¿Qué? Qué estás diciendo, Joshua?!",
  ui_story_5053_50530901_73_dialog_content = "Necesito que Lumina de los forasteros se vaya de aquí. Todavía tengo un propósito que cumplir allá afuera.",
  ui_story_5053_50530901_74_dialog_content = "No, Joshua... Jakine no tiene nada que ver con nada de esto! ¡Tú mismo lo dijiste, no estás dispuesto a asesinar a personas inocentes para salirte con la tuya!",
  ui_story_5053_50530901_75_dialog_content = "Su muerte es un sacrificio necesario.",
  ui_story_5053_50530901_76_dialog_content = "Qué... ¡¿Estás loco?! ¿Qué pasó con la dulce y gentil dama? Joshua ¡¿desde antes?!",
  ui_story_5053_50530901_77_dialog_content = "Me gustaría preguntar lo mismo! No me criaste por amor, sino por venganza... ¡Nunca he oído nada más ridículo en mi vida! Jakine, ¿estás seguro de que esta persona no es solo otra ilusión?",
  ui_story_5053_50530901_78_dialog_content = "¡No lo es, créeme! ¡Y tampoco le lancé ningún hechizo!",
  ui_story_5053_50530901_79_dialog_content = "¿Cuánto tiempo seguirás ignorando la verdad, Caleb? ¿Quieres que los sacrificios de tu familia sean en vano?",
  ui_story_5053_50530901_80_dialog_content = "...",
  ui_story_5053_50530901_81_dialog_content = "No importa, puedo disponer de Jakine mí mismo. Parece que fallamos en educarte a fondo, Caleb.",
  ui_story_5053_50530901_82_dialog_content = "Te daré una última oportunidad para demostrar tu determinación. Cuando llegue el momento, debes eliminar personalmente Schwartz, junto con los demás.",
  ui_story_5053_50530901_83_dialog_content = "¡Argh, suéltame! ¡Estás loco si crees que puedes matarnos a todos!",
  ui_story_5053_50530901_84_dialog_content = "No tienes a nadie a quien culpar pero Schwartz. Adiós, enviado de Northland.",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5053_50530901_86_dialog_content = "... Tienes razón, Joshua. Aunque gran parte de ti se me ha vuelto desconocida, no se puede negar que eres mi muy querida hermana.",
  ui_story_5053_50530901_87_dialog_content = "¡Por eso debo detenerte! ¡No dejaré que vivas con el arrepentimiento de haber hecho algo tan horrible!",
  ui_story_5053_50530901_88_dialog_content = "¿Arrepentirse? Nunca me he arrepentido de nada. Elegí criarte en el lugar de tu cobarde padre para que heredases nuestro deseo de venganza.",
  ui_story_5053_50530901_89_dialog_content = "¡Urgh...!",
  ui_story_5053_50530901_90_dialog_content = "Sin embargo, has elegido traicionarme... ¡Al igual que todos los demás!",
  ui_story_5053_50530901_91_dialog_content = "No, Joshua... ¡Nunca te traicionaría!",
  ui_story_5053_50530901_92_dialog_content = "Hmph, así que has logrado desarmarme... ¡Pero los pequeños trucos no te salvarán ahora!",
  ui_story_5053_50530901_93_dialog_content = "Si somos honestos, también tengo una confesión que hacer. Todos estos años, he dicho que Schwartz no era digno de ti, pero la verdad es...",
  ui_story_5053_50530901_94_dialog_content = "¡Yo estaba resentido con él! ¡Con todo mi corazón, estaba resentido con ese hombre y los hijos que le diste porque te alejaron de mí! ¡Me quitaron la única familia que me quedaba en este mundo!",
  ui_story_5053_50530901_95_dialog_content = "No me importa que no estemos relacionados por sangre... ¡Me criaste de un niño a un adulto, y siempre serás mi amada hermana!",
  ui_story_5053_50530901_96_dialog_content = "Parece que nunca serás más que un niño llorón, desesperado por la atención de su hermana. ¡Ahora sal de mi camino!",
  ui_story_5053_50530901_97_dialog_content = "¡Así es! ¡Y nunca cambiaré, no importa cuánto me ridiculices!",
  ui_story_5053_50530901_98_dialog_content = "Pero sabía... sabía cuánto amabas a tu marido ya tus hijas; ¡Nada de lo que hice podría cambiar eso!",
  ui_story_5053_50530901_99_dialog_content = "¡¡Te dije que todo era un acto!!",
  ui_story_5053_50530901_100_dialog_content = "Yo... lo siento, Joshua, pero me niego a creer eso.",
  ui_story_5053_50530901_101_dialog_content = "Y me niego a dejar que sigas adelante con esto. ¡Protegeré a tu preciosa familia, incluso a costa de mi propia vida!",
  ui_story_5053_50530901_102_dialog_content = "Muy bien, entonces perderás tanto tu vida como tu Lumina.",
  ui_story_5053_50530901_103_dialog_content = "¡¿Urgh...?!",
  ui_story_5053_50530901_104_dialog_content = "No... ¡¡Noooo!! Caleb!!!",
  ui_story_5053_50530901_105_dialog_content = "... Tu hiciste tu decisión.",
  ui_story_5053_50530901_130_dialog_content = "Caleb!!!",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>Aplastar-!</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>¡Aaaaaah—!</size>",
  ui_story_5053_50530901_133_dialog_content = "¡Uh!",
  ui_story_5053_50530901_134_dialog_content = "Urg-!",
  ui_story_5053_50530901_135_dialog_content = "¡¿?!",
  ui_story_5053_50530901_136_dialog_content = "¡Oh, criatura repugnante, apareciendo en un momento como este...!",
  ui_story_5053_50530901_138_dialog_content = "¡Caleb! ¡Solo espera, por favor!",
  ui_story_5053_50530901_139_dialog_content = "¡¡C...Caleb...!!",
  ui_story_5053_50530901_140_dialog_content = "Heh... Matándome con un solo golpe... Así que todavía hay algo de misericordia en su corazón, después de todo...",
  ui_story_5053_50530901_141_dialog_content = "Esto no está bien. La herida es demasiado profunda, está perdiendo demasiada sangre...",
  ui_story_5053_50530901_143_dialog_content = "Está tan oscuro... No puedo ver nada.",
  ui_story_5053_50530901_145_dialog_content = "No por favor...",
  ui_story_5053_50530901_146_dialog_content = "Joshua...? Eres tu...?",
  ui_story_5053_50530901_147_dialog_content = "¡Caleb... Caleb!",
  ui_story_5053_50530901_148_dialog_content = "Estoy aquí...",
  ui_story_5053_50530901_149_dialog_content = "Yo... ya veo... Tos, tos!!!",
  ui_story_5053_50530901_150_dialog_content = "Tú... ¿Dejaste tu arma? Joshua?",
  ui_story_5053_50530901_151_dialog_content = "Estoy tan feliz...",
  ui_story_5053_50530901_152_dialog_content = "...",
  ui_story_5053_50530901_153_dialog_content = "¿Caleb? Caleb!!!",
  ui_story_5053_50530901_155_dialog_content = "Por favor... Caleb!!!",
  ui_story_5053_50530901_156_dialog_content = "No no...!!",
  ui_story_5053_50530901_157_dialog_content = "<size=50>¡¡¡Hraaaaaaaaaaaah!!!</size>",
  ui_story_5053_50531001_1_dialog_content = "Huff... Huff...",
  ui_story_5053_50531001_2_dialog_content = "¿Estás bien? PlayerName? Podemos parar y descansar si lo necesitas.",
  ui_story_5053_50531001_3_dialog_content = "Estoy bien, no te preocupes. Solo estoy preocupado porque la Oscuridad Angel despegó tan rápido en este momento.",
  ui_story_5053_50531001_4_dialog_content = "Estuvo con nosotros todo este tiempo, pero de repente se fue volando como si sintiera que algo andaba mal...",
  ui_story_5053_50531001_5_dialog_content = "Ella hizo exactamente lo mismo antes, cuando sintió que estabas en peligro. Realmente estoy empezando a preocuparme por Jakine y Caleb.",
  ui_story_5053_50531001_6_dialog_content = "¡Casi estámos allí! Ojalá todavía estén bien...",
  ui_story_5053_50531001_7_dialog_content = "Mia, estás seguro que Jakine no recuerda nada sobre el segundo reinicio?",
  ui_story_5053_50531001_8_dialog_content = "Estoy seguro de ello. Ninguno de nosotros recordaba que alguna vez sucedió... Por eso creíamos todo lo que los demás Joshua nos dijo.",
  ui_story_5053_50531001_9_dialog_content = "Para ser honesto, todavía me cuesta creer tu propia historia, PlayerName...",
  ui_story_5053_50531001_10_dialog_content = "Por eso... ¡Necesito ver la verdad por mí mismo!",
  ui_story_5053_50531001_11_dialog_content = "(Entonces, ¿por qué recuerdo todo, aunque Jakine ¿no? No tiene sentido...)",
  ui_story_5053_50531001_12_dialog_content = "Algo no se siente bien. ¿Dónde están todos los guardias?",
  ui_story_5053_50531001_13_dialog_content = "Se siente como si el suelo estuviera temblando... Mia, ¡¡Estar atento!!",
  ui_story_5053_50531001_14_dialog_content = "¡¿?!",
  ui_story_5053_50531001_15_dialog_content = "¡Intrusos! ¡Traidores! Morir-!",
  ui_story_5053_50531001_16_dialog_content = "Ahhh—!!!",
  ui_story_5053_50531001_17_dialog_content = "¡Morir! ¡Morir! ¡Morir!",
  ui_story_5053_50531001_18_dialog_content = "¡No esos guardias locos otra vez!",
  ui_story_5053_50531001_19_dialog_content = "¡¡¡Ahhhh!!! ¡¡¡Alguien salveme!!!",
  ui_story_5053_50531001_20_dialog_content = "Era que... Jakine?!",
  ui_story_5053_50531001_21_dialog_content = "¡Los guardias la persiguen! Tenemos que abrirnos camino a través de esta mafia, Mia!",
  ui_story_5053_50531001_22_dialog_content = "¡Hay demasiados de ellos! Hipopótamo-",
  ui_story_5053_50531001_23_dialog_content = "¡Hazte a un lado, Princesa Verónica—!",
  ui_story_5053_50531001_24_dialog_content = "?!?!",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5053_50531001_26_dialog_content = "Urgh...!!",
  ui_story_5053_50531001_27_dialog_content = "Aaaaaahhh!!!",
  ui_story_5053_50531001_28_dialog_content = "(Ms. Blanc?! ¡Eso fue increible! ¡Bailó a través de toda la multitud de guardias y los eliminó a todos!)",
  ui_story_5053_50531001_29_dialog_content = "¡Sra. Rot! ¡Detrás de ti!",
  ui_story_5053_50531001_30_dialog_content = "No te preocupes, princesa Verónica.",
  ui_story_5053_50531001_31_dialog_content = "Como miembro de la Guardia Nocturna, mi deber es evitar que nadie profane Lumopolis.",
  ui_story_5053_50531001_32_dialog_content = "¡Nadie perturbará la paz y el orden de Lumopolis bajo mi vigilancia!",
  ui_story_5053_50531001_33_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_5053_50531001_34_dialog_content = "Puaj-!!",
  ui_story_5053_50531001_35_dialog_content = "¡¡Yarrgh!!",
  ui_story_5053_50531001_36_dialog_content = "Princesa Verónica, señorita Jakine, ¿estás herido?",
  ui_story_5053_50531001_37_dialog_content = "Estoy bien.",
  ui_story_5053_50531001_38_dialog_content = "Llegaste justo a tiempo. No creo que hubiéramos podido ganar sin usted, Sra. Rot.",
  ui_story_5053_50531001_39_dialog_content = "¿Qué diablos está pasando, su alteza? Estos guardias no estaban actuando como rebeldes ordinarios.",
  ui_story_5053_50531001_40_dialog_content = "¡Eso es porque no son rebeldes! Todo este lío es todo de Joshua—",
  ui_story_5053_50531001_41_dialog_content = "¡Silencio, traidor! Gracias a Dios que ha venido, Sra. Rot.",
  ui_story_5053_50531001_42_dialog_content = "Estos asaltantes estaban aliados con PlayerName y Jakine, junto con el resto de su traicionero grupo de forasteros. ¡Incluso han logrado lavarle el cerebro a Veronica para que se una a su lado!",
  ui_story_5053_50531001_43_dialog_content = "Ella está demasiado lejos para ser salvada ahora. Como su madre, no podría estar más decepcionada.",
  ui_story_5053_50531001_44_dialog_content = "Me temo que ahora no tengo elección. Sra. Rot, le ordeno que se deshaga de los tres.",
  ui_story_5053_50531001_45_dialog_content = "...",
  ui_story_5053_50531001_46_dialog_content = "¡¿Qué estás diciendo, madre?! Entonces PlayerName tenía razón todo el tiempo...",
  ui_story_5053_50531001_47_dialog_content = "¡Escúchame, Sra. Rot! El \"Joshua\"¡Frente a ti no hay nada más que un impostor! Todavía no sé exactamente qué está pasando...",
  ui_story_5053_50531001_48_dialog_content = "Pero créanme cuando les digo que ella no es la Joshua ¡siempre lo has sabido!",
  ui_story_5053_50531001_49_dialog_content = "PlayerName esta diciendo la verdad! Por mi honor como miembro de la Schwartz familia, puedo dar fe de ello!",
  ui_story_5053_50531001_50_dialog_content = "¡Conoces a mi madre mejor que nadie! ¡¿Cómo pudo ordenarte que hicieras algo así?!",
  ui_story_5053_50531001_51_dialog_content = "...",
  ui_story_5053_50531001_52_dialog_content = "¿Por qué sigues dudando? ¿Has olvidado todo lo que te he enseñado?",
  ui_story_5053_50531001_53_dialog_content = "Un asesino debe obedecer a su amo sin dudarlo. Deben estar dispuestos a pagar cualquier precio para llevar a cabo la justa voluntad de su amo.",
  ui_story_5053_50531001_54_dialog_content = "No dejarás que tus emociones anulen tu sentido del deber, ¿verdad? Recuerde, las emociones no son más que obstáculos en el camino hacia el futuro próspero de Lumopolis.",
  ui_story_5053_50531001_55_dialog_content = "(¿Qué? No sabía Ms. Blanc ¿Era alumno de Joshua?!)",
  ui_story_5053_50531001_56_dialog_content = "... Tienes razón, Maestro. Todo lo que hago es por el futuro de Lumopolis.",
  ui_story_5053_50531001_57_dialog_content = "¡¿Qué...?!",
  ui_story_5053_50531001_58_dialog_content = "Con el fin de crear un mundo mejor, uno en el que los niños puedan reír y existir en pacífica armonía... Eliminaré cualquier obstáculo en mi camino, incluso si ese obstáculo eres tú.",
  ui_story_5053_50531001_59_dialog_content = "...",
  ui_story_5053_50531001_60_dialog_content = "Qué notablemente audaz de tu parte apuntar tu espada hacia mí. Supongo que no debería sorprenderme.",
  ui_story_5053_50531001_61_dialog_content = "Si esta es tu elección, ¡entonces puedes morir aquí con el resto de ellos!",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_5053_50531001_63_dialog_content = "Urgh—!",
  ui_story_5053_50531001_64_dialog_content = "(¡Sus ataques son demasiado rápidos...!)",
  ui_story_5053_50531001_65_dialog_content = "¿Sra. Rot?",
  ui_story_5053_50531001_66_dialog_content = "PlayerName! Lleva a la princesa Verónica y a la señorita Jakine, ¡¡¡y correr!!!",
  ui_story_5053_50531001_67_dialog_content = "¡No sé si soy lo suficientemente fuerte para derrotarla, así que ustedes tres deben escapar mientras puedan!",
  ui_story_5053_50531001_68_dialog_content = "Pero.",
  ui_story_5053_50531001_69_dialog_content = "¡Guarda tu aliento! Tu seguridad está por encima de cualquier otra cosa, ¡ahora vete!",
  ui_story_5053_50531001_70_dialog_content = "... ¡Lo lamento! Mia, Jakine, ¡¡vamos a salir de aquí!!",
  ui_story_5053_50531001_71_dialog_content = "(¡Tenga cuidado, Sra. Rot...!)",
  ui_story_5053_50531002_1_dialog_content = "¡Allá! ¿Tenemos algo más para bloquear la puerta?",
  ui_story_5053_50531002_2_dialog_content = "Me temo que no. Esa silla era la única que quedaba.",
  ui_story_5053_50531002_3_dialog_content = "¡Argh! ¡¡Todo esto es demasiado raro!!",
  ui_story_5053_50531002_4_dialog_content = "Si que PlayerName dice que es cierto, entonces ya hemos pasado por un segundo reinicio.",
  ui_story_5053_50531002_5_dialog_content = "Todos se tomaron de la mano por primera vez, así que recordamos todo. Así es como sé que lo hice bien.",
  ui_story_5053_50531002_6_dialog_content = "Estuve allí para el segundo reinicio, pero no conservé ninguno de mis recuerdos...",
  ui_story_5053_50531002_7_dialog_content = "Por qué cree que pasó, Jakine?",
  ui_story_5053_50531002_8_dialog_content = "... Creo que tengo una idea.",
  ui_story_5053_50531002_9_dialog_content = "¡El Cristal de la Memoria Eterna se debe estar quedando sin Lumina!",
  ui_story_5053_50531002_10_dialog_content = "¡¿Qué?!",
  ui_story_5053_50531002_11_dialog_content = "Ugh... Parece que nos pasamos con nuestra lucha contra el enemigo.",
  ui_story_5053_50531002_12_dialog_content = "Con tan poca Lumina, el Cristal de la Memoria Eterna no puede mantener todas sus funciones.",
  ui_story_5053_50531002_13_dialog_content = "Pero entonces, ¿por qué te quedaste con todos tus recuerdos? PlayerName?",
  ui_story_5053_50531002_14_dialog_content = "Y ahora hay dos Joshua... ¡Las cosas se vuelven cada vez más locas!",
  ui_story_5053_50531002_15_dialog_content = "Quizas el Joshua de la mansión realmente es un impostor?",
  ui_story_5053_50531002_16_dialog_content = "Estoy tan confundido como tú, pero mi padre todavía está demasiado ocupado luchando contra el dragón para ayudarnos. Yo también estoy preocupada por él...",
  ui_story_5053_50531002_17_dialog_content = "No tenemos muchas opciones en este momento. ¿Por qué no intentamos realizar otro reinicio?",
  ui_story_5053_50531002_18_dialog_content = "¡¿Estás loco?! Si ninguno de nosotros logra mantener nuestros recuerdos, tendrías que luchar Joshua ¡todo por ti mismo!",
  ui_story_5053_50531002_19_dialog_content = "Ella está en lo correcto. No tendrías ninguna oportunidad contra ella por tu cuenta.",
  ui_story_5053_50531002_20_dialog_content = "Bloquear la puerta con toda esta basura debería habernos dado algo de tiempo. Déjame ver qué hay en el libro...",
  ui_story_5053_50531002_21_dialog_content = "\"Las artes de adivinación de Northland se originaron en un antiguo asentamiento auroriano...\" Antiguos aurorianos, hmmm...",
  ui_story_5053_50531002_22_dialog_content = "¡Espera, eso es todo! Las artes de la adivinación fueron diseñadas y utilizadas por los aurorianos, pero PlayerName es una Caelestita!",
  ui_story_5053_50531002_23_dialog_content = "¿Podría afectar a otras razas de manera diferente? Después de todo, el libro no menciona a ningún no auroriano usando los hechizos.",
  ui_story_5053_50531002_24_dialog_content = "Ya veo... ¿Quizás eso también explica por qué mis habilidades psíquicas también son mucho más débiles?",
  ui_story_5053_50531002_25_dialog_content = "Decir, PlayerName? ¿Alguna vez has jugado alguno de los juegos de Illumina?",
  ui_story_5053_50531002_26_dialog_content = "Cuando comienzas un juego, los personajes pierden todo su progreso, pero el jugador aún recuerda todo lo que sucedió.",
  ui_story_5053_50531002_27_dialog_content = "¿Estás diciendo que aquí, yo soy el jugador?",
  ui_story_5053_50531002_28_dialog_content = "¡Bingo! ¡Es por eso que no estás sujeto a las mismas reglas que el resto de nosotros!",
  ui_story_5053_50531002_29_dialog_content = "Es por eso que debemos planificar todo perfectamente si queremos restablecer el tiempo nuevamente.",
  ui_story_5053_50531002_30_dialog_content = "Estoy de acuerdo. Sería demasiado peligroso para ti retroceder en el tiempo sin estar preparado.",
  ui_story_5053_50531002_31_dialog_content = "Supongo que tienes razón... Planifiquemos las cosas, entonces.",
  ui_story_5053_50531002_32_dialog_content = "En este momento, nuestra mayor amenaza es Joshua.",
  ui_story_5053_50531002_33_dialog_content = "En cuanto a por qué de repente hay dos de ellos, todavía no estoy del todo seguro.",
  ui_story_5053_50531002_34_dialog_content = "Es demasiado confuso referirse a ambos como Joshua, ya que uno de ellos es Dark Angel...",
  ui_story_5053_50531002_35_dialog_content = "¡Podemos llamar al otro el Demonio Blanco!",
  ui_story_5053_50531002_37_dialog_content = "El Demonio Blanco... No quiero llamar a Madre por ese nombre, pero es una forma adecuada de describirla tal como es ahora.",
  ui_story_5053_50531002_38_dialog_content = "A juzgar por el comportamiento y el conocimiento del Demonio Blanco, es seguro asumir que no es una impostora.",
  ui_story_5053_50531002_39_dialog_content = "Cuando una Semilla se planta en un huésped vivo, crea una personalidad dividida... Dadas mis propias experiencias, puedo relacionarme con su situación.",
  ui_story_5053_50531002_40_dialog_content = "Y al igual que Baba Yaga y yo, no hay forma de determinar quién de nosotros es bueno o malo.",
  ui_story_5053_50531002_41_dialog_content = "Sus acciones pueden ser extremas a veces, pero eso no hace que Baba Yaga sea mala. PlayerName eso también lo sabe.",
  ui_story_5053_50531002_42_dialog_content = "¿Es posible que la Oscuridad Angel y el Demonio Blanco son lo mismo?",
  ui_story_5053_50531002_43_dialog_content = "A pesar de su comportamiento aterrador, la Oscuridad Angel nos salvó en la plaza central.",
  ui_story_5053_50531002_44_dialog_content = "¿Quizás solo tiene problemas para controlarse?",
  ui_story_5053_50531002_45_dialog_content = "Bueno, a pesar de que comparte algunos rasgos con Baba Yaga, no creo que tú y el Demonio Blanco se parezcan en nada. Mia.",
  ui_story_5053_50531002_46_dialog_content = "No es más que una asesina despiadada y despiadada. ¿Estás diciendo señora? Joshua tiene un lado como este?",
  ui_story_5053_50531002_47_dialog_content = "Yo tampoco lo entiendo. Madre siempre fue una persona amable y gentil... Nunca vi una pizca de maldad en ella.",
  ui_story_5053_50531002_48_dialog_content = "Er, podría ser capaz de agregar a la historia aquí.",
  ui_story_5053_50531002_49_dialog_content = "Ella solía ser una asesina. Lo escuché directamente de su boca hace un tiempo...",
  ui_story_5053_50531002_50_dialog_content = "Hace muchos años, mi familia se negó a someterse a House Schwartz y su dominio despótico. Como resultado, mi familia fue erradicada por el padre de Daniel, el anterior Señor de la Ciudad.",
  ui_story_5053_50531002_51_dialog_content = "Muchas otras familias también compartieron nuestro destino. Solo unos pocos de nosotros sobrevivimos y yo era solo un niño en ese entonces.",
  ui_story_5053_50531002_52_dialog_content = "Todos llegamos a despreciar House Schwartz, y juramos vengarnos de cada uno de ellos.",
  ui_story_5053_50531002_53_dialog_content = "Eventualmente, encontré mi camino hacia los Jardines de Lumopolis. Una familia afligida de nobles que habían perdido a su hija por la tiranía de Schwartz me aceptó como uno de los suyos.",
  ui_story_5053_50531002_54_dialog_content = "Qué...? ¡¿P-Pero cómo podría ser eso?! ¡¡E-Ella es la esposa de Lord Schwartz!!",
  ui_story_5053_50531002_55_dialog_content = "¿No crees que podría haber estado mintiendo?",
  ui_story_5053_50531002_56_dialog_content = "A mi también me cuesta imaginarlo...",
  ui_story_5053_50531002_57_dialog_content = "...",
  ui_story_5053_50531002_58_dialog_content = "No crees eso, verdad Mia?!",
  ui_story_5053_50531002_59_dialog_content = "En realidad... Tendría mucho sentido si estuviera diciendo la verdad.",
  ui_story_5053_50531002_60_dialog_content = "Además de ser una madre amable y compasiva, también era una persona increíblemente poderosa.",
  ui_story_5053_50531002_61_dialog_content = "A pesar de su elevado estatus como esposa del señor de la ciudad, nunca perdió de vista su moral. Ella se acercó a todo con una mente racional y un corazón gentil...",
  ui_story_5053_50531002_62_dialog_content = "En nuestra vida privada, cuidó de todos nosotros, incluido mi padre. En público, era la compañera perfecta del señor de la ciudad de Lumopolis.",
  ui_story_5053_50531002_63_dialog_content = "Nunca estuvo motivada por la riqueza o el poder. Incluso en las situaciones más extremas, siempre sacrificaría sus propios intereses por el bien de otras personas.",
  ui_story_5053_50531002_64_dialog_content = "Eso no es algo que cualquier mujer noble sea capaz de hacer.",
  ui_story_5053_50531002_65_dialog_content = "Un pasado cruel y trágico, seguido de toda una vida sacrificándose y reprimiendo sus propias necesidades, todo mientras no tenía a nadie que la entendiera...",
  ui_story_5053_50531002_66_dialog_content = "El sufrimiento de mi madre fue un millón de veces más doloroso que el mío.",
  ui_story_5053_50531002_67_dialog_content = "No la culparía si este Demonio Blanco fuera una manifestación de su resentimiento.",
  ui_story_5053_50531002_68_dialog_content = "Entiendo...",
  ui_story_5053_50531002_69_dialog_content = "Dama Joshua... Qué existencia tan increíble pero trágica.",
  ui_story_5053_50531002_70_dialog_content = "Pero si nuestra teoría es cierta, ¿por qué Baba Yaga y yo no nos separamos también?",
  ui_story_5053_50531002_71_dialog_content = "Tienes razón, y esa es una gran diferencia entre tú y Lady. Joshua.",
  ui_story_5053_50531002_72_dialog_content = "Baba Yaga es tu amigo, Mia. Ella siempre está tratando de protegerte.",
  ui_story_5053_50531002_73_dialog_content = "Es posible que ella no quiera separarse de ti. Eso explicaría por qué no la hemos visto desde que entramos en el mundo de Crystal.",
  ui_story_5053_50531002_74_dialog_content = "Joshua, por otro lado, es exactamente lo contrario. Sus dos mitades están completamente en desacuerdo entre sí.",
  ui_story_5053_50531002_75_dialog_content = "¿T-Tú crees? Me alivia escuchar eso... Todo este tiempo, pensé que solo estaba enojada porque me cambié de ropa sin consultarla.",
  ui_story_5053_50531002_76_dialog_content = "Baba Yaga... Cuando volvamos, tendré que agradecerle por ser tan considerada...",
  ui_story_5053_50531002_77_dialog_content = "Volvamos a lo que dijo el Demonio Blanco antes.",
  ui_story_5053_50531002_78_dialog_content = "Según ella, la única forma de escapar sin lastimar a nadie... es traerlos a los dos con nosotros.",
  ui_story_5053_50531002_79_dialog_content = "No crees que estaba mintiendo cuando dijo eso, ¿verdad...?",
  ui_story_5053_50531002_80_dialog_content = "No me parece. Después de todo, coincide con lo que sucedió durante el último reinicio.",
  ui_story_5053_50531002_81_dialog_content = "El problema es que no sabemos si todavía tiene algo bajo la manga o no...",
  ui_story_5053_50531002_82_dialog_content = "...",
  ui_story_5053_50531002_83_dialog_content = "¿Desaparecido en combate?",
  ui_story_5053_50531002_84_dialog_content = "Lo siento, solo me pregunto cómo será mamá una vez que regresemos al mundo real...",
  ui_story_5053_50531002_85_dialog_content = "¿Seguirá sufriendo como antes? O peor... ¿Se convertirá en un Eclipsite?",
  ui_story_5053_50531002_86_dialog_content = "Yo... creo que deberíamos tratar de mantenernos optimistas por ahora.",
  ui_story_5053_50531002_87_dialog_content = "Pase lo que pase, todos estaremos ahí para ayudar. Caballero Schwartz, Caleb, Jakine... y yo también.",
  ui_story_5053_50531002_88_dialog_content = "Con nuestra fuerza combinada, deberíamos ser capaces de manejar cualquier cosa que se nos presente.",
  ui_story_5053_50531002_89_dialog_content = "¡Pero nada cambiará a menos que salgamos de aquí primero!",
  ui_story_5053_50531002_90_dialog_content = "... ¡Estás absolutamente en lo correcto!",
  ui_story_5053_50531002_91_dialog_content = "Sin embargo, sacarlos a los dos al mismo tiempo no será fácil. Dudo que el Demonio Blanco venga en silencio.",
  ui_story_5053_50531002_92_dialog_content = "También dejó muy claro que odia a su otro yo y se niega a volver a ser uno con ella...",
  ui_story_5053_50531002_93_dialog_content = "Cierto, por eso planea matarnos a todos.",
  ui_story_5053_50531002_94_dialog_content = "Nuestra única opción es someterla por la fuerza y llevárnosla con nosotros.",
  ui_story_5053_50531002_95_dialog_content = "Pero con todos esos guardias sin sentido y un dragón en el camino...",
  ui_story_5053_50531002_96_dialog_content = "¿Dice algo el libro sobre por qué están actuando de manera tan extraña, Jakine?",
  ui_story_5053_50531002_97_dialog_content = "Déjame ver... ¡Allí! \"Quienquiera que primero active un Cristal de la Memoria Eterna tiene el poder de alterar el curso de los acontecimientos hasta cierto punto\".",
  ui_story_5053_50531002_98_dialog_content = "... Espera, ¿es eso todo? Argh, ¿no podrías explicar un poco más, mamá?",
  ui_story_5053_50531002_99_dialog_content = "Parece que tendremos que encontrar la respuesta por nosotros mismos. Mmm...",
  ui_story_5053_50531002_100_dialog_content = "El mundo dentro de un Cristal de Memoria Eterna es creado y sostenido por <color=#FFB400>El agua del lago Mirror</color> y <color=#FFB400>la Lumina de quien la active</color>.",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>El activador Lumina</color>... En otras palabras, ¡la Lumina de Joshua! Todo este mundo ilusorio es producto de su propia Lumina.",
  ui_story_5053_50531002_102_dialog_content = "Ella mencionó que su poder se había dividido, ¿verdad?",
  ui_story_5053_50531002_103_dialog_content = "Cierto...",
  ui_story_5053_50531002_104_dialog_content = "¡También dijo que necesitaba absorber a nuestra Lumina para convertirse en su propia persona!",
  ui_story_5053_50531002_105_dialog_content = "¡Así es! ¡¿No ves?!",
  ui_story_5053_50531002_106_dialog_content = "cuando la oscuridad Angel se separó del Demonio Blanco, ¡se llevó la mitad de su poder con ella!",
  ui_story_5053_50531002_107_dialog_content = "En cuanto a la otra mitad, ¡no creo que la haya perdido en absoluto! ¡Creo que lo usó para manipular el Cristal de la Memoria Eterna!",
  ui_story_5053_50531002_108_dialog_content = "Después de todo, el dragón y los guardias son productos de la Lumina de Joshua.",
  ui_story_5053_50531002_109_dialog_content = "Eso significa que ella es la única capaz de interferir con ellos... ¡O, en este caso, de infectarlos!",
  ui_story_5053_50531002_110_dialog_content = "Si ese es el caso, ¡el Demonio Blanco nos ha estado mintiendo desde el principio!",
  ui_story_5053_50531002_111_dialog_content = "¿Es eso realmente posible? Entonces Sra. Rot...",
  ui_story_5053_50531002_112_dialog_content = "... Es probable que esté en mucho peligro en este momento.",
  ui_story_5053_50531002_113_dialog_content = "Esto es aterrador, ella puede ser tan cruel y calculadora...",
  ui_story_5053_50531002_114_dialog_content = "Nunca le he tenido miedo a mamá, pero sin su lado cálido y gentil...",
  ui_story_5053_50531002_115_dialog_content = "¿Es este realmente el tipo de persona en la que se convertiría?",
  ui_story_5053_50531002_116_dialog_content = "Entonces, el dragón y las turbas de locos son probablemente los peones del Demonio Blanco. Derrotarlos debería reducir su fuerza.",
  ui_story_5053_50531002_117_dialog_content = "Aparte de eso, ¿tenemos alguna otra forma de luchar contra ella? ¡Espera!",
  ui_story_5053_50531002_118_dialog_content = "La oscuridad Angel! Ella fue pacífica con el Señor Schwartz y el resto de su familia, ¡y el Demonio Blanco no puede matarla por su cuenta!",
  ui_story_5053_50531002_119_dialog_content = "Si podemos convencerla de que luche de nuestro lado, ¡tendremos muchas más posibilidades de ganar!",
  ui_story_5053_50531002_120_dialog_content = "¡Ese es un plan descabellado que tienes ahí! ¡Siempre supe que tenías un lado imprudente!",
  ui_story_5053_50531002_121_dialog_content = "Pero tengo que advertirte, PlayerName...",
  ui_story_5053_50531002_122_dialog_content = "Al Cristal de la Memoria Eterna solo le queda suficiente Lumina para un reinicio final.",
  ui_story_5053_50531002_123_dialog_content = "Eso significa que el fracaso no es una opción. ¡Tienes que tener éxito, o estamos todos perdidos!",
  ui_story_5053_50531002_124_dialog_content = "Tengo que tener éxito... Lo tengo...",
  ui_story_5053_50531002_125_dialog_content = "PlayerName? Después del reinicio final, ¿qué pasa si vas directamente al Demonio Blanco y la expones de inmediato?",
  ui_story_5053_50531002_126_dialog_content = "Whoa... Eso es aún más salvaje que PlayerName'¡lado a! Mi impresión de ti ha cambiado mucho desde que llegamos aquí. Mia.",
  ui_story_5053_50531002_127_dialog_content = "¿D-De veras?",
  ui_story_5053_50531002_128_dialog_content = "Sería extremadamente arriesgado, sin duda.",
  ui_story_5053_50531002_129_dialog_content = "No tengo forma de defenderme. El Demonio Blanco no tendría ningún problema en deshacerse de mí.",
  ui_story_5053_50531002_130_dialog_content = "Ninguno de ustedes tendrá sus recuerdos tampoco, por lo que es posible que no crean mis acusaciones de inmediato.",
  ui_story_5053_50531002_131_dialog_content = "Tienes razón... Al tío Caleb le resultaría especialmente difícil creer en tu testimonio.",
  ui_story_5053_50531002_132_dialog_content = "Pero honestamente, PlayerName, no creo que tengas que preocuparte demasiado por esto.",
  ui_story_5053_50531002_133_dialog_content = "Mi padre es extremadamente perceptivo. Ha tenido sus sospechas sobre el Demonio Blanco desde que la conocimos esta vez.",
  ui_story_5053_50531002_134_dialog_content = "Creo que le pidió al tío Caleb que se quedara atrás para poder ver la verdad con sus propios ojos...",
  ui_story_5053_50531002_135_dialog_content = "Es por eso que debes centrar tu atención en la Oscuridad. Angel en cambio.",
  ui_story_5053_50531002_136_dialog_content = "Eso suena como Señor Schwartz...",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>¡Pam! ¡Pam! ¡Pam!</color>",
  ui_story_5053_50531002_138_dialog_content = "¡¿Q-Qué fue eso?!",
  ui_story_5053_50531002_139_dialog_content = "¡Oh no, los guardias lo alcanzaron!",
  ui_story_5053_50531002_140_dialog_content = "¡Iré a retenerlos! Jakine, prepárate para realizar el reinicio final...",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5053_50531002_142_dialog_content = "¡Cuidado, Mia!",
  ui_story_5053_50531002_143_dialog_content = "Es eso...?!",
  ui_story_5053_50531002_144_dialog_content = "...",
  ui_story_5053_50531002_145_dialog_content = "¿Sra. Rot?",
  ui_story_5053_50531002_146_dialog_content = "Volver, Mia!",
  ui_story_5053_50531002_147_dialog_content = "... No.",
  ui_story_5053_50531002_148_dialog_content = "Debe sentir mucho dolor en este momento, Sra. Rot... Al igual que Carleen, cuando luchó hasta el final para mantener la cordura.",
  ui_story_5053_50531002_149_dialog_content = "... No dejaré que vuelva a suceder. No dejaré que sufras el camino Carleen sufrido.",
  ui_story_5053_50531002_150_dialog_content = "¡Te liberaré de tu dolor!",
  ui_story_5053_50531002_151_dialog_content = "¡Ven a mí!",
  ui_story_5053_50531002_152_dialog_content = "—!",
  ui_story_5053_50531002_153_dialog_content = "Mia...",
  ui_story_5053_50531002_154_dialog_content = "Ella está luchando tan duro como puede para ganar algo de tiempo, Jakine... Comencemos el reinicio.",
  ui_story_5053_50531002_155_dialog_content = "Una vez que me despierte, solo tengo que encontrar la oscuridad. Angel, luego escóndete de esos guardias, y luego...",
  ui_story_5053_50531002_156_dialog_content = "PlayerName? Te tiemblan las manos...",
  ui_story_5053_50531002_157_dialog_content = "...",
  ui_story_5053_50531002_158_dialog_content = "Sé que estamos poniendo mucho sobre tus hombros en este momento. Yo también estaría nervioso si tuviera que hacerlo todo solo, pero no tengas miedo.",
  ui_story_5053_50531002_159_dialog_content = "Todo va a estar bien. ¡Te creemos, pase lo que pase!",
  ui_story_5053_50531002_160_dialog_content = "Jakine...!",
  ui_story_5053_50531002_161_dialog_content = "¡Bien! ¡Sólo déjamelo a mi!",
  ui_story_5053_50531002_162_dialog_content = "¡Reditus, reditus, reditus! ¡Que todo vuelva a ser como antes!",
  ui_story_5053_50531002_163_dialog_content = "¡Abracadabra!",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>Después del tercer reinicio—</color>",
  ui_story_5053_50531101_1_dialog_content = "Todo está listo, mi señor.",
  ui_story_5053_50531101_2_dialog_content = "El carruaje espera afuera y está listo para partir en cualquier momento.",
  ui_story_5053_50531101_3_dialog_content = "Entendido.",
  ui_story_5053_50531101_4_dialog_content = "Sube al carruaje, Carleen.",
  ui_story_5053_50531101_5_dialog_content = "¡Yo... quiero quedarme atrás con mamá!",
  ui_story_5053_50531101_6_dialog_content = "Jakine... Mia... Yo debo...",
  ui_story_5053_50531101_7_dialog_content = "Hmmm... ¿Dónde estoy...?",
  ui_story_5053_50531101_8_dialog_content = "Así es, Jakine me envió atrás en el tiempo otra vez!",
  ui_story_5053_50531101_9_dialog_content = "Y por allí... el yo más joven de Lord Schwartz está escoltando Carleen fuera de aquí.",
  ui_story_5053_50531101_10_dialog_content = "¡Parece que el reinicio fue exitoso!",
  ui_story_5053_50531101_11_dialog_content = "Muy bien, lo primero es lo primero...",
  ui_story_5053_50531101_12_dialog_content = "Persona sospechosa... debe exterminar...",
  ui_story_5053_50531101_13_dialog_content = "Persona sospechosa... no aquí...",
  ui_story_5053_50531101_14_dialog_content = "¡Uf, logré esquivar a los guardias! ¡Eso se encarga de eso!",
  ui_story_5053_50531101_15_dialog_content = "(Antes del reinicio, los tres armamos un plan de tres pasos para sacarnos de aquí).",
  ui_story_5053_50531101_16_dialog_content = "(Primero, encuentra la oscuridad Angel y convencerla de luchar de nuestro lado.)",
  ui_story_5053_50531101_17_dialog_content = "(Y luego, evita que el dragón y los guardias infectados lancen su ataque).",
  ui_story_5053_50531101_18_dialog_content = "(Por último, acaba con el Demonio Blanco antes de que alguien más resulte herido o algo peor).",
  ui_story_5053_50531101_19_dialog_content = "(Mia, Jakine...)",
  ui_story_5053_50531101_20_dialog_content = "(Este es nuestro último reinicio. Tengo que lograr esto, o todos estamos condenados).",
  ui_story_5053_50531101_21_dialog_content = "Persona sospechosa... exterminar...",
  ui_story_5053_50531101_22_dialog_content = "!!!",
  ui_story_5053_50531101_23_dialog_content = "Aqui no...",
  ui_story_5053_50531101_24_dialog_content = "(Eso estuvo cerca... Según mis últimos encuentros con estos guardias, no van a dejar de perseguirme hasta el final).",
  ui_story_5053_50531101_25_dialog_content = "(Tengo poco tiempo, fuerza de combate y movilidad... Lo que significa que tendré que completar los tres pasos de una sola vez).",
  ui_story_5053_50531101_26_dialog_content = "(¡Solo tengo una oportunidad para esto!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5053_50531102_2_dialog_content = "Ugh... Tos, tos...",
  ui_story_5053_50531102_3_dialog_content = "¿De dónde salió la oscuridad? Angel ¿ir?",
  ui_story_5053_50531102_4_dialog_content = "Parece que escapó por un camino exterior.",
  ui_story_5053_50531102_5_dialog_content = "Eso fue maravilloso, Señor Schwartz!",
  ui_story_5053_50531102_6_dialog_content = "Estoy agradecido de que nadie resultó herido—",
  ui_story_5053_50531102_7_dialog_content = "¡Ahí están todos!",
  ui_story_5053_50531102_8_dialog_content = "Madre... ¿Qué haces aquí? ¿No deberías estar viendo el desfile?",
  ui_story_5053_50531102_9_dialog_content = "...",
  ui_story_5053_50531102_10_dialog_content = "... Parece que tuvimos un invitado no deseado.",
  ui_story_5053_50531102_11_dialog_content = "¿Todos están bien?",
  ui_story_5053_50531102_12_dialog_content = "Joshua? P-pero la oscuridad Angel En este momento...",
  ui_story_5053_50531102_13_dialog_content = "Jejeje, así que mi pequeño genio también tiene sus momentos de confusión.",
  ui_story_5053_50531102_14_dialog_content = "Todos ustedes deben estar cansados de su batalla. Entra y descansa, ¿quieres?",
  ui_story_5053_50531102_15_dialog_content = "No te preocupes por ese monstruo. Enviaré a mis guardias a cazarlo en un momento.",
  ui_story_5053_50531102_16_dialog_content = "Madre, un momento, algo no parece estar bien...",
  ui_story_5053_50531102_17_dialog_content = "¿Alguien ha visto PlayerName?",
  ui_story_5053_50531102_18_dialog_content = "¡Oh sí! Dónde es PlayerName? No lo veo por ninguna parte.",
  ui_story_5053_50531102_19_dialog_content = "Ha estado desaparecido todo el tiempo.",
  ui_story_5053_50531102_20_dialog_content = "Qué...",
  ui_story_5053_50531102_21_dialog_content = "Lo siento, madre. Tenemos que ir a buscar PlayerName antes de que corra peligro...",
  ui_story_5053_50531102_22_dialog_content = "Me alegra el corazón ver cuánto te preocupas por tu amigo, Vonnie... Pero tengo algo muy importante que compartir con todos.",
  ui_story_5053_50531102_23_dialog_content = "Enviaré un equipo de guardias a buscar PlayerName. Vamos adentro por ahora, ¿de acuerdo?",
  ui_story_5053_50531102_24_dialog_content = "¿Eh? Um... O-Está bien...",
  ui_story_5053_50531102_25_dialog_content = "... ¿Es asi?",
  ui_story_5053_50531102_26_dialog_content = "No es propio de ti hablar sobre las circunstancias de vida o muerte de una persona con tanta indiferencia.",
  ui_story_5053_50531102_27_dialog_content = "¿Oh? ¿Es eso lo que piensas de mí? ¿Una dama noble ordinaria y débil? DANIEL.",
  ui_story_5053_50531102_28_dialog_content = "...",
  ui_story_5053_50531102_29_dialog_content = "¿Daniel? Pero Joshua, ¿cómo pudiste ser?",
  ui_story_5053_50531201_1_dialog_content = "Resoplan...",
  ui_story_5053_50531201_2_dialog_content = "Sé que la vi irse por aquí, pero ¿por qué no puedo encontrarla?",
  ui_story_5053_50531201_3_dialog_content = "Sch... verruga...",
  ui_story_5053_50531201_4_dialog_content = "¡Allá! ¡Detrás de esa caja!",
  ui_story_5053_50531201_5_dialog_content = "...!!!",
  ui_story_5053_50531201_6_dialog_content = "¡Espera, no quiero pelear contigo! ¡Caleb y Veronica están en peligro y necesitan tu ayuda!",
  ui_story_5053_50531201_7_dialog_content = "Ca... ¿Caleb...? Verónica...?",
  ui_story_5053_50531201_8_dialog_content = "¡Así es! ¡Tu hermano Caleb y tu hija Verónica!",
  ui_story_5053_50531201_9_dialog_content = "Son tu familia, ¿no?",
  ui_story_5053_50531201_10_dialog_content = "Mi familia...",
  ui_story_5053_50531201_11_dialog_content = "¡Sí, tu familia! ¡Y ahora mismo están en grave peligro!",
  ui_story_5053_50531201_12_dialog_content = "Mi familia... en peligro...",
  ui_story_5053_50531201_13_dialog_content = "Hay algo mal...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>Mi familia... Schwartz!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "¡¿E-Eh?! ¡Oye, mantenlo abajo! ¡Vas a alertar a los guardias!",
  ui_story_5053_50531201_16_dialog_content = "(Cuando dijimos que Caleb estaba en peligro la última vez, ella estaba dispuesta a ayudarnos. ¿Por qué se enoja esta vez?)",
  ui_story_5053_50531201_17_dialog_content = "(¿Es posible que la Oscuridad Angel solo escuchare Mia o alguien más de su familia?)",
  ui_story_5053_50531201_18_dialog_content = "Dolor...! Mucho dolor...!",
  ui_story_5053_50531201_19_dialog_content = "Ah, esto no es bueno... ¡Me estoy quedando sin tiempo! ¡¿Qué tengo que hacer?!",
  ui_story_5053_50531201_20_dialog_content = "no llores...",
  ui_story_5053_50531201_21_dialog_content = "No llores... Mi dulce, pequeña... Vonnie...",
  ui_story_5053_50531201_22_dialog_content = "Todo estará bien...",
  ui_story_5053_50531201_23_dialog_content = "Ah...",
  ui_story_5053_50531201_24_dialog_content = "(Necesito calmarla de alguna manera. Entonces, la forma en que los Aurorianos se consuelan unos a otros... lo único que significa paz y seguridad para la Oscuridad Angel...)",
  ui_story_5053_50531201_25_dialog_content = "(¡Es mi única oportunidad!)",
  ui_story_5053_50531201_26_dialog_content = "Elige una rosa... ¿Solo para mi bebé? ♪",
  ui_story_5053_50531201_27_dialog_content = "Algo, algo... ¿La brisa en tu rostro es todo lo que necesito? ♪",
  ui_story_5053_50531201_28_dialog_content = "¿...?",
  ui_story_5053_50531201_29_dialog_content = "...",
  ui_story_5053_50531201_30_dialog_content = "¿Elegir una rosa...? Para mi querido padre y madre... ♪",
  ui_story_5053_50531201_31_dialog_content = "Callarse la boca.",
  ui_story_5053_50531201_32_dialog_content = "Me disculpo si mi canto es terrible.",
  ui_story_5053_50531201_33_dialog_content = "Escucho esta canción en la calle de vez en cuando. Es pegadizo, pero nunca puedo recordar las palabras.",
  ui_story_5053_50531201_34_dialog_content = "La melodía también se me escapa la mayor parte del tiempo.",
  ui_story_5053_50531201_35_dialog_content = "Un miembro de la casa Schwartz no tiene derecho a cantar una canción de Lower Lumopolis.",
  ui_story_5053_50531201_36_dialog_content = "... ¿Por qué te molesta House? Schwartz ¿mucho?",
  ui_story_5053_50531201_37_dialog_content = "El odio incluso te obligó a enmascararte y sacrificarte para acercarte a mí, convirtiéndote en mi amante.",
  ui_story_5053_50531201_38_dialog_content = "Todo esto, solo para que pudieras asesinar a mi padre.",
  ui_story_5053_50531201_39_dialog_content = "...",
  ui_story_5053_50531201_40_dialog_content = "Tu acto fue perfecto y tu experiencia en combate y academia es insuperable.",
  ui_story_5053_50531201_41_dialog_content = "Dime, ¿cuánto tiempo tomó perfeccionar estas habilidades?",
  ui_story_5053_50531201_42_dialog_content = "¿Cinco años? ¿Diez años? O tal vez... ¿toda tu vida?",
  ui_story_5053_50531201_43_dialog_content = "Todo el entrenamiento y los preparativos solo para llevar a cabo un solo asesinato de alto perfil.",
  ui_story_5053_50531201_44_dialog_content = "¿Fue la vida de mi padre verdaderamente digna del odio en tu corazón y en los corazones de tus conspiradores?",
  ui_story_5053_50531201_45_dialog_content = "Antes de que llegues a una conclusión equivocada, déjame aclarar una cosa.",
  ui_story_5053_50531201_46_dialog_content = "Digo estas cosas, no sólo en defensa del honor de mi padre... sino porque no quiero verte consumido por el odio.",
  ui_story_5053_50531201_47_dialog_content = "Casa Schwartz es la encarnación de la opresión y la tiranía.",
  ui_story_5053_50531201_48_dialog_content = "Todas las comidas que tienes y toda la ropa que vistes están manchadas con la sangre de tus víctimas.",
  ui_story_5053_50531201_49_dialog_content = "Víctimas, dices. ¿Están incluyendo a la verdadera hermana de Caleb además de tu verdadera familia?",
  ui_story_5053_50531201_50_dialog_content = "...",
  ui_story_5053_50531201_51_dialog_content = "Esto es solo una especulación de mi parte, al menos por el momento.",
  ui_story_5053_50531201_52_dialog_content = "Hace siete años, la madre de Caleb murió trágica y accidentalmente durante una operación antirebelde.",
  ui_story_5053_50531201_53_dialog_content = "Su hermana, Joshua, también estuvo presente durante el ataque.",
  ui_story_5053_50531201_54_dialog_content = "Sin embargo, de alguna manera, como por algún milagro, ella emergió como la única sobreviviente de la operación... Pero no fue un milagro, ¿o sí?",
  ui_story_5053_50531201_55_dialog_content = "Sólo entonces, un completamente nuevo \"Joshua\" como tú podría aparecer. ¿Me equivoco hasta ahora?",
  ui_story_5053_50531201_56_dialog_content = "...",
  ui_story_5053_50531201_57_dialog_content = "Nunca compartí mis sospechas con nadie, ni le conté a nadie sobre tu presencia aquí.",
  ui_story_5053_50531201_58_dialog_content = "Todos asumieron que simplemente te habías ido a casa. Incluso se lo dije a tu padre adoptivo.",
  ui_story_5053_50531201_59_dialog_content = "Pero, de hecho, nunca volviste. Tu padre adoptivo tampoco mencionó tu desaparición.",
  ui_story_5053_50531201_60_dialog_content = "Claramente, él sabía por qué estabas desaparecida.",
  ui_story_5053_50531201_61_dialog_content = "...",
  ui_story_5053_50531201_62_dialog_content = "Sin embargo, en lugar de evitar el tema, se me acercó durante la clase y me preguntó cómo estábamos últimamente.",
  ui_story_5053_50531201_63_dialog_content = "Tramar la muerte de su soberano es un crimen punible con la muerte más espantosa, sin embargo, en ese momento, estaba más preocupado por tu seguridad que por la suya propia.",
  ui_story_5053_50531201_64_dialog_content = "En lugar de elegir el miedo o el odio, ese amable anciano erudito te eligió a ti.",
  ui_story_5053_50531201_65_dialog_content = "Así que, por favor... Por su bien, abandona tu plan de asesinar a mi padre.",
  ui_story_5053_50531201_66_dialog_content = "Si lo haces, prometo comportarme como si nada hubiera pasado y devolverte a tu familia.",
  ui_story_5053_50531201_67_dialog_content = "Ahórrame el teatro, Schwartz. No escucharé, y si él estuviera aquí ahora... Él tampoco escucharía.",
  ui_story_5053_50531201_68_dialog_content = "Estamos unidos por nuestro odio mutuo por House Schwartz. Sacrificarnos en pos de nuestras ambiciones es el mayor honor.",
  ui_story_5053_50531201_69_dialog_content = "¿Mmm? ¿No dije que solo estaba haciendo conjeturas? Nunca tuve ninguna evidencia para probar mis afirmaciones.",
  ui_story_5053_50531201_70_dialog_content = "Pero ahora que ha admitido haber conspirado contra House Schwartz con el padre de Caleb...",
  ui_story_5053_50531201_71_dialog_content = "Jajaja, parece que esta ronda me pertenece, Joshua!",
  ui_story_5053_50531201_72_dialog_content = "...",
  ui_story_5053_50531201_73_dialog_content = "Ejem, perdóname por ese poco de regodeo. Solo quería aligerar un poco el ambiente...",
  ui_story_5053_50531201_74_dialog_content = "En cualquier caso, puedo comprender tu desconfianza.",
  ui_story_5053_50531201_75_dialog_content = "Mi padre siempre ha sido un hombre despiadado y decidido. Cuando se trataba de silenciar a sus enemigos... Lo haría indiscriminadamente, en lugar de dejar escapar a una sola persona.",
  ui_story_5053_50531201_76_dialog_content = "Afirmó que sus acciones eran necesarias para establecer un frente unificado.",
  ui_story_5053_50531201_77_dialog_content = "Todos deben respetar House Schwartz, y todos deben obedecer a un solo gobernante.",
  ui_story_5053_50531201_78_dialog_content = "Cuando todos los ciudadanos sean leales a un solo líder digno de confianza, los codiciosos y los malvados no tendrán dónde esconderse.",
  ui_story_5053_50531201_79_dialog_content = "Y una vez que su suciedad haya sido purgada de la ciudad, Lumopolis brillará sobre el mundo como una utopía pura y perfecta.",
  ui_story_5053_50531201_80_dialog_content = "La visión del futuro de mi padre era tan grandiosa como ideal. Lo respeto aún más por eso.",
  ui_story_5053_50531201_81_dialog_content = "Sin embargo... aún se están sentando las bases para la utopía de mi padre, y no todos comparten su visión.",
  ui_story_5053_50531201_82_dialog_content = "Dime, ¿notaste las expresiones en los rostros de todos cuando llegaste por primera vez a mi casa?",
  ui_story_5053_50531201_83_dialog_content = "Cada vez que yo estaba presente, todos me trataban con adulación nerviosa.",
  ui_story_5053_50531201_84_dialog_content = "Solo desde lejos pude ver sus verdaderas sonrisas... Sus verdaderos momentos de felicidad.",
  ui_story_5053_50531201_85_dialog_content = "Así que le pregunté a mi padre por qué me trataban así.",
  ui_story_5053_50531201_86_dialog_content = "Dijo que era porque todos se habían acostumbrado a vivir en un pecado vergonzoso.",
  ui_story_5053_50531201_87_dialog_content = "Por lo tanto, no podan soportar mirar a los miembros de la Casa Schwartz, que simbolizaba la justicia y el orden.",
  ui_story_5053_50531201_88_dialog_content = "Estaba en su naturaleza, un mal que nunca podría ser erradicado... Por eso necesitaban nuestra guía.",
  ui_story_5053_50531201_89_dialog_content = "Era el noble deber de House Schwartz para soportar el peso de la gobernabilidad y corregir su comportamiento.",
  ui_story_5053_50531201_90_dialog_content = "... Pero para ser sincero, vivir aquí era insoportablemente sofocante.",
  ui_story_5053_50531201_91_dialog_content = "Por esta razón, a menudo me disfrazaba y me escabullía de casa para disfrutar de un momento de respiro.",
  ui_story_5053_50531201_92_dialog_content = "Todo este tiempo, pensé que eras diferente, Joshua. Eras la única persona que se reiría conmigo, Joshua.",
  ui_story_5053_50531201_93_dialog_content = "Pero ahora veo que solo fue una ilusión... Y que todavía tengo mucho que aprender.",
  ui_story_5053_50531201_94_dialog_content = "... Tonto.",
  ui_story_5053_50531201_95_dialog_content = "Jaja... Estoy de acuerdo. Si tan solo nunca hubiera nacido como Schwartz.",
  ui_story_5053_50531201_96_dialog_content = "Razón de más por la que debo confrontar tu dolor y tu odio.",
  ui_story_5053_50531201_97_dialog_content = "Un asesinato perfecto como este nunca podría ser realizado por unas pocas personas.",
  ui_story_5053_50531201_98_dialog_content = "Pueden ocultar tu verdadera identidad, entrenarte año tras año, obtener ayuda de todo el personal relevante...",
  ui_story_5053_50531201_99_dialog_content = "No puedo imaginar cuántas personas se necesitan para lograr tal hazaña, y mucho menos hacerlo con perfecta precisión.",
  ui_story_5053_50531201_100_dialog_content = "La presión ejercida por House Schwartz está lejos de erradicar la codicia y la maldad. Más bien, nos ha convertido en enemigos de innumerables personas.",
  ui_story_5053_50531201_101_dialog_content = "Esta nunca fue la intención de mi padre...",
  ui_story_5053_50531201_102_dialog_content = "No intentes persuadirme con tus lastimosos discursos, Schwartz. Si ha reconocido sus errores, usted y su padre deberían aceptar la responsabilidad por ellos... y pagar con sus vidas.",
  ui_story_5053_50531201_103_dialog_content = "Morir por los propios errores es evitar responsabilizarse por ellos, Joshua.",
  ui_story_5053_50531201_104_dialog_content = "La visión de mi padre no estaba del todo equivocada. De hecho, tenía muchas cualidades redentoras.",
  ui_story_5053_50531201_105_dialog_content = "Este complot de asesinato es una prueba indiscutible de ello.",
  ui_story_5053_50531201_106_dialog_content = "¿...?",
  ui_story_5053_50531201_107_dialog_content = "En el pasado, el rango y el linaje determinaban todo en Lumopolis.",
  ui_story_5053_50531201_108_dialog_content = "El soborno y la malversación de fondos eran hechos comunes entre la nobleza. Con su influencia política, ocuparon todos los puestos de poder y utilizaron la ley para promover sus propios intereses.",
  ui_story_5053_50531201_109_dialog_content = "Pero bajo la presión ejercida por mi padre, la gente de Lower Lumopolis también obtuvo el derecho a buscar justicia.",
  ui_story_5053_50531201_110_dialog_content = "Con la amenaza de la justicia pendiendo sobre sus cabezas, los nobles de Lumopolis comenzaron a confesar sus crímenes a cambio de indulgencia.",
  ui_story_5053_50531201_111_dialog_content = "A través de un sistema de evaluaciones, las personas también comenzaron a ascender en los rangos de la jerarquía de nuestra ciudad.",
  ui_story_5053_50531201_112_dialog_content = "Esto estaba en línea con la visión de mi padre: un mundo donde el valor de una persona se decide por sus habilidades y determinación, en lugar de su nacimiento.",
  ui_story_5053_50531201_113_dialog_content = "¿No era el padre de Caleb un erudito nacido en una familia común?",
  ui_story_5053_50531201_114_dialog_content = "Si lo que he dicho es mentira, entonces alguien como él, sin riqueza ni estatus, nunca podría haber entrado en los Jardines de Lumopolis solo por su talento.",
  ui_story_5053_50531201_115_dialog_content = "Tampoco podrías haber usado su condición de profesor para acercarte a mí.",
  ui_story_5053_50531201_116_dialog_content = "La persona que planeó este asesinato reconoció esta verdad y basó todo su plan en torno a ella.",
  ui_story_5053_50531201_117_dialog_content = "...",
  ui_story_5053_50531201_118_dialog_content = "Entonces, dime, Joshua. ¿En qué fallaron las políticas de mi padre?",
  ui_story_5053_50531201_119_dialog_content = "¿Es porque el Bajo Lumopolis todavía está acosado por el crimen? ¿O es porque sus purgas excesivamente decisivas resultaron en innumerables errores judiciales?",
  ui_story_5053_50531201_120_dialog_content = "Sea lo que sea, juro que no descansaré hasta que se haya revelado la verdad.",
  ui_story_5053_50531201_121_dialog_content = "Puede ser imposible compensar el dolor que sientes en este momento...",
  ui_story_5053_50531201_122_dialog_content = "Pero al menos, deberíamos tratar de aclarar las cosas. Por el bien de todos los demás, así como por el nuestro.",
  ui_story_5053_50531201_123_dialog_content = "... Todavía no entiendes.",
  ui_story_5053_50531201_124_dialog_content = "Lo que la gente necesita no es un gobierno adecuado sino una libertad verdadera y absoluta.",
  ui_story_5053_50531201_125_dialog_content = "Absoluta... ¿libertad?",
  ui_story_5053_50531201_126_dialog_content = "Sí. El derecho a vivir como les plazca en lugar de acatar una jerarquía social.",
  ui_story_5053_50531201_127_dialog_content = "El derecho a decir lo que piensan sin temor a perder su riqueza o incluso sus vidas.",
  ui_story_5053_50531201_128_dialog_content = "Eso es libertad.",
  ui_story_5053_50531201_129_dialog_content = "Esos sirvientes te tenían tanto miedo porque sabían que podías quitarles todo cuando quisieras.",
  ui_story_5053_50531201_130_dialog_content = "\"Un mundo donde el valor de una persona se decide por sus habilidades y determinación...\" ¡No me hagas reír!",
  ui_story_5053_50531201_131_dialog_content = "¡Para la Casa Schwartz, no somos más que ganado cuya existencia depende únicamente de su aprobación!",
  ui_story_5053_50531201_132_dialog_content = "...",
  ui_story_5053_50531201_133_dialog_content = "...",
  ui_story_5053_50531201_134_dialog_content = "Entonces, al matar a mi padre y erradicar a House Schwartz...",
  ui_story_5053_50531201_135_dialog_content = "Deseas crear un mundo de absoluta libertad, uno que exista sin House Schwartz?",
  ui_story_5053_50531201_136_dialog_content = "¿Eso realmente te hará feliz, Joshua?",
  ui_story_5053_50531201_137_dialog_content = "Mi felicidad no está ligada a nada de esto.",
  ui_story_5053_50531201_138_dialog_content = "Una vez que el asesinato finalmente se lleve a cabo, mi vida también llegará a su fin.",
  ui_story_5053_50531201_139_dialog_content = "En otras palabras, ¿ha elegido la muerte sin importar el resultado?",
  ui_story_5053_50531201_140_dialog_content = "¿Es esto para proteger a tus aliados?",
  ui_story_5053_50531201_141_dialog_content = "No. Una vez que mi misión esté completa, simplemente ya no tengo razón para existir.",
  ui_story_5053_50531201_142_dialog_content = "Sin razón...?",
  ui_story_5053_50531201_143_dialog_content = "Los nobles están motivados por el interés propio, pero nosotros lo estamos por nuestros ideales.",
  ui_story_5053_50531201_144_dialog_content = "No vivimos para la riqueza ni el estatus, sino para levantar un nuevo sol en el cielo, uno que brille igualmente sobre el mundo.",
  ui_story_5053_50531201_145_dialog_content = "Para abatir al viejo y opresor sol, estamos más que dispuestos a sacrificarnos. No creas que puedes juzgarnos con tu podrido pensamiento utilitario.",
  ui_story_5053_50531201_146_dialog_content = "Je, aunque me siento honrado de que hayas compartido tanto conmigo, ¿por qué todo es tan críptico y oscuro?",
  ui_story_5053_50531201_147_dialog_content = "¿Así que esta es tu forma preferida de hablar...?",
  ui_story_5053_50531201_148_dialog_content = "Si mi padre y su regla representan el \"viejo sol\", ¿no sería este llamado \"nuevo sol\" simplemente otra regla?",
  ui_story_5053_50531201_149_dialog_content = "La persona detrás del complot de asesinato... ¿Buscan tomar el lugar de mi padre como el nuevo gobernante?",
  ui_story_5053_50531201_150_dialog_content = "...",
  ui_story_5053_50531201_151_dialog_content = "... Increíble.",
  ui_story_5053_50531201_152_dialog_content = "Podría entender morir con tu enemigo para proteger a tu familia y aliados... Pero, ¿qué quieres decir con que no tienes razón para existir?",
  ui_story_5053_50531201_153_dialog_content = "¿Qué hay de tu hermano menor, que se ha opuesto a mí día y noche desde que te robé de él?",
  ui_story_5053_50531201_154_dialog_content = "¿Qué hay de tu padre adoptivo, que teme por tu seguridad y simplemente desea que vuelvas a casa?",
  ui_story_5053_50531201_155_dialog_content = "¿No son motivo suficiente para vivir de...?",
  ui_story_5053_50531201_156_dialog_content = "Si realmente crees que House Schwartz ha robado a todos su libertad, ¡solo necesitas destruirnos para reclamarla!",
  ui_story_5053_50531201_157_dialog_content = "Entonces, ¿por qué debes privarte de esa misma libertad, incluso si tienes éxito?",
  ui_story_5053_50531201_158_dialog_content = "¿Significa esto que terminarías con tu propia vida si mi padre falleciera inesperadamente? ¿Están sus destinos tan entrelazados?",
  ui_story_5053_50531201_159_dialog_content = "Lo he probado suficientes veces, ¿no? Todo el vínculo y la relación con ese hombre y su tonto hijo es solo un disfraz.",
  ui_story_5053_50531201_160_dialog_content = "Soy un arma cuyo único propósito es acabar con el gobierno de House. Schwartz.",
  ui_story_5053_50531201_161_dialog_content = "Sin mi enemigo, no tengo razón para existir. La libertad es del pueblo, no mía.",
  ui_story_5053_50531201_162_dialog_content = "... Qué hipócrita.",
  ui_story_5053_50531201_163_dialog_content = "Parece que este \"nuevo sol\" nunca te enseñó el verdadero significado del amor o la libertad.",
  ui_story_5053_50531201_164_dialog_content = "¿Cómo podría usted posiblemente entregar cualquiera de los dos a la gente?",
  ui_story_5053_50531201_165_dialog_content = "...",
  ui_story_5053_50531201_166_dialog_content = "... Entiendo ahora.",
  ui_story_5053_50531201_167_dialog_content = "Nunca fui parte de tu mundo. No tengo forma de comprender verdaderamente cómo ha sufrido el pueblo bajo un gobierno estricto.",
  ui_story_5053_50531201_168_dialog_content = "Tú tampoco fuiste parte de mi mundo. No tienes manera de entender el verdadero significado del amor o la libertad.",
  ui_story_5053_50531201_169_dialog_content = "Esta es una brecha que nunca podremos esperar cerrar.",
  ui_story_5053_50531201_170_dialog_content = "De acuerdo, así que ríndete ya...",
  ui_story_5053_50531201_171_dialog_content = "¡Por eso debemos trabajar juntos y compensar las deficiencias de los demás!",
  ui_story_5053_50531201_172_dialog_content = "Estas loco.",
  ui_story_5053_50531201_173_dialog_content = "Ya seamos nosotros, o mi padre, o incluso esta persona del \"nuevo sol\"...",
  ui_story_5053_50531201_174_dialog_content = "Nadie es capaz de ver las cosas desde el punto de vista de todos. No solo, al menos.",
  ui_story_5053_50531201_175_dialog_content = "Pero si dejamos de lado nuestras diferencias e intentamos trabajar juntos...",
  ui_story_5053_50531201_176_dialog_content = "¡Podemos crear un mundo nuevo y libre! ¡Uno donde la voz de todos se puede escuchar!",
  ui_story_5053_50531201_177_dialog_content = "Este es tu objetivo también, ¿no es así?",
  ui_story_5053_50531201_178_dialog_content = "...",
  ui_story_5053_50531201_179_dialog_content = "Desde que te detuve ese día, he pensado en ello constantemente.",
  ui_story_5053_50531201_180_dialog_content = "¿Está mal que confiemos nuestros sueños a otros?",
  ui_story_5053_50531201_181_dialog_content = "Ya sea realizando la visión de mi padre o matándolo para dar lugar a un \"nuevo sol\"...",
  ui_story_5053_50531201_182_dialog_content = "Quizás tomar nuestro destino en nuestras propias manos es la mejor manera de realizar nuestros sueños.",
  ui_story_5053_50531201_183_dialog_content = "Tan confundido e ignorante como estoy ahora...",
  ui_story_5053_50531201_184_dialog_content = "Creo que trabajando juntos, podemos lograr cualquier cosa que deseemos.",
  ui_story_5053_50531201_185_dialog_content = "Todo lo que tenemos que hacer es dar el primer paso.",
  ui_story_5053_50531201_186_dialog_content = "Puedes abrirme los ojos al mundo fuera de Lumopolis Gardens.",
  ui_story_5053_50531201_187_dialog_content = "Sólo entonces podré ver las deficiencias de la política de mi padre.",
  ui_story_5053_50531201_188_dialog_content = "A cambio, te ayudaré a experimentar la vida al máximo, para que puedas reírte desde el fondo de tu corazón nuevamente.",
  ui_story_5053_50531201_189_dialog_content = "Cuando llegue ese día, ¡puedes compartir esa alegría con el resto del mundo!",
  ui_story_5053_50531201_190_dialog_content = "... Qué inútil.",
  ui_story_5053_50531201_191_dialog_content = "Hay muchas otras mujeres que estarían más que felices de jugar a las casitas contigo. ¿Por qué perder el tiempo conmigo?",
  ui_story_5053_50531201_192_dialog_content = "Bueno, para ser honesto...",
  ui_story_5053_50531201_193_dialog_content = "Hay tan pocas personas que están dispuestas a oponerse a mi padre, y los residentes de Lumopolis Gardens no pueden comprender el mundo exterior...",
  ui_story_5053_50531201_194_dialog_content = "Y, er... Tal como dije cuando nos conocimos por primera vez—",
  ui_story_5053_50531201_195_dialog_content = "¡Me enamoré de ti a primera vista!",
  ui_story_5053_50531201_196_dialog_content = "...",
  ui_story_5053_50531201_197_dialog_content = "(La oscuridad Angel no se ha movido en mucho tiempo. ¿Se ha calmado finalmente...?)",
  ui_story_5053_50531201_198_dialog_content = "¡Ey! ¿Finalmente estás dispuesto a escucharme entonces?",
  ui_story_5053_50531201_199_dialog_content = "Escucha, el Demonio Blanco... quiero decir, el otro tú, quiere matar a Caleb, Veronica y todos los demás.",
  ui_story_5053_50531201_200_dialog_content = "Realmente necesitan tu...",
  ui_story_5053_50531201_201_dialog_content = "Daniel...",
  ui_story_5053_50531201_202_dialog_content = "¿Ah?",
  ui_story_5053_50531201_203_dialog_content = "Daniel... ¡¿Por qué... me traicionaste?!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>¡¡¡Daniel!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "Que-?! ¡Se está volviendo aún más loca que antes! ¡P-Por favor, cálmate! no soy señor Schwartz!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>¡Daniel! ¡Daniel!</size>",
  ui_story_5053_50531201_207_dialog_content = "(Me estoy quedando sin tiempo, ¡pero al menos tengo su atención! ¡Necesito llevarla a la plaza central!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>Daniel-</size>",
  ui_story_5053_50531301_1_dialog_content = "Mi agradecimiento a todas las personas de Lumopolis reunidas aquí hoy para celebrar esta ocasión especial.",
  ui_story_5053_50531301_2_dialog_content = "Casa Schwartz es la joya de la corona de la ciudad, así como su fundación.",
  ui_story_5053_50531301_3_dialog_content = "Levantamos nuestros brazos en defensa de Lumopolis, empuñando espadas que fueron creadas por su propia gente.",
  ui_story_5053_50531301_4_dialog_content = "Hoy, alabamos no solo a House Schwartz y su ejemplo moral, pero también la gente orgullosa y justa de Lumopolis!",
  ui_story_5053_50531301_5_dialog_content = "Por la presente declaro el comienzo de la Schwartz ¡Celebración del día de la familia!",
  ui_story_5053_50531301_6_dialog_content = "La celebración está por comenzar, pero la Oscuridad Angel aún no ha aparecido cerca del stand.",
  ui_story_5053_50531301_7_dialog_content = "Eliminar... Intruso...",
  ui_story_5053_50531301_8_dialog_content = "¿Mmm? ¿Qué les pasa a estos guardias?",
  ui_story_5053_50531301_9_dialog_content = "Si mal no recuerdo, las personas dentro del Cristal de la Memoria Eterna no son más que ilusiones creadas por Lumina.",
  ui_story_5053_50531301_10_dialog_content = "¿Por qué de repente se comportarían de manera tan errática? Es como si hubieran perdido la sensibilidad...",
  ui_story_5053_50531301_11_dialog_content = "Estaré en el estrado para vigilar. Si veo alguna señal de la Oscuridad Angel, se lo haré saber a todo el mundo.",
  ui_story_5053_50531301_12_dialog_content = "Bien. Estar en guardia, Mia.",
  ui_story_5053_50531301_13_dialog_content = "(Mia debería estar a salvo allí por el momento. PlayerName, por otro lado, ¿dónde podría estar ahora mismo?)",
  ui_story_5053_50531301_14_dialog_content = "¿Qué?",
  ui_story_5053_50531301_15_dialog_content = "PlayerName...",
  ui_story_5053_50531301_16_dialog_content = "Debe encontrar... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "Detener. Ustedes claramente no son caballeros de la Casa Kartima.",
  ui_story_5053_50531301_18_dialog_content = "House Kartima está supervisando la seguridad para la celebración de este año, entonces, ¿por qué deambulas así?",
  ui_story_5053_50531301_19_dialog_content = "(Estos guardias siguen tambaleándose y murmurando para sí mismos... ¿Podrían estar borrachos?)",
  ui_story_5053_50531301_20_dialog_content = "(¿Y por qué están tan interesados en encontrar PlayerName?)",
  ui_story_5053_50531301_21_dialog_content = "Debe encontrar... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "Debe eliminar... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "¿Le ruego me disculpe? Lo que acabas de decir es un grave incumplimiento de tus deberes caballerescos.",
  ui_story_5053_50531301_24_dialog_content = "Explíquense en este instante, todos ustedes.",
  ui_story_5053_50531301_25_dialog_content = "¡Elimina... al intruso...!",
  ui_story_5053_50531301_26_dialog_content = "Ni siquiera pueden hablar coherentemente, mucho menos decirme quién o qué está detrás de esto. ¿Qué diablos les pasa a estos caballeros?",
  ui_story_5053_50531301_27_dialog_content = "(Después del reinicio, nadie en el Cristal de la Memoria Eterna debería reconocer PlayerName ya no.)",
  ui_story_5053_50531301_28_dialog_content = "(Ni siquiera deberían ser conscientes de su existencia, y mucho menos albergar intenciones asesinas hacia él).",
  ui_story_5053_50531301_29_dialog_content = "Eso no será necesario. Un equipo de guardias puede encontrar PlayerName con la misma rapidez, si no más.",
  ui_story_5053_50531301_30_dialog_content = "Además, necesitamos la fuerza de todos si esperamos tener una oportunidad contra ese monstruo.",
  ui_story_5053_50531301_31_dialog_content = "Creo que sabes tan bien como yo cuál de estos asuntos es más importante. Usa tu sentido común, Daniel.",
  ui_story_5053_50531301_32_dialog_content = "(... Joshua es el único fuera de nuestro grupo que sabe sobre PlayerName.)",
  ui_story_5053_50531301_33_dialog_content = "(Ella es también la única otra persona viva dentro del Cristal de la Memoria Eterna además de nosotros).",
  ui_story_5053_50531301_34_dialog_content = "(Pero, ¿por qué querría cazar a un simple niño, uno que no tiene nada que ver con ella?)",
  ui_story_5053_50531301_35_dialog_content = "(Después de todo, decirle a Caleb que permaneciera a su lado fue la elección correcta).",
  ui_story_5053_50531301_36_dialog_content = "(Solo rezo para que no permita que la alegría de reunirse con su hermana nuble su juicio y descubra la verdad en mi lugar).",
  ui_story_5053_50531301_37_dialog_content = "Huff... huff... L-Señor Schwartz! ¡Oh, gracias a Dios que te encontré!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "¡¡¡Aaaaaah!!!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName, baja!",
  ui_story_5053_50531301_41_dialog_content = "Olvídate de la oscuridad Angel! ¡Mia está en peligro! ¡Tenemos que llegar al estrado!",
  ui_story_5053_50531301_42_dialog_content = "¿Qué quieres decir?",
  ui_story_5053_50531301_43_dialog_content = "¡Solo confía en mi! ¡¡Ahora vámonos!!",
  ui_story_5053_50531301_44_dialog_content = "Muy bien...",
  ui_story_5053_50531301_45_dialog_content = "¡Bwaaah! ¡¿Q-Qué es esto?!",
  ui_story_5053_50531301_46_dialog_content = "Quédate quieto. Te llevaré al estrado.",
  ui_story_5053_50531301_47_dialog_content = "¡¿?!",
  ui_story_5053_50531301_48_dialog_content = "D... ¿Daniel...? ¡¡¡Daniel!!!",
  ui_story_5053_50531301_49_dialog_content = "¡Ey! ¡Deja de empujar!",
  ui_story_5053_50531301_50_dialog_content = "¿Q-Qué está pasando?",
  ui_story_5053_50531301_51_dialog_content = "¡Monstruo! ¡¡Es un monstruo!!",
  ui_story_5053_50531301_52_dialog_content = "La multitud está alborotada. ¿Qué está pasando ahí abajo?",
  ui_story_5053_50531301_53_dialog_content = "<size=30> Eso es... Padre y PlayerName! Espera, ¿eso es... la oscuridad? Angel?!</size>",
  ui_story_5053_50531301_54_dialog_content = "¿Qué pasa, Verónica?",
  ui_story_5053_50531301_55_dialog_content = "N-Nada, Padre...",
  ui_story_5053_50531301_56_dialog_content = "¡Están abriéndose paso entre la multitud y hacia el stand!",
  ui_story_5053_50531301_57_dialog_content = "¡¡Detenedlos, guardias!!",
  ui_story_5053_50531301_58_dialog_content = "(La oscuridad Angel realmente está persiguiendo a Padre... Justo como dijo Madre.)",
  ui_story_5053_50531301_59_dialog_content = "(No sé por qué están corriendo de esta manera, pero tengo que protegerlo).",
  ui_story_5053_50531301_60_dialog_content = "(¡Oh, Hippoca, por favor respóndeme, te necesito más que nunca!)",
  ui_story_5053_50531301_61_dialog_content = "Verónica, ¿qué está pasando? ¿Quiénes son esos extraños que luchan entre la multitud?",
  ui_story_5053_50531301_62_dialog_content = "no lo se Carleen, pero quédate cerca de nosotros.",
  ui_story_5053_50531301_63_dialog_content = "Ese hombre en el frente es otra cosa.",
  ui_story_5053_50531301_64_dialog_content = "Está esquivando a nuestros guardias sin esfuerzo, todo mientras lleva a alguien en sus brazos.",
  ui_story_5053_50531301_65_dialog_content = "De hecho, casi parece...",
  ui_story_5053_50531301_66_dialog_content = "¡H-Él derribó a uno de los guardias y lo usó para saltar fuera de la multitud! ¡Viene directamente hacia nosotros!",
  ui_story_5053_50531301_67_dialog_content = "¡Hombres, protejan a los demás! Los manejaré yo mismo.",
  ui_story_5053_50531301_68_dialog_content = "...",
  ui_story_5053_50531301_69_dialog_content = "¿Quién eres y cuál es tu negocio aquí?",
  ui_story_5053_50531301_70_dialog_content = "¿Dónde está el peligro que mencionaste, PlayerName?",
  ui_story_5053_50531301_71_dialog_content = "¡Le hice una pregunta, señor!",
  ui_story_5053_50531301_72_dialog_content = "¡Sobre nosotros! ¡Estará aquí en cualquier segundo!",
  ui_story_5053_50531301_73_dialog_content = "¡¿De dónde salió esta asquerosa criatura?! ¡Guardias! ¡Protegeme! ¡¡¡Guardias!!!",
  ui_story_5053_50531301_74_dialog_content = "D... ¿Daniel? Daniel... Daniel...",
  ui_story_5053_50531301_75_dialog_content = "¡¡¡Aaaaaah—Daniel—!!!",
  ui_story_5053_50531301_76_dialog_content = "¡Aléjate de mi padre!",
  ui_story_5053_50531301_77_dialog_content = "... ¡Esta aquí! ¡¡El dragón está aquí ahora!!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>Rugido-!!!</size>",
  ui_story_5053_50531301_79_dialog_content = "¿Un dragón volador?",
  ui_story_5053_50531301_80_dialog_content = "Un pacto grabado en el linaje de la Casa Kartima... ¿Pero no es demasiado pronto todavía?",
  ui_story_5053_50531301_81_dialog_content = "Te aconsejaría que te concentraras en el peligro que te acecha, jovencito.",
  ui_story_5053_50531301_82_dialog_content = "Traidores de Kartima... ¡Nunca tendrás el control aquí!",
  ui_story_5053_50531301_83_dialog_content = "¡Concéntrate en tu verdadero enemigo! ¡Viene por nosotros!",
  ui_story_5053_50531301_84_dialog_content = "...",
  ui_story_5053_50531301_85_dialog_content = "¡E-El dragón! ¡Pero no se supone que debería estar aquí todavía!",
  ui_story_5053_50531301_86_dialog_content = "¡No te preocupes, Verónica! ¡Yo te protegere!",
  ui_story_5053_50531301_87_dialog_content = "No... ¡Los rebeldes pusieron en marcha su plan antes de lo que pensábamos! Ponerse a cubierto, Carleen!",
  ui_story_5053_50531301_88_dialog_content = "¿Carleen...? Verónica...?",
  ui_story_5053_50531301_89_dialog_content = "¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡",
  ui_story_5053_50531301_90_dialog_content = "¡El dragón está a punto de atacar!",
  ui_story_5053_50531301_91_dialog_content = "—!!!",
  ui_story_5053_50531301_92_dialog_content = "¡¿De dónde salió ese dragón?!",
  ui_story_5053_50531301_93_dialog_content = "¡Waaaah! Papá, ¿dónde estás?",
  ui_story_5053_50531301_94_dialog_content = "¡Está respirando fuego! ¡¡¡Correr!!!",
  ui_story_5053_50531301_95_dialog_content = "¡Hijo! ¡¿Dónde estás, hijo mío?!",
  ui_story_5053_50531301_96_dialog_content = "...",
  ui_story_5053_50531301_97_dialog_content = "¡Por favor, señor! ¿Has visto a mi hijito? Él es así de alto, y...",
  ui_story_5053_50531301_98_dialog_content = "Eliminar... a todos...",
  ui_story_5053_50531301_99_dialog_content = "¿Eh? ¿Qué dijiste?",
  ui_story_5053_50531301_100_dialog_content = "Más aliados... elimínalos a todos...",
  ui_story_5053_50531301_101_dialog_content = "Urk?! ¿Q-Qué estás...",
  ui_story_5053_50531301_102_dialog_content = "Más aliados... elimínalos a todos...",
  ui_story_5053_50531301_103_dialog_content = "*Tosiendo* ¿Verónica? ¿Padre? ¿Dónde estás?",
  ui_story_5053_50531301_104_dialog_content = "Carleen! ¿Estás bien?",
  ui_story_5053_50531301_105_dialog_content = "Estoy bien. Es que me duele la garganta de tanto polvo.",
  ui_story_5053_50531301_106_dialog_content = "Oh, gracias a Dios...",
  ui_story_5053_50531301_107_dialog_content = "Verónica... Carleen...",
  ui_story_5053_50531301_108_dialog_content = "¡Funcionó! ¡Los cuatro pudieron vencer al dragón!",
  ui_story_5053_50531301_109_dialog_content = "(Parece que solo los miembros de la familia pueden calmar la oscuridad Angel abajo. Fue una gran apuesta, ¡pero me alegro de que haya valido la pena!",
  ui_story_5053_50531301_110_dialog_content = "Todavía es demasiado pronto para celebrar.",
  ui_story_5053_50531301_111_dialog_content = "El dragón simplemente se retiró para reunir su fuerza para otro ataque de fuego.",
  ui_story_5053_50531301_112_dialog_content = "Muy pronto caerá sobre nosotros.",
  ui_story_5053_50531301_113_dialog_content = "Eso simplemente significa que debemos derrotarlo antes de que lance su próximo ataque.",
  ui_story_5053_50531301_114_dialog_content = "Entonces será mejor que hagas bien en apuntar a su punto débil.",
  ui_story_5053_50531301_115_dialog_content = "Más específicamente, necesitas atacar su—",
  ui_story_5053_50531301_116_dialog_content = "Sé dónde golpear a la bestia.",
  ui_story_5053_50531301_117_dialog_content = "¡No nos hará ningún bien! El dragón tiene algún tipo de invulnerabilidad, lo que le permite curar instantáneamente cualquier herida.",
  ui_story_5053_50531301_118_dialog_content = "¿Qué?",
  ui_story_5053_50531301_119_dialog_content = "Caballero Schwartz! ¡El levantamiento ha comenzado!",
  ui_story_5053_50531301_120_dialog_content = "Luego continúa con el plan. Reúne a más hombres y reprime a los rebeldes.",
  ui_story_5053_50531301_121_dialog_content = "Déjame el dragón a mí, y haz que los soldados restantes evacuen a la gente de esta área.",
  ui_story_5053_50531301_122_dialog_content = "Pero mi señor... ¡Los rebeldes no son los únicos que se amotinan! ¡La mayoría de las personas en el área, incluidos algunos de nuestros propios soldados, también han comenzado a atacar!",
  ui_story_5053_50531301_123_dialog_content = "¡¿Qué...?!",
  ui_story_5053_50531301_124_dialog_content = "Parecen haber perdido el control de sus cuerpos y mentes, mi señor. ¡Están arremetiendo contra cualquier criatura viviente que puedan alcanzar, ya sean amigos o enemigos!",
  ui_story_5053_50531301_125_dialog_content = "¡Pero lo más inquietante es que su locura parece contagiarse a quienquiera que logren herir! Es como si...",
  ui_story_5053_50531301_126_dialog_content = "Como si estuvieran siendo infectados y convertidos en muertos vivientes, ¿verdad?",
  ui_story_5053_50531301_127_dialog_content = "P-Precisamente.",
  ui_story_5053_50531301_128_dialog_content = "Pareces ser muy consciente de nuestra situación actual.",
  ui_story_5053_50531301_129_dialog_content = "El tiempo no está de nuestro lado, así que cuéntanos lo que sabes.",
  ui_story_5053_50531301_130_dialog_content = "Yo...",
  ui_story_5053_50531301_131_dialog_content = "(Joven Schwartz también me está mirando...)",
  ui_story_5053_50531301_132_dialog_content = "(Si no le doy una explicación lo suficientemente buena, no me dejará ir tan fácilmente).",
  ui_story_5053_50531301_133_dialog_content = "(¡Pero si le digo la verdad ahora mismo, solo hará que dude de mí! Necesito encontrar la excusa perfecta...)",
  ui_story_5053_50531301_134_dialog_content = "¿Eres tan reacio a divulgar la verdad ante mí?",
  ui_story_5053_50531301_135_dialog_content = "¿O podría ser que el culpable se encuentra entre ustedes los forasteros?",
  ui_story_5053_50531301_136_dialog_content = "¿Como tal vez ese monstruo alado allí?",
  ui_story_5053_50531301_137_dialog_content = "¡Por favor, no la llames así! Ella no es un monstruo, ella es...",
  ui_story_5053_50531301_138_dialog_content = "Allí arriba, el dragón se prepara para descender para otro ataque.",
  ui_story_5053_50531301_139_dialog_content = "Mientras un ejército de muertos vivientes nos rodea desde abajo.",
  ui_story_5053_50531301_140_dialog_content = "Estoy seguro de que sabes lo que tiene prioridad en un momento como este, ¿no?",
  ui_story_5053_50531301_141_dialog_content = "... Por supuesto que lo sé.",
  ui_story_5053_50531301_142_dialog_content = "Guardia, contacta a Lachon y Otto, y diles que los soldados en la plaza están ahora bajo su mando.",
  ui_story_5053_50531301_143_dialog_content = "Diles que fortalezcan las defensas del puesto y que traigan aquí a los supervivientes que no estén infectados.",
  ui_story_5053_50531301_144_dialog_content = "¡Si mi señor!",
  ui_story_5053_50531301_145_dialog_content = "(Suerte que señor Schwartz fue capaz de quitarme de encima a su yo más joven. Debe haberse dado cuenta de que tengo mis razones para no decirle la verdad.)",
  ui_story_5053_50531301_146_dialog_content = "(No puedo perder otro segundo de nuestro tiempo, no después de haber llegado tan lejos. Es hora de que regresemos a Schwartz ¡Mansión!)",
  ui_story_5053_50531301_147_dialog_content = "Verónica... ¿Por qué me llama por mi nombre?",
  ui_story_5053_50531301_148_dialog_content = "Solo mantén tu distancia de ella, Carleen.",
  ui_story_5053_50531301_149_dialog_content = "Verónica... Carleen... Estás herido...?",
  ui_story_5053_50531301_150_dialog_content = "Estás herido...?",
  ui_story_5053_50531301_151_dialog_content = "Te abrazaré... y cantaré...",
  ui_story_5053_50531301_152_dialog_content = "¿Eh? Estoy bien, y también Carleen.",
  ui_story_5053_50531301_153_dialog_content = "Entonces puedes comunicarte con nosotros después de todo... Eres parte de Madre, ¿no es así?",
  ui_story_5053_50531301_154_dialog_content = "Madre... Yo soy.. Madre...",
  ui_story_5053_50531301_155_dialog_content = "Entonces, ¿podrías dejar de atacarnos? ¿Puedes por favor dejar de intentar lastimar a Padre?",
  ui_story_5053_50531301_156_dialog_content = "Verónica... ¿Padre? ¡¡¡Daniel...Daniel...!!!",
  ui_story_5053_50531301_157_dialog_content = "¡N-Nunca quisiste que los viéramos a ustedes dos peleando!",
  ui_story_5053_50531301_158_dialog_content = "¿No es así?",
  ui_story_5053_50531301_159_dialog_content = "...",
  ui_story_5053_50531301_160_dialog_content = "No más... No más peleas... Asusta a las chicas...",
  ui_story_5053_50531301_161_dialog_content = "No más peleas... Verónica... no tengas miedo...",
  ui_story_5053_50531301_162_dialog_content = "Lo sé, madre. Gracias.",
  ui_story_5053_50531301_163_dialog_content = "(Madre dijo que la oscuridad Angel nació de una Semilla, y que ella no era más que una bestia sin mente.)",
  ui_story_5053_50531301_164_dialog_content = "(Pero no solo puedo comunicarme con ella... Incluso puedo sentir cierta amabilidad proveniente de ella).",
  ui_story_5053_50531301_165_dialog_content = "(Una amabilidad que no he sentido de la madre en la mansión. ¿Qué diablos está pasando...?)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>¡Ey! ¡Por aquí, Verónica!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName! ¡Padre! ¿Están ustedes dos bien?",
  ui_story_5053_50531301_168_dialog_content = "¡Shhh! ¡Mantenerla baja!",
  ui_story_5053_50531301_169_dialog_content = "mientras los jóvenes Schwartz está ocupado luchando contra el dragón, nosotros tres y la oscuridad Angel necesito partir.",
  ui_story_5053_50531301_170_dialog_content = "¿Dejar? Pero ¿adónde? ¿Y por qué la oscuridad Angel tiene que venir con nosotros?",
  ui_story_5053_50531301_171_dialog_content = "A Schwartz Mansión. Caleb y Jakine corren grave peligro.",
  ui_story_5053_50531301_172_dialog_content = "¿Eh? Lo siento, todo esto es tan confuso. ¿Qué es exactamente...",
  ui_story_5053_50531301_173_dialog_content = "PlayerName ha prometido explicar todo en el camino. Debemos irnos mientras todavía tenemos la oportunidad.",
  ui_story_5053_50531301_174_dialog_content = "S-Sí, entonces.",
  ui_story_5053_50531301_175_dialog_content = "Daniel...",
  ui_story_5053_50531301_176_dialog_content = "Y estás seguro de que no me volverá a atacar, PlayerName?",
  ui_story_5053_50531301_177_dialog_content = "Uh, estoy bastante seguro de que estás a salvo por ahora...",
  ui_story_5053_50531301_178_dialog_content = "No lo hará, padre. Madre ya me prometió que no lo haría, ¿verdad?",
  ui_story_5053_50531301_179_dialog_content = "Prometo...",
  ui_story_5053_50531301_180_dialog_content = "... Bien.",
  ui_story_5053_50531301_181_dialog_content = "La parte posterior del stand debe estar libre de espectadores. Deberíamos irnos antes de que terminen de reforzar sus defensas.",
  ui_story_5053_50531301_182_dialog_content = "¿Adónde vas, Verónica?",
  ui_story_5053_50531301_183_dialog_content = "Padre nos dijo que nos quedáramos aquí y esperáramos a que la Sra. Rot nos escoltara a un lugar seguro.",
  ui_story_5053_50531301_184_dialog_content = "Lo lamento, Carleen, pero no puedo quedarme. Hay algo muy importante que debo hacer.",
  ui_story_5053_50531301_185_dialog_content = "Pero una chica valiente como tú no debería tener problemas para esperar sola a la Sra. Rot, ¿verdad?",
  ui_story_5053_50531301_186_dialog_content = "Estaré bien, pero estoy más preocupado por ti, Verónica.",
  ui_story_5053_50531301_187_dialog_content = "Cuando te vas solo, normalmente es para llorar solo...",
  ui_story_5053_50531301_188_dialog_content = "¡Pero ya no necesitas llorar, Verónica! ¡Te prometo que algún día me haré más fuerte y te protegeré, pase lo que pase!",
  ui_story_5053_50531301_189_dialog_content = "Jejeje... En qué persona tan valiente y madura te has convertido, Carleen.",
  ui_story_5053_50531301_190_dialog_content = "Tampoco tienes que preocuparte. No soy tan débil e indefenso como solía ser.",
  ui_story_5053_50531301_191_dialog_content = "Tu hermana mayor estará perfectamente bien, lo prometo.",
  ui_story_5053_50531301_192_dialog_content = "Sé que siempre estuve medio paso detrás de ti en el pasado y puse las cosas difíciles para todos.",
  ui_story_5053_50531301_193_dialog_content = "Pero de ahora en adelante, trabajaré duro y me convertiré en una hermana mayor confiable que pueda ayudarte a llevar tu carga.",
  ui_story_5053_50531301_194_dialog_content = "Verónica...?",
  ui_story_5053_50531301_195_dialog_content = "Así que, por favor, confía en mí.",
  ui_story_5053_50531301_196_dialog_content = "Sí. Confío en ti.",
  ui_story_5053_50531301_197_dialog_content = "Jejeje, gracias.",
  ui_story_5053_50531301_198_dialog_content = "Hasta la próxima... Mi dulce, pequeña Carleen.",
  ui_story_5053_50531302_1_dialog_content = "... Esta es la situación actual en la plaza central.",
  ui_story_5053_50531302_2_dialog_content = "Todos los pasajes que conducen a la plaza han sido completamente sellados.",
  ui_story_5053_50531302_3_dialog_content = "Bajo el mando de Lord Schwartz, los disturbios comienzan a estar bajo control. Puede tranquilizarse, su alteza.",
  ui_story_5053_50531302_4_dialog_content = "... Comprendido. Usted puede irse ahora.",
  ui_story_5053_50531302_5_dialog_content = "Como desees.",
  ui_story_5053_50531302_6_dialog_content = "Ahora bien, ¿serías tan amable de cerrar la puerta para nosotros? Jakine?",
  ui_story_5053_50531302_7_dialog_content = "¡Oh, por supuesto! ¡Después de todo, incluso una simple cerradura puede hacer maravillas por nuestra seguridad!",
  ui_story_5053_50531302_8_dialog_content = "Déjame hacerte una pregunta, Caleb. ¿Por qué quieres rescatarme?",
  ui_story_5053_50531302_9_dialog_content = "¿Ah?",
  ui_story_5053_50531302_10_dialog_content = "¿Mmm? ¡Porque eres mi hermana, por supuesto! ¿Qué hermano no querría ayudar a su propia hermana?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5053_50531302_12_dialog_content = "Dama Joshua, he venido a escoltarte a un lugar seguro. May ¿Entro?",
  ui_story_5053_50531302_13_dialog_content = "¡Claro, solo entra aquí!",
  ui_story_5053_50531302_14_dialog_content = "Jakine, ¿has olvidado que eres un invitado aquí? ¡Mi hermana no había terminado de hablar!",
  ui_story_5053_50531302_15_dialog_content = "...",
  ui_story_5053_50531302_16_dialog_content = "Perdona la interrupción...",
  ui_story_5053_50531302_17_dialog_content = "¿Qué es, Sra. Rot?",
  ui_story_5053_50531302_18_dialog_content = "Me dijeron que no te sentías bien hoy. Como tal, Señor Schwartz me ordenó quedarme a tu lado y velar por tu seguridad.",
  ui_story_5053_50531302_19_dialog_content = "Dada la gravedad de la situación, debo pedirte que me sigas a otro lugar seguro.",
  ui_story_5053_50531302_20_dialog_content = "Una vez que te hayas refugiado, escoltaré a la princesa. Carleen a la seguridad también. Tenga la seguridad de que no dejaré que sufra ningún daño.",
  ui_story_5053_50531302_21_dialog_content = "Veo. Que amable de tu parte.",
  ui_story_5053_50531302_22_dialog_content = "Sin embargo, mis invitados y yo estamos perfectamente seguros aquí. En todo caso, deberías preocuparte más por la seguridad de Carleen ahora mismo.",
  ui_story_5053_50531302_23_dialog_content = "Me temo que no puedo hacer eso.",
  ui_story_5053_50531302_24_dialog_content = "Si me fuera ahora mismo... No tendría ningún problema en asesinar a sus dos invitados en mi ausencia.",
  ui_story_5053_50531302_25_dialog_content = "¿M-asesinato?",
  ui_story_5053_50531302_26_dialog_content = "¡¿Cuál es el significado de esto, Sra. Rot?! Mi hermana nunca...",
  ui_story_5053_50531302_27_dialog_content = "... Joshua?",
  ui_story_5053_50531302_28_dialog_content = "Sí, Caleb. Nunca haría algo tan violentamente atroz.",
  ui_story_5053_50531302_29_dialog_content = "¿Por qué diablos me acusaría de eso, Sra. Rot?",
  ui_story_5053_50531302_30_dialog_content = "Puedes prescindir del acto.",
  ui_story_5053_50531302_31_dialog_content = "La daga está escondida en tu pierna, ¿no es así? Todo el método clásico de asesinato.",
  ui_story_5053_50531302_32_dialog_content = "Tu habilidad para ocultar armas es incomparable, pero tu mano sobre la empuñadura hace que tus intenciones sean demasiado obvias.",
  ui_story_5053_50531302_33_dialog_content = "...",
  ui_story_5053_50531302_34_dialog_content = "Eres un asesino altamente entrenado, y no puede haber ninguna duda.",
  ui_story_5053_50531302_35_dialog_content = "Te pareces tanto a mi maestro, pero no eres más que un impostor extremadamente convincente.",
  ui_story_5053_50531302_36_dialog_content = "¿Un impostor? P-Pero su voz y apariencia... ¡Nunca podría confundirlos!",
  ui_story_5053_50531302_37_dialog_content = "Tiene razón, ¡y el Cristal de la Memoria Eterna muestra claramente que ella también es una persona que vive y respira!",
  ui_story_5053_50531302_38_dialog_content = "¿Cuáles son las probabilidades de que alguien más esté aquí haciéndose pasar por Lady? Joshua?!",
  ui_story_5053_50531302_39_dialog_content = "No sé cómo están conectados ustedes dos con esta asesina, pero por su seguridad, les sugiero que se mantengan alejados de ella.",
  ui_story_5053_50531302_40_dialog_content = "Si tuviera que adivinar, debes ser otro remanente de esa organización, uno a quien también entrenaron en las artes de matar.",
  ui_story_5053_50531302_41_dialog_content = "Después de todo, el parecido entre tú y mi antiguo maestro es asombroso.",
  ui_story_5053_50531302_42_dialog_content = "Es precisamente por eso que nunca podrías reemplazarla. La dama Joshua de hoy es una esposa amorosa, una madre cariñosa y una hermana cariñosa.",
  ui_story_5053_50531302_43_dialog_content = "¿Estoy en lo correcto al decir eso?",
  ui_story_5053_50531302_44_dialog_content = "...",
  ui_story_5053_50531302_45_dialog_content = "L-dama Joshua tiene una daga en sus manos! ¿Cómo diablos sacó eso de la nada...?",
  ui_story_5053_50531302_46_dialog_content = "¡Argh, eso lo hace! ¿Dónde está mi bola de cristal?",
  ui_story_5053_50531302_47_dialog_content = "No hay duda de que, Jakine... Ella realmente es mi hermana. Pero cómo... ¡¿Cómo podría ser esto?!",
  ui_story_5053_50531302_48_dialog_content = "¡Deja de dar vueltas, Caleb! ¡Si no vas a pelear, entonces ponte a cubierto!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>¡Aaaaaah—!</size>",
  ui_story_5053_50531302_50_dialog_content = "¡¡E-Eres tú—!!",
  ui_story_5053_50531302_51_dialog_content = "es la oscuridad Angel!",
  ui_story_5053_50531302_52_dialog_content = "La oscuridad Angel...?",
  ui_story_5053_50531302_53_dialog_content = "Lejos... de Caleb...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>Deja... Caleb... ¡¡¡Solo!!!</size>",
  ui_story_5053_50531302_55_dialog_content = "¡¿Qué estás haciendo aquí?!",
  ui_story_5053_50531302_56_dialog_content = "¡Aléjate de mí, cosa repugnante!",
  ui_story_5053_50531302_57_dialog_content = "¡No hay escapatoria!",
  ui_story_5053_50531302_58_dialog_content = "Primera mujer Joshua quiere matarnos, y ahora la Oscuridad Angel la ahuyentó...",
  ui_story_5053_50531302_59_dialog_content = "¡¿Q-Qué diablos está pasando ya?! ¡Alguien tiene que explicar este lío ahora mismo!",
  ui_story_5053_50531302_60_dialog_content = "¡W-Whoa, Hipoca! Detener...!!",
  ui_story_5053_50531302_61_dialog_content = "¡Bwaaa! ¡Y ahora un caballo araña gigante acaba de volar por la ventana!",
  ui_story_5053_50531302_62_dialog_content = "Esperar... PlayerName?! Con Mia y señor Schwartz!",
  ui_story_5053_50531302_63_dialog_content = "Bien hecho, Mia. Parece que tienes un buen don cuando se trata de usar tu invocación de Lumina como montura.",
  ui_story_5053_50531302_64_dialog_content = "*Jadeando* Para ser honesto... Esa fue la primera vez que usé a Hippoca así...",
  ui_story_5053_50531302_65_dialog_content = "Ugh... Saltamos tantos edificios a lomos de Hippoca... Creo que me voy a enfermar...",
  ui_story_5053_50531302_66_dialog_content = "Que sois los tres...",
  ui_story_5053_50531302_67_dialog_content = "Oh bien, se parece a Caleb y Jakine todavía están bien...",
  ui_story_5053_50531302_68_dialog_content = "Menos mal que llegamos a tiempo... ¡Urk...!",
  ui_story_5053_50531401_1_dialog_content = "Así que estás diciendo que este Demonio Blanco ha estado tomándonos por tontos todo el tiempo.",
  ui_story_5053_50531401_2_dialog_content = "Y que ella y la Oscuridad Angel ambos son parte de Lady Joshua, pero no pueden llegar a un acuerdo entre sí.",
  ui_story_5053_50531401_3_dialog_content = "Así que su plan es matarnos a todos, absorber nuestra Lumina y liberarse con ella...",
  ui_story_5053_50531401_4_dialog_content = "Aunque suene tan increíble, creo que entiendo sus circunstancias.",
  ui_story_5053_50531401_5_dialog_content = "El dolor atroz, el miedo a su otro yo...",
  ui_story_5053_50531401_6_dialog_content = "Pero a pesar de que somos tan diferentes, Baba Yaga y yo somos la misma persona.",
  ui_story_5053_50531401_7_dialog_content = "Y si pude aprender a convivir con ella, entonces seguramente mi madre podría...",
  ui_story_5053_50531401_8_dialog_content = "¿Crees que todavía tenemos la oportunidad de convencer al Demonio Blanco de que abandone su loco plan? PlayerName?",
  ui_story_5053_50531401_9_dialog_content = "Bueno... creo que solo la verdadera Dama Joshua sabría eso.",
  ui_story_5053_50531401_10_dialog_content = "Todo lo que sé es que el Cristal de la Memoria Eterna está casi fuera de Lumina.",
  ui_story_5053_50531401_11_dialog_content = "Esta es nuestra última oportunidad de salir de aquí. No podemos perder el tiempo pensando demasiado en las cosas.",
  ui_story_5053_50531401_12_dialog_content = "Por favor, perdóname, pero no pude someter a la otra dama. Joshua.",
  ui_story_5053_50531401_13_dialog_content = "Un guardia me acaba de alertar que la situación en la plaza central ya está bajo control.",
  ui_story_5053_50531401_14_dialog_content = "Sin embargo, el dragón sigue siendo una amenaza implacable. Nuestras fuerzas no durarán mucho más contra un enemigo imbatible como este.",
  ui_story_5053_50531401_15_dialog_content = "Gracias por su ayuda, Sra. Rot. Puede dejarnos el resto a nosotros.",
  ui_story_5053_50531401_16_dialog_content = "Me temo que debo negarme.",
  ui_story_5053_50531401_17_dialog_content = "Mi deber es proteger House Schwartz y todo Lumopolis.",
  ui_story_5053_50531401_18_dialog_content = "Si soy o no solo una ilusión no tiene nada que ver con mi deber. Soy, y siempre seré, la Sra. Rot.",
  ui_story_5053_50531401_19_dialog_content = "Incluso frente a una crisis existencial tan discordante, tu compostura permanece inquebrantable.",
  ui_story_5053_50531401_20_dialog_content = "Jejeje... Honestamente, darme cuenta de esto me ha dado una sensación de alivio.",
  ui_story_5053_50531401_21_dialog_content = "Ahora que sé que no hay futuro para mí, no tengo motivos para preocuparme constantemente por ello.",
  ui_story_5053_50531401_22_dialog_content = "Si alguien está sufriendo por la verdad en este momento, sería el Sr. Caleb.",
  ui_story_5053_50531401_23_dialog_content = "Joshua... Nunca quiso que nadie supiera la verdad sobre su pasado.",
  ui_story_5053_50531401_24_dialog_content = "Por un lado, revelar su pasado solo invitaría a más críticas.",
  ui_story_5053_50531401_25_dialog_content = "Sin embargo, creo que la verdadera razón fue que ella no tuvo el corazón para confesárselo a su hermano pequeño.",
  ui_story_5053_50531401_26_dialog_content = "En cierto modo, la fuerza y la bondad que descubrió a lo largo de los años también dieron origen a su mayor debilidad.",
  ui_story_5053_50531401_27_dialog_content = "Sé lo que quieres decir. para dama Joshua haber crecido y experimentado tantas emociones es algo positivo.",
  ui_story_5053_50531401_28_dialog_content = "Pero a veces, un problema solo puede resolverse comunicándose abierta y sinceramente, incluso cuando hacerlo es aterrador.",
  ui_story_5053_50531401_29_dialog_content = "cuando dama Joshua finalmente vuelve a despertar en el mundo real, debo pedirte que también compartas estos sinceros pensamientos con ella.",
  ui_story_5053_50531401_30_dialog_content = "De lo contrario, puede enfurecerse tanto que pierda el conocimiento una vez más.",
  ui_story_5053_50531401_31_dialog_content = "... Me acordaré de hacerlo.",
  ui_story_5053_50531401_32_dialog_content = "Señor Schwartz? ¿Tú y la Srta. Rot ya terminaron de hablar? Todavía tenemos que hablar sobre el siguiente paso de nuestro plan.",
  ui_story_5053_50531401_33_dialog_content = "Seguramente.",
  ui_story_5053_50531401_34_dialog_content = "... Espera, ¿dónde está Caleb? ¿Ya se siente mejor?",
  ui_story_5053_50531401_35_dialog_content = "Déjalo en paz por ahora.",
  ui_story_5053_50531401_36_dialog_content = "...",
  ui_story_5053_50531401_37_dialog_content = "¿Eres... realmente mi hermana...?",
  ui_story_5053_50531401_38_dialog_content = "—!",
  ui_story_5053_50531401_39_dialog_content = "¿Por qué te escondes de mí?",
  ui_story_5053_50531401_40_dialog_content = "¿El Demonio Blanco estaba diciendo la verdad? ¿Es posible que... nunca me hayas visto realmente como una familia?",
  ui_story_5053_50531401_41_dialog_content = "... No...",
  ui_story_5053_50531401_42_dialog_content = "Caleb... Estoy... Asustado...",
  ui_story_5053_50531401_43_dialog_content = "¿Asustada?",
  ui_story_5053_50531401_44_dialog_content = "Caleb... me amaba... confiaba en mí...",
  ui_story_5053_50531401_45_dialog_content = "Me duele el pecho... la presión... no puedo respirar...",
  ui_story_5053_50531401_46_dialog_content = "Padre.. déjalo ir... murió... para protegerme... Todo... mi culpa...",
  ui_story_5053_50531401_47_dialog_content = "Qué quieres decir...?",
  ui_story_5053_50531401_48_dialog_content = "La otra parte de ti dijo que Padre se suicidó para preservar las brasas de la venganza.",
  ui_story_5053_50531401_49_dialog_content = "Sin embargo, estás diciendo que lo dejó pasar todo... Ya no puedo decir cuál es la verdad.",
  ui_story_5053_50531401_50_dialog_content = "Te hiciste pasar por mi hermana durante todos esos años, solo para poder asesinar al padre de Schwartz.",
  ui_story_5053_50531401_51_dialog_content = "Me criaste y me cuidaste como una verdadera hermana... No, como una madre.",
  ui_story_5053_50531401_52_dialog_content = "Todos esos años de aguantarme... El estrés debe haber sido insoportable.",
  ui_story_5053_50531401_53_dialog_content = "... Pero ya no importa, Joshua. Tu felicidad siempre será mi prioridad, ahora y siempre.",
  ui_story_5053_50531401_54_dialog_content = "Una vez que volvamos a la realidad, si realmente no me ves como tu hermano... Entonces no te molestaré nunca más. Quiero que vivas libre y sin remordimientos, tal como siempre has querido.",
  ui_story_5053_50531401_55_dialog_content = "No... Por favor... no me dejes... Caleb...",
  ui_story_5053_50531401_56_dialog_content = "Me equivoqué... en mentir... pero... tenía miedo...",
  ui_story_5053_50531401_57_dialog_content = "Asustado... tú... me odiarías...",
  ui_story_5053_50531401_58_dialog_content = "...",
  ui_story_5053_50531401_59_dialog_content = "Nunca podría odiarte, Joshua.",
  ui_story_5053_50531401_60_dialog_content = "Eres la hermana más hermosa y gentil que alguien podría desear.",
  ui_story_5053_50531401_61_dialog_content = "¿Cómo podría estar resentido contigo de alguna manera?",
  ui_story_5053_50531401_62_dialog_content = "Muy bien, déjame repasar todo por última vez.",
  ui_story_5053_50531401_63_dialog_content = "Tal como está, hemos puesto fin al plan anterior del Demonio Blanco para matarnos.",
  ui_story_5053_50531401_64_dialog_content = "Sin ningún otro lugar a donde ir, hay una buena posibilidad de que use al dragón y a esas personas controladas mentalmente para lanzar un ataque final desesperado.",
  ui_story_5053_50531401_65_dialog_content = "A pesar de que tenemos la ventaja numérica ahora, y los jóvenes Schwartz todavía está defendiéndose del dragón...",
  ui_story_5053_50531401_66_dialog_content = "Él y sus fuerzas no podrán luchar con toda su fuerza, no con la poca Lumina que queda en el Cristal de la Memoria Eterna.",
  ui_story_5053_50531401_67_dialog_content = "No solo eso, solo quedan unas pocas horas en el día.",
  ui_story_5053_50531401_68_dialog_content = "Necesitamos un método simple y efectivo que nos permita lidiar con todos los peones del Demonio Blanco en el menor tiempo posible.",
  ui_story_5053_50531401_69_dialog_content = "Es la única forma en que podremos capturarla.",
  ui_story_5053_50531401_70_dialog_content = "¿Ese Cristal de la Memoria Eterna tiene alguna otra función que podamos usar, Jakine? ¿Podemos usarlo para manipular las otras ilusiones, como el Demonio Blanco?",
  ui_story_5053_50531401_71_dialog_content = "Mmm... ¡No! Con la poca Lumina que le queda, el Cristal de la Memoria Eterna no puede usarse para otra cosa que no sea sostener el mundo que nos rodea.",
  ui_story_5053_50531401_72_dialog_content = "Además, este Cristal de la memoria eterna es solo un dispositivo a prueba de fallas.",
  ui_story_5053_50531401_73_dialog_content = "En primer lugar, nunca debería haberse usado tanto... Ya hemos roto suficientes reglas desde que lo tenemos en nuestras manos.",
  ui_story_5053_50531401_74_dialog_content = "¡Pero si logré armar un encantamiento aún mejor que la última vez...!",
  ui_story_5053_50531401_75_dialog_content = "No, Jakine. Nuestra situación es demasiado grave para que recurramos a otro de tus hechizos improvisados.",
  ui_story_5053_50531401_76_dialog_content = "Jejejeje... Lo tengo.",
  ui_story_5053_50531401_77_dialog_content = "Eso no será necesario.",
  ui_story_5053_50531401_78_dialog_content = "Todo lo que tenemos que hacer es dejar que se destruyan a sí mismos.",
  ui_story_5053_50531401_79_dialog_content = "¡Bienvenido de nuevo, Caleb! ¿Ya terminaron de llorar?",
  ui_story_5053_50531401_80_dialog_content = "¡No estaba llorando! ¡Cómo te atreves a tratarme como a un niño!",
  ui_story_5053_50531401_81_dialog_content = "¿Qué quieres decir con eso, Caleb? ¿Por qué se destruirían a sí mismos si estuvieran todos bajo el control del Demonio Blanco?",
  ui_story_5053_50531401_82_dialog_content = "Es simple, de verdad.",
  ui_story_5053_50531401_83_dialog_content = "Al alterar el equilibrio de Lumina en sus cuerpos, perderán la capacidad de controlarse a sí mismos. Dolorosamente, podría añadir.",
  ui_story_5053_50531401_84_dialog_content = "¿El \"equilibrio de Lumina\"? Nunca he oído hablar de algo así antes.",
  ui_story_5053_50531401_85_dialog_content = "Hmph, los aurorianos comunes nunca podrían entender, pero creo que nuestro amigo caelestita sabe exactamente de lo que estoy hablando. ¿No es así?",
  ui_story_5053_50531401_86_dialog_content = "¿M-Yo? Uh... Bueno, he notado algo diferente en sus estelas de luz...",
  ui_story_5053_50531401_87_dialog_content = "Tu dudosa respuesta es... Bastante decepcionante.",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName, Sentí que Caleb se había vuelto más hostil hacia nosotros antes. ¿Quizás en realidad es una persona podrida?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>Bueno, sin comentarios...</size>",
  ui_story_5053_50531401_90_dialog_content = "¡Ustedes dos! ¡No chatear mientras la clase está en sesión!",
  ui_story_5053_50531401_91_dialog_content = "Basta de tonterías, Caleb. Cuéntanos tu plan.",
  ui_story_5053_50531401_92_dialog_content = "Puedo preparar cierto tipo de droga, una poción que puede desestabilizar la Lumina del usuario. Piense en ello como un veneno que apunta directamente a Lumina.",
  ui_story_5053_50531401_93_dialog_content = "Todo dentro del Cristal de la Memoria Eterna fue creado a través de una combinación de Lumina de Joshua y el agua del Lago Mirror.",
  ui_story_5053_50531401_94_dialog_content = "Como resultado, esta droga debería resultar altamente efectiva contra nuestros enemigos.",
  ui_story_5053_50531401_95_dialog_content = "Pero con tan pocos ingredientes a mano, propongo que lo usemos para combatir al dragón.",
  ui_story_5053_50531401_96_dialog_content = "Los títeres controlados por la mente del Demonio Blanco no son más que hormigas perniciosas. Si derribamos al dragón sobre ellos...",
  ui_story_5053_50531401_97_dialog_content = "El dolor inducido por la droga hará que la pisoteen y se retuerza en el suelo, aplastando a nuestros adversarios en el proceso.",
  ui_story_5053_50531401_98_dialog_content = "¡Ajá! Entonces, en otras palabras, si logramos alimentar al dragón con el veneno, ¡caerá sobre sus cabezas sin sentido!",
  ui_story_5053_50531401_99_dialog_content = "... Por así decirlo, sí.",
  ui_story_5053_50531401_100_dialog_content = "Debo decir que su plan es bastante indicativo de su estilo habitual. Siempre te han gustado los trucos simples pero siniestros como este.",
  ui_story_5053_50531401_101_dialog_content = "Me sorprende que todavía lo recuerde, mi señor. ¿Fue mi taza de té realmente tan memorable?",
  ui_story_5053_50531401_102_dialog_content = "(Espera... ¿Caleb envenenó a Lord? Schwartz ¡¿en el pasado?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>¡Realmente no eres una buena persona después de todo, Caleb!</size>",
  ui_story_5053_50531401_104_dialog_content = "Pfff... jejeje...",
  ui_story_5053_50531401_105_dialog_content = "Dejar de reír, Mia.",
  ui_story_5053_50531401_106_dialog_content = "Lo siento, no pude evitarlo... Espera, no quise decir eso...",
  ui_story_5053_50531401_107_dialog_content = "Sólo tengo suficientes ingredientes para hacer una sola poción. Necesitaré a alguien poderoso para someter al dragón el tiempo suficiente para que yo pueda administrar la poción. Alguien como tu.",
  ui_story_5053_50531401_108_dialog_content = "¿E-eh? A mí...?!",
  ui_story_5053_50531401_109_dialog_content = "Sí tú. Ahora sígueme.",
  ui_story_5053_50531401_110_dialog_content = "¡E-Espera, tío...!",
  ui_story_5053_50531401_111_dialog_content = "¡Ahí va, corriendo para hacer lo suyo otra vez! ¿Crees que deberíamos seguirlos?",
  ui_story_5053_50531401_112_dialog_content = "Déjale el dragón a Caleb. Yo creo en él, así como Mia.",
  ui_story_5053_50531401_113_dialog_content = "Caballero Schwartz...",
  ui_story_5053_50531401_114_dialog_content = "Según tú, siempre logro sobrevivir a los planes del Demonio Blanco hasta el final, pero nunca puedo cambiar el resultado.",
  ui_story_5053_50531401_115_dialog_content = "Ustedes, jóvenes héroes, por otro lado, son mucho más capaces de dar forma al futuro de lo que yo podría ser.",
  ui_story_5053_50531401_116_dialog_content = "Siempre pensé que podía proteger todo con mis propias manos... Pero parece que ha llegado el momento de dejar de lado mi obstinado orgullo.",
  ui_story_5053_50531401_117_dialog_content = "Entonces, ¿deberíamos quedarnos aquí por ahora?",
  ui_story_5053_50531401_118_dialog_content = "Sí, Jakine. Nos quedaremos aquí para reunir nuestro ingenio y nuestras fuerzas.",
  ui_story_5053_50531401_119_dialog_content = "Conociendo al Demonio Blanco, aparecerá ante nosotros para una última batalla después de que su carta de triunfo haya sido derrotada.",
  ui_story_5053_50531401_120_dialog_content = "Ese es el tipo de oponente tenaz al que nos enfrentamos.",
  ui_story_5053_50531401_121_dialog_content = "Además...",
  ui_story_5053_50531401_122_dialog_content = "...",
  ui_story_5053_50531401_123_dialog_content = "Todavía tengo que convencerla de que se vaya con nosotros.",
  ui_story_5053_50531401_125_dialog_content = "Así que nos encontramos aquí una vez más. Tú y yo, parados en esta mesa por la noche.",
  ui_story_5053_50531401_126_dialog_content = "...",
  ui_story_5053_50531401_127_dialog_content = "La última vez que esto sucedió, traté de cambiar el resultado de nuestra pelea fingiendo ser mi yo más joven.",
  ui_story_5053_50531401_128_dialog_content = "Dije que no deseaba lastimarte más, pero en este mundo ilusorio, mis acciones buscaban la satisfacción propia y nada más.",
  ui_story_5053_50531401_129_dialog_content = "Irónicamente, estuviste parado frente a mí todo el tiempo, siendo testigo de mi peor momento. No es de extrañar que estés tan enojado conmigo.",
  ui_story_5053_50531401_130_dialog_content = "D-Daniel...",
  ui_story_5053_50531401_131_dialog_content = "Usted tenía razón. Todo esto es culpa mía, y tu venganza contra mí está perfectamente justificada. Sin embargo, no puedes matarme todavía.",
  ui_story_5053_50531401_132_dialog_content = "Estos niños son inocentes y no merecen morir en este lugar.",
  ui_story_5053_50531401_133_dialog_content = "Así que, por favor, ayúdanos a capturar tu otra mitad para que podamos escapar. ¿Qué dices?",
  ui_story_5053_50531401_134_dialog_content = "Los niños son... el futuro... Debemos... proteger el futuro...",
  ui_story_5053_50531401_135_dialog_content = "Entonces estamos de acuerdo. Gracias, Joshua... Gracias por creer en mí una vez más.",
  ui_story_5053_50531401_136_dialog_content = "...",
  ui_story_5053_50531401_137_dialog_content = "Caleb y Mia solo queda. Deberíamos tratar de recuperar nuestras fuerzas por ahora.",
  ui_story_5053_50531401_138_dialog_content = "¿Todavía recuerdas esa canción, Joshua?",
  ui_story_5053_50531401_139_dialog_content = "Sí... Una canción de... Lower Lumopolis... sobre... una vida feliz...",
  ui_story_5053_50531401_140_dialog_content = "Sí, esa misma canción. A decir verdad, te preparé un regalo hace doce años.",
  ui_story_5053_50531401_141_dialog_content = "Pero en el calor del momento, olvidé dártelo. Si mal no recuerdo... Debería estar justo aquí.",
  ui_story_5053_50531401_142_dialog_content = "¿Un expediente?",
  ui_story_5053_50531401_143_dialog_content = "Así es. Hice que alguien grabara una versión bailable de esa misma canción. ¿Te gustaría escucharlo? Después de todo, hay un tocadiscos aquí mismo.",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>...♪</color>",
  ui_story_5053_50531401_145_dialog_content = "¡...!",
  ui_story_5053_50531401_146_dialog_content = "Me alegra ver que lo disfrutas, Joshua.",
  ui_story_5053_50531401_147_dialog_content = "Pero sería un desperdicio simplemente escuchar una canción tan maravillosa.",
  ui_story_5053_50531401_148_dialog_content = "Bueno, mi bella dama? May tengo este baile?",
  ui_story_5053_50531401_149_dialog_content = "...",
  ui_story_5053_50531401_150_dialog_content = "...",
  ui_story_5053_50531401_151_dialog_content = "Papá... Daniel...",
  ui_story_5053_50531401_152_dialog_content = "¿Si?",
  ui_story_5053_50531401_153_dialog_content = "¿Están todos... bien...?",
  ui_story_5053_50531401_154_dialog_content = "...Sí, bastante bien.",
  ui_story_5053_50531401_155_dialog_content = "Carleen ahora es Capitán de la Guardia de Lumopolis y dirige un equipo de subordinados ejemplares. No solo eso, también ha hecho muchos amigos confiables.",
  ui_story_5053_50531401_156_dialog_content = "Mia continúa viviendo bajo el cuidado y la guía de Istvan. Su condición ha mejorado mucho; Escuché que ahora incluso puede salir y jugar durante el día.",
  ui_story_5053_50531401_157_dialog_content = "En cuanto a Caleb... Parece que le está yendo bastante bien en el Dawn Academia. Apuesto a que te extraña más que a nadie en el mundo.",
  ui_story_5053_50531401_158_dialog_content = "Qué pasa contigo...?",
  ui_story_5053_50531401_159_dialog_content = "¿Yo?",
  ui_story_5053_50531401_160_dialog_content = "Mi tiempo ha terminado ahora, Joshua.",
  ui_story_5053_50531401_161_dialog_content = "Estaba tan indefenso en el pasado, y cometí más errores de los que podía contar, pero ahora. Ahora, nuestros hijos se paran sobre mis hombros, alcanzando mayores alturas de las que jamás conoceré.",
  ui_story_5053_50531401_162_dialog_content = "Todo lo que me queda por hacer es estar en este lugar, apoyándolos en su lucha por un futuro mejor.",
  ui_story_5053_50531401_163_dialog_content = "El futuro ideal que tú y yo siempre hemos soñado.",
  ui_story_5053_50531401_164_dialog_content = "Cuando regresemos, puedo arreglar que te recuperes en la seguridad y privacidad de la casa de Caleb.",
  ui_story_5053_50531401_165_dialog_content = "Después, haré que Veronica regrese para acompañarte y compartir las buenas noticias con Carleen. Pronto, nuestra familia estará completa de nuevo.",
  ui_story_5053_50531401_166_dialog_content = "Solo que ahora... Bueno, como puedes ver, he envejecido bastante. Puede que sea aún menos digno de su compañía ahora, pero le agradecería que me permitiera visitarlo de vez en cuando. ¿Estaría bien?",
  ui_story_5053_50531401_167_dialog_content = "Quiere... Casa...",
  ui_story_5053_50531401_168_dialog_content = "Josué?",
  ui_story_5053_50531401_169_dialog_content = "Quiero ir a casa...",
  ui_story_5053_50531401_170_dialog_content = "Lo sé. Te prometo que nos iremos a casa juntos.",
  ui_story_5053_50531401_171_dialog_content = "Joshua... ¿Te arrepientes de nuestro matrimonio?",
  ui_story_5053_50531401_172_dialog_content = "Haber guardado tanta rabia y dolor escondidos en tu corazón... ¿Te arrepientes de haberme elegido para ser tu esposo?",
  ui_story_5053_50531401_173_dialog_content = "Me enseñaste... la felicidad y el amor.",
  ui_story_5053_50531401_174_dialog_content = "El odio... es la otra cara... del amor.",
  ui_story_5053_50531401_175_dialog_content = "El odio es... doloroso... pero nació... del amor... Así que no tengo... remordimientos.",
  ui_story_5053_50531401_176_dialog_content = "...",
  ui_story_5053_50531401_177_dialog_content = "¿En serio?",
  ui_story_5053_50531401_178_dialog_content = "Entiendo...",
  ui_story_5053_50531401_179_dialog_content = "Los puntos cinco y seis ya están armados...",
  ui_story_5053_50531401_180_dialog_content = "Bien. Ahora lo único que falta es un detonador, y nuestras bombas estarán listas para atraer al dragón.",
  ui_story_5053_50531401_181_dialog_content = "¿Cómo van las cosas con los explosivos, Sr. Caleb? ¿Requieres mi ayuda?",
  ui_story_5053_50531401_182_dialog_content = "De nada. Ya he terminado de montarlos.",
  ui_story_5053_50531401_183_dialog_content = "En tan poco tiempo, nada menos. Muy impresionante, señor.",
  ui_story_5053_50531401_184_dialog_content = "No hay necesidad de halagos entre parientes, Sra. Rot. Además, si alguien merece elogios, eres tú.",
  ui_story_5053_50531401_185_dialog_content = "Sin ti, estos guardias nunca nos habrían permitido hacer preparativos tan elaborados.",
  ui_story_5053_50531401_186_dialog_content = "Simplemente estoy cumpliendo con mis deberes. ¿Estás seguro de que ninguno de los dos necesita mi ayuda?",
  ui_story_5053_50531401_187_dialog_content = "Como una ilusión creada por el Cristal de la Memoria Eterna, soy mucho más adecuado para mantener a raya al enemigo.",
  ui_story_5053_50531401_188_dialog_content = "Por favor, no diga eso, Sra. Rot...",
  ui_story_5053_50531401_189_dialog_content = "Sin embargo, tengo algo importante que me gustaría preguntarte.",
  ui_story_5053_50531401_190_dialog_content = "Estoy a sus órdenes, su alteza.",
  ui_story_5053_50531401_191_dialog_content = "¿Podrías quedarte al lado de Carleen en mi lugar? Está completamente sola en este momento, y estoy seguro de que eso la tranquilizaría.",
  ui_story_5053_50531401_192_dialog_content = "Como desées. Pero antes, debo preguntar...",
  ui_story_5053_50531401_193_dialog_content = "¿Por qué estás tan preocupado por nuestra seguridad, a pesar de que ninguno de nosotros somos reales?",
  ui_story_5053_50531401_194_dialog_content = "No, Sra. Rot... Todos ustedes siguen siendo muy reales para mí. Cada uno de ustedes es un reflejo de alguien que me importa profundamente. Compartes sus rostros, sus personalidades... Incluso sus recuerdos.",
  ui_story_5053_50531401_195_dialog_content = "Aunque solo existes dentro de este cristal, todavía me preocupo por ti exactamente de la misma manera.",
  ui_story_5053_50531401_196_dialog_content = "En mi opinión, nuestra preocupación mutua es lo que hace que nuestras interacciones sean reales.",
  ui_story_5053_50531401_197_dialog_content = "Además, me niego a ver a los demás como insignificantes, o incluso prescindibles...",
  ui_story_5053_50531401_198_dialog_content = "Me preocupa que si lo hago, me perderé de vista como persona.",
  ui_story_5053_50531401_199_dialog_content = "Siempre te has parecido a tu madre, la princesa Verónica, pero en este momento... apenas puedo distinguirte.",
  ui_story_5053_50531401_200_dialog_content = "E-¿Es eso así...?",
  ui_story_5053_50531401_201_dialog_content = "¡Los preparativos finalmente están completos! Es la hora, Mia!",
  ui_story_5053_50531401_202_dialog_content = "¡Comprendido! Por favor cuídate bien Carleen, Sra. Rot!",
  ui_story_5053_50531401_203_dialog_content = "Parece que mis oraciones han sido respondidas. el futuro de la Schwartz la familia es tan brillante como el mismo sol.",
  ui_story_5053_50531401_204_dialog_content = "*Inhala* Vaya...",
  ui_story_5053_50531401_205_dialog_content = "Tan pronto como presione este botón, las bombas detonarán en una secuencia, lo que debería atraer al dragón a nuestra ubicación en menos de veinte segundos.",
  ui_story_5053_50531401_206_dialog_content = "Estás listo, Mia?",
  ui_story_5053_50531401_207_dialog_content = "Yo creo que sí...",
  ui_story_5053_50531401_208_dialog_content = "Suspiro... Después de todo lo que hemos pasado, ¿cómo sigues tan inseguro?",
  ui_story_5053_50531401_209_dialog_content = "¡Consíguelo!",
  ui_story_5053_50531401_210_dialog_content = "¡Lo siento! Mmm... May ¿Te pregunto algo, tío?",
  ui_story_5053_50531401_211_dialog_content = "Hazlo breve.",
  ui_story_5053_50531401_212_dialog_content = "¿Por qué me elegiste para ayudarte con esta parte del plan?",
  ui_story_5053_50531401_213_dialog_content = "Si necesitabas a alguien poderoso, el padre o la Sra. Rot habrían sido una mejor opción que yo.",
  ui_story_5053_50531401_214_dialog_content = "¿Oh? ¿Y qué te hace decir eso?",
  ui_story_5053_50531401_215_dialog_content = "Nuestra aventura hasta ahora me ha dado una idea clara de tu poder, Mia. Además, me han dicho que eres capaz de convocar a un familiar Lumina. ¿Es eso cierto?",
  ui_story_5053_50531401_216_dialog_content = "Si es así, tiene la movilidad más alta de todos nosotros, lo que lo convierte en un candidato perfecto para este plan.",
  ui_story_5053_50531401_217_dialog_content = "MM-¿Mi familiar?",
  ui_story_5053_50531401_218_dialog_content = "¡Pero solo he convocado a Hippoca unas pocas veces hasta ahora! Todavía no soy muy bueno montándolo...",
  ui_story_5053_50531401_219_dialog_content = "\"Algunas veces\", dices? ¿Por qué diablos desperdiciarías un regalo tan raro y valioso?",
  ui_story_5053_50531401_220_dialog_content = "B-Bueno... La apariencia de Hippoca puede ser un poco inquietante. Cuando lo convoqué por primera vez, todos tenían miedo de Hippoca y decían que su existencia era un presagio terrible.",
  ui_story_5053_50531401_221_dialog_content = "¡P-Pero ya no me siento así por él! ¡No volveré a dudar de mí mismo por lo que digan los demás!",
  ui_story_5053_50531401_222_dialog_content = "Aún así, la verdad es que Hippoca y yo solo hemos luchado juntos unas pocas veces... Por eso no me siento muy seguro...",
  ui_story_5053_50531401_223_dialog_content = "Si fallamos, la vida de todos...",
  ui_story_5053_50531401_224_dialog_content = "Ah, ya veo. Fue obra de Schwartz, ¿no?",
  ui_story_5053_50531401_225_dialog_content = "...",
  ui_story_5053_50531401_226_dialog_content = "Te prohibió convocar a tu familiar, todo por culpa de esos nobles chismosos.",
  ui_story_5053_50531401_227_dialog_content = "¿Honestamente pensó que te salvarías de las críticas al impedirte convocar a Hippoca?",
  ui_story_5053_50531401_228_dialog_content = "¿Eh? N-No tío, padre solo estaba tratando de protegerme... ¿No?",
  ui_story_5053_50531401_229_dialog_content = "<size=45>¡Ese tonto! ¡Ese completo y absoluto tonto!</size>",
  ui_story_5053_50531401_230_dialog_content = "¡¿Qué...?!",
  ui_story_5053_50531401_231_dialog_content = "Escúchame, Mia! ¡Esos nobles idiotas solo dijeron eso porque estaban celosos de ti! ¡Cuanto más extraordinario eres, más intentan arrastrarte por el fango!",
  ui_story_5053_50531401_232_dialog_content = "¡Por eso no deberías escucharlos ni a ellos ni a tu padre! ¡Si te dicen que no hagas algo, esa es la razón por la que debes hacerlo! ¡¡La vida de un genio está llena de obstáculos!!",
  ui_story_5053_50531401_233_dialog_content = "\"La vida de un genio\"?! P-Pero sigo pensando que deberíamos escuchar a los demás, especialmente a nuestra familia...",
  ui_story_5053_50531401_234_dialog_content = "No es verdad, Mia. Eso es justo lo que quieren que pienses, para poder seguir reteniéndote. Déjame mostrarte el camino.",
  ui_story_5053_50531401_235_dialog_content = "¡Debes desatar cada onza de tu poder, aquí y ahora! ¡Déjelo fluir a través de cada célula de su cuerpo y suéltelo todo de una vez!",
  ui_story_5053_50531401_236_dialog_content = "Eh...?!",
  ui_story_5053_50531401_237_dialog_content = "Sólo la medicina más poderosa te curará de esa sumisión exasperante, Mia.",
  ui_story_5053_50531401_238_dialog_content = "Y solo al comprender el alcance total de su poder aprenderá a controlarlo.",
  ui_story_5053_50531401_239_dialog_content = "Todo el alcance de mi poder...",
  ui_story_5053_50531401_240_dialog_content = "(La gente tiende a temer lo que no entiende. En ese sentido, no soy diferente a los demás).",
  ui_story_5053_50531401_241_dialog_content = "(Los métodos del tío pueden parecer un poco extremos... pero tiene razón. Necesito conocer las verdaderas profundidades de mi propia fuerza).",
  ui_story_5053_50531401_242_dialog_content = "Relájate, prometo mantenerte a salvo mientras lo haces. No pensaste que yo era solo otro erudito insignificante, ¿verdad?",
  ui_story_5053_50531401_243_dialog_content = "E-El pensamiento nunca pasó por mi mente. Muy bien, tío... ¡Haré lo mejor que pueda!",
  ui_story_5053_50531401_244_dialog_content = "¡Ese es el espíritu!",
  ui_story_5053_50531401_245_dialog_content = "¡Ahora prepárate para la batalla!",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>Rugido-</color>",
  ui_story_5053_50531501_2_dialog_content = "¡Qué monstruoso rugido! ¡Podíamos oírlo todo el camino hasta aquí!",
  ui_story_5053_50531501_3_dialog_content = "Han pasado tres minutos desde la primera explosión. Dos llamas de diferentes colores están luchando en el cielo por allí.",
  ui_story_5053_50531501_4_dialog_content = "el azul es Mia, y el rojo es el dragón...",
  ui_story_5053_50531501_5_dialog_content = "¡Mirar! ¡La llama roja se está apagando! Mia ¡y Caleb lo hizo!",
  ui_story_5053_50531501_6_dialog_content = "Parece que llegamos en el momento justo.",
  ui_story_5053_50531501_7_dialog_content = "Caballero Schwartz! ¡Estaba a punto de venir y decírtelo!",
  ui_story_5053_50531501_8_dialog_content = "Entonces, ¿están listos para negociar?",
  ui_story_5053_50531501_9_dialog_content = "Sí, y ahora que las tornas han cambiado...",
  ui_story_5053_50531501_10_dialog_content = "Todo lo que queda es ver dónde la reina enemiga hace su movimiento final.",
  ui_story_5053_50531501_11_dialog_content = "... Aquí...",
  ui_story_5053_50531501_12_dialog_content = "¿Eh? A qué te refieres aquí\"?",
  ui_story_5053_50531501_13_dialog_content = "Aquí... ¡Ella está aquí...!",
  ui_story_5053_50531501_14_dialog_content = "¡¡E-El suelo está temblando y partiéndose!! ¡¿Es esto lo que está haciendo el Demonio Blanco?!",
  ui_story_5053_50531501_15_dialog_content = "¡PlayerName!",
  ui_story_5053_50531501_16_dialog_content = "¡Explosión! ¡¿Qué diablos está pasando?!",
  ui_story_5053_50531501_17_dialog_content = "Mia? ¿Caleb? ¿Qué están haciendo ustedes dos de vuelta tan pronto? ¿No acabas de terminar de matar al dragón?",
  ui_story_5053_50531501_18_dialog_content = "No, y tampoco estamos completamente seguros de lo que sucedió.",
  ui_story_5053_50531501_19_dialog_content = "Cuando el dragón cayó del cielo, el cuadrado central comenzó a deformarse y romperse. Aparte de mi tío y yo...",
  ui_story_5053_50531501_20_dialog_content = "Todos en el área se convirtieron en destellos de luz blanca y volaron hacia el cielo.",
  ui_story_5053_50531501_21_dialog_content = "Cuando tratamos de escapar por la puerta principal de alguien, de repente nos encontramos de regreso en la mansión.",
  ui_story_5053_50531501_22_dialog_content = "Zzzzz...",
  ui_story_5053_50531501_23_dialog_content = "Despertar, Jakine! ¡Algo terrible está pasando!",
  ui_story_5053_50531501_24_dialog_content = "Zzzzz... ¿Eh? ¡¿Quién está ahí?! ¡Mantén tus manos fuera de mi cristal!",
  ui_story_5053_50531501_25_dialog_content = "O-Oye... ¡¿Qué pasó con el Cristal de la Memoria Eterna?!",
  ui_story_5053_50531501_26_dialog_content = "¿Por qué?",
  ui_story_5053_50531501_27_dialog_content = "¿Por qué has elegido ponerte del lado de esa repugnante criatura...?",
  ui_story_5053_50531501_28_dialog_content = "Madre... tu cara...",
  ui_story_5053_50531501_29_dialog_content = "¡Mira las grietas que aparecen en su rostro! Son del mismo color que la Oscuridad. Angel!",
  ui_story_5053_50531501_30_dialog_content = "¿Por qué no me elegiste a mí...?",
  ui_story_5053_50531501_31_dialog_content = "¿Por qué nadie entiende la importancia de mis ideales...?",
  ui_story_5053_50531501_32_dialog_content = "<size=45>¿¡¿POR QUÉ?!?</size>",
  ui_story_5053_50531501_33_dialog_content = "Sh-Ella se está convirtiendo en la oscuridad Angel!!",
  ui_story_5053_50531501_34_dialog_content = "Entonces Mia ¡era correcto! Los dos son iguales...",
  ui_story_5053_50531501_35_dialog_content = "¡Supongo que no tenemos tiempo para discutir su rendición con té y galletas! ¡Vamos a por ella!",
  ui_story_5053_50531501_36_dialog_content = "M-Madre... ¡Lo siento!",
  ui_story_5053_50531501_37_dialog_content = "Josué...",
  ui_story_5053_50531501_38_dialog_content = "¿Estás dudando ahora de todos los tiempos, Caleb?",
  ui_story_5053_50531501_39_dialog_content = "Incluso mi hija mayor está mostrando más coraje que tú en este momento.",
  ui_story_5053_50531501_40_dialog_content = "¡Guárdalo, Schwartz! ¡Cuando se trata de los asuntos de mi hermana, solo tú no tienes derecho a culpar a nadie!",
  ui_story_5053_50531501_41_dialog_content = "¡Solo espera hasta que volvamos al mundo real!",
  ui_story_5053_50531501_42_dialog_content = "(Niño tonto. Incluso después de todos estos años, todavía no puedes controlar tu temperamento).",
  ui_story_5053_50531501_43_dialog_content = "...",
  ui_story_5053_50531502_1_dialog_content = "Urgh...!!",
  ui_story_5053_50531502_2_dialog_content = "Jakine!",
  ui_story_5053_50531502_3_dialog_content = "¡¡Muy por delante de usted!!",
  ui_story_5053_50531502_4_dialog_content = "S-Quédate atrás...",
  ui_story_5053_50531502_5_dialog_content = "Se acabó, Joshua.",
  ui_story_5053_50531502_6_dialog_content = "¡No te acerques más...!",
  ui_story_5053_50531502_7_dialog_content = "Luchar solo lo hará más doloroso.",
  ui_story_5053_50531502_8_dialog_content = "¡¡¡Mantente alejado de mí!!!",
  ui_story_5053_50531502_9_dialog_content = "Caballero Schwartz!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>La espada del soberano—</size>",
  ui_story_5053_50531502_11_dialog_content = "Uwaaaaa!!",
  ui_story_5053_50531502_12_dialog_content = "Todo es tu culpa...",
  ui_story_5053_50531502_13_dialog_content = "...",
  ui_story_5053_50531502_14_dialog_content = "Tú... me hiciste débil...",
  ui_story_5053_50531502_15_dialog_content = "Verónica y Carleen... Caleb y Blanc... Y Schwartz.",
  ui_story_5053_50531502_16_dialog_content = "¡Son escoria traidora, todos y cada uno de ellos!",
  ui_story_5053_50531502_17_dialog_content = "¡¿Cómo pudiste entregarles tus ideales?! Inútil, tonto roto—",
  ui_story_5053_50531502_18_dialog_content = "Mia, ayúdame a terminar esto. No podemos dejar que mi hermana siga lastimándose.",
  ui_story_5053_50531502_19_dialog_content = "Bien...",
  ui_story_5053_50531502_20_dialog_content = "¡Esperar! ¡No te acerques a ella!",
  ui_story_5053_50531502_21_dialog_content = "Si así es como debe terminar... Entonces, en nombre de la venganza...",
  ui_story_5053_50531502_22_dialog_content = "Juro aniquilar hasta el último de ustedes...",
  ui_story_5053_50531502_23_dialog_content = "...¿Eh? ¿Qué pasa con este viento?",
  ui_story_5053_50531502_24_dialog_content = "¡Mirar! ¡Está empezando a absorber la Lumina dentro del Cristal de la Memoria Eterna!",
  ui_story_5053_50531502_25_dialog_content = "¿Está ella... tratando de derribarnos con ella?",
  ui_story_5053_50531502_26_dialog_content = "Jakine¡Prepárate para sacarnos de aquí! ¡El resto de ustedes, ayúdenme a someterla!",
  ui_story_5053_50531502_27_dialog_content = "¿Qué? ¡¿Dices que ahorita?!",
  ui_story_5053_50531502_28_dialog_content = "¡¿Planeas llevar a mi hermana de vuelta a este estado?!",
  ui_story_5053_50531502_29_dialog_content = "Si Joshua si lastimara a alguno de ustedes, solo le rompería el corazón.",
  ui_story_5053_50531502_30_dialog_content = "¡Todos los que se oponen a mis ideales deben perecer! ¡¡¡Mueran, asquerosos traidores!!!",
  ui_story_5053_50531502_31_dialog_content = "¿Por qué tiene que llegar a esto, Madre? ¿Podrías realmente tener tanto odio en tu corazón hacia nosotros...?",
  ui_story_5053_50531502_32_dialog_content = "Vonnie... No estés triste...",
  ui_story_5053_50531502_33_dialog_content = "Déjame esto a mi...",
  ui_story_5053_50531502_34_dialog_content = "Madre...?",
  ui_story_5053_50531502_35_dialog_content = "¡Argh, nuestros ataques son inútiles! Mia, ¡deja de estar parado y concéntrate en la batalla!",
  ui_story_5053_50531502_36_dialog_content = "... Joshua? Espera, ¡¿qué estás haciendo?! ¡¡No te acerques a tu otra mitad!!",
  ui_story_5053_50531502_37_dialog_content = "... Confía en ella, Caleb.",
  ui_story_5053_50531502_38_dialog_content = "Déjame ir, Schwartz! ¡No intentes detenerme! Joshua!!!",
  ui_story_5053_50531502_39_dialog_content = "¡El viento es demasiado fuerte para que abra los ojos! ¡No puedo usar el Cristal de la Memoria Eterna de esta manera!",
  ui_story_5053_50531502_40_dialog_content = "¡¿E-Eh?! ¡Me estoy quedando impresionado! Ayúdame-",
  ui_story_5053_50531502_41_dialog_content = "Jakine!",
  ui_story_5053_50531502_42_dialog_content = "gracias PlayerName... ¿Eh?",
  ui_story_5053_50531502_43_dialog_content = "No tengas miedo... Todo ha terminado ahora.",
  ui_story_5053_50531502_44_dialog_content = "Recuerden aferrarse fuertemente el uno al otro esta vez, todos.",
  ui_story_5053_50531502_45_dialog_content = "J-Joshua...?",
  ui_story_5053_50531502_46_dialog_content = "Madre... eres tú...",
  ui_story_5053_50531502_47_dialog_content = "¡No! Quedarse atrás...",
  ui_story_5053_50531502_48_dialog_content = "Eso es suficiente. Es hora de dejar que todos se vayan a casa ahora.",
  ui_story_5053_50531502_49_dialog_content = "¡No! No te me acerques... Noooo!!!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>Joshua!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "Finalmente te he encontrado.",
  ui_story_5053_50531601_2_dialog_content = "Eres tu...! ¡No! ¡Alejarse de mí!",
  ui_story_5053_50531601_3_dialog_content = "¿De verdad estás tan disgustado conmigo?",
  ui_story_5053_50531601_4_dialog_content = "¡Claro que soy yo! ¿Te has visto en el espejo últimamente? ¿Quién podría soportar mirar a alguien tan horrible, y mucho menos amarlo?",
  ui_story_5053_50531601_5_dialog_content = "Ya veo... Yo también solía sentirme así.",
  ui_story_5053_50531601_6_dialog_content = "Pero cuando vi cuánto se preocupaban por mí mi familia y mis amigos, comencé a ver más allá de mi autodesprecio y a amarme a mí mismo nuevamente.",
  ui_story_5053_50531601_7_dialog_content = "Qué asco...",
  ui_story_5053_50531601_8_dialog_content = "¿Te has visto en el espejo también?",
  ui_story_5053_50531601_9_dialog_content = "Tengo. Solía practicar el control de mis expresiones frente al espejo durante tres horas todos los días. No tengo ninguna razón para mirarme a mí mismo por más tiempo.",
  ui_story_5053_50531601_10_dialog_content = "Así es, siempre has sido una guerrera tan valiente e intrépida, que haría cualquier cosa para realizar sus ideales.",
  ui_story_5053_50531601_11_dialog_content = "Pero todos tienen algo a lo que temen, y tú no eres la excepción. Para ti...",
  ui_story_5053_50531601_12_dialog_content = "Era tu padre muriendo.",
  ui_story_5053_50531601_13_dialog_content = "¡¿?!",
  ui_story_5053_50531601_14_dialog_content = "Fueron tus hijos y tu hermano aprendiendo la verdad.",
  ui_story_5053_50531601_15_dialog_content = "Para...",
  ui_story_5053_50531601_16_dialog_content = "Fue su esposo separándose de usted.",
  ui_story_5053_50531601_17_dialog_content = "¡Dije que lo detuvieras!",
  ui_story_5053_50531601_18_dialog_content = "Tú eres el que teme esas cosas... ¡Yo no! ¡Tú eres el que insiste en tener esas emociones sin sentido!",
  ui_story_5053_50531601_19_dialog_content = "No los necesito... ¡No necesito familia ni sentimientos para realizar mis ambiciones! ¡Solo necesito sacrificarme!",
  ui_story_5053_50531601_20_dialog_content = "Lo sé. Solo quieres vivir una vida simple y sin complicaciones. De esa manera, nunca tendrías que experimentar la felicidad o el dolor de la pérdida.",
  ui_story_5053_50531601_21_dialog_content = "Fue el miedo a conocer esas emociones lo que te hizo forzarme a salir de tu cuerpo.",
  ui_story_5053_50531601_22_dialog_content = "Cállate... Ya basta...",
  ui_story_5053_50531601_23_dialog_content = "¡Nunca puedo confiar en ellos! No me escuchan... Solo quieren traicionarme...",
  ui_story_5053_50531601_24_dialog_content = "Las personas no son máquinas. Todos tienen sus propios pensamientos y sentimientos.",
  ui_story_5053_50531601_25_dialog_content = "\"Desde que te detuve ese día, he pensado en eso constantemente\".",
  ui_story_5053_50531601_26_dialog_content = "\"¿Está mal que confiemos nuestros sueños a otros?\"",
  ui_story_5053_50531601_27_dialog_content = "Daniel dijo eso una vez antes, ¿recuerdas?",
  ui_story_5053_50531601_28_dialog_content = "No es más que un mentiroso...",
  ui_story_5053_50531601_29_dialog_content = "Simplemente dependíamos demasiado de él. Pusimos el peso de nuestros ideales sobre los hombros de una sola persona.",
  ui_story_5053_50531601_30_dialog_content = "Sabes mejor que yo que la familia de un señor de la ciudad nunca podría experimentar las alegrías de la vida ordinaria... Y, sin embargo, nunca dejé de esperarlo.",
  ui_story_5053_50531601_31_dialog_content = "Una asesina despiadada, la esposa perfecta de un señor de la ciudad...",
  ui_story_5053_50531601_32_dialog_content = "Cambiamos constantemente entre las identidades que nos dieron otras personas, pero ninguna de ellas reflejaba nuestro verdadero yo.",
  ui_story_5053_50531601_33_dialog_content = "Todavía no sé quiénes somos realmente...",
  ui_story_5053_50531601_34_dialog_content = "...",
  ui_story_5053_50531601_35_dialog_content = "Pero una cosa que sí sé es que no quiero perder a las personas que amo. Eso siempre será más importante que la verdad.",
  ui_story_5053_50531601_36_dialog_content = "Entonces ven conmigo. Es hora de dejar de pelear.",
  ui_story_5053_50531601_37_dialog_content = "¡Argh! Tu mano... ¡Se siente como si estuviera cubierta de espinas! ¡Hasta el más mínimo toque duele tanto!",
  ui_story_5053_50531601_38_dialog_content = "Y sin embargo, se siente tan cálido... ¿Qué es este sentimiento?",
  ui_story_5053_50531601_39_dialog_content = "Así es como <color=#FFB400>amar</color> siente.",
  ui_story_5053_50531601_40_dialog_content = "¡Madre! Tos, tos... Madre, ¿dónde estás?",
  ui_story_5053_50531601_41_dialog_content = "Aqui, Mia! ¡Toma mi mano!",
  ui_story_5053_50531601_42_dialog_content = "PlayerName... Todos... ¿Adónde fue mamá?",
  ui_story_5053_50531601_43_dialog_content = "Ella... Después de la explosión...",
  ui_story_5053_50531601_44_dialog_content = "Lanza el hechizo, Jakine.",
  ui_story_5053_50531601_45_dialog_content = "¡Suéltame! ¡¡Me niego a irme sin mi hermana!!",
  ui_story_5053_50531601_46_dialog_content = "¡El suelo se derrumba bajo nuestros pies! ¡Apurarse!",
  ui_story_5053_50531601_47_dialog_content = "¡Lo tengo!",
  ui_story_5053_50531601_48_dialog_content = "Anuncio praessence!",
  ui_story_5053_50531601_49_dialog_content = "¡Volvamos a la realidad!",
  ui_story_5053_50531601_50_dialog_content = "¡Abracadabra!",
  ui_story_5053_50531601_51_dialog_content = "Joshua! no te dejare!! Joshua!!!",
  ui_story_5053_50531601_52_dialog_content = "Mocoso testarudo... Jakine, agarrarse a Mia!",
  ui_story_5053_50531601_53_dialog_content = "¿Q-Qué dijiste? ¡¡No puedo oírte por el viento!!",
  ui_story_5053_50531601_54_dialog_content = "¡No puedo aguantar más! PlayerName!!",
  ui_story_5053_50531601_55_dialog_content = "Ahh!!!",
  ui_story_5053_50531601_56_dialog_content = "Entonces agárrate a mí.",
  ui_story_5053_50531601_57_dialog_content = "Eres tu...?",
  ui_story_5053_50531601_58_dialog_content = "\"... Espero que esta carta te encuentre bien\".",
  ui_story_5053_50531601_59_dialog_content = "\"¿Cómo has estado últimamente? Los demás y yo estamos bien\".",
  ui_story_5053_50531601_60_dialog_content = "Escribiendo una carta, ¿eh? ¿Para quién es?",
  ui_story_5053_50531601_61_dialog_content = "¡Bwaaa! J-Jakine! Me asustaste...",
  ui_story_5053_50531601_62_dialog_content = "Jejeje, lo siento por eso!",
  ui_story_5053_50531601_63_dialog_content = "Buenas tardes, PlayerName.",
  ui_story_5053_50531601_64_dialog_content = "¡Buenas tardes! Seguro que llegaron temprano, pensé. Jakine Iba a llegar tarde otra vez!",
  ui_story_5053_50531601_65_dialog_content = "¡Oye, no es mi culpa que todos se mueran por saber sobre mi trabajo! Es difícil mantener un horario cuando una multitud de personas te bombardea constantemente con preguntas...",
  ui_story_5053_50531601_66_dialog_content = "Oh sí, estoy seguro de ser una celebridad en el Dawn La academia debe ser tan horrible para Jakine, el \"erudito visitante\".",
  ui_story_5053_50531601_67_dialog_content = "¡Jejeje, no me llames así! Vas a hacer que me sonroje...",
  ui_story_5053_50531601_68_dialog_content = "De todos modos, ¿te has encargado de las cosas por tu parte? Mia?",
  ui_story_5053_50531601_69_dialog_content = "¡Sí! ¡Todo está tomado!",
  ui_story_5053_50531601_70_dialog_content = "Desafortunadamente, estábamos tan ocupados que Carleen y no tuve la oportunidad de despedirnos...",
  ui_story_5053_50531601_71_dialog_content = "¡No te preocupes, siempre puedes venir a verla en el Coloso! Te avisaré la próxima vez que esté a bordo.",
  ui_story_5053_50531601_72_dialog_content = "Está bien, nos volveremos a ver cuando sea el momento adecuado.",
  ui_story_5053_50531601_73_dialog_content = "Oh, okay...",
  ui_story_5053_50531601_74_dialog_content = "\"Desde entonces, han sucedido muchas cosas aquí, con muchas personas tomando decisiones inesperadas\".",
  ui_story_5053_50531601_75_dialog_content = "\"Prometí que resolvería toda la historia por ti, así que comencemos desde el principio\".",
  ui_story_5053_50531601_76_dialog_content = "\"En ese momento, salimos con éxito del <color=#FFB400>Cristal de memoria eterna</color>\"",
  ui_story_5053_50531601_77_dialog_content = "\"Antes de que tuviéramos tiempo de asegurarnos de que todos estuvieran bien, Caleb ya había salido por la puerta y regresaba corriendo a su casa\".",
  ui_story_5053_50531601_78_dialog_content = "\"No pasó mucho tiempo antes de que lo persiguiéramos ... Solo para encontrarlo con Lady Joshua, a quien había tenido escondido en su casa todos estos años\".",
  ui_story_5053_50531601_79_dialog_content = "¡Los ojos de mamá se movieron...!",
  ui_story_5053_50531601_80_dialog_content = "¡Dame esa medicina! ¡El del estante de la izquierda!",
  ui_story_5053_50531601_81_dialog_content = "¡E-Espera, todavía estoy buscando la gasa!",
  ui_story_5053_50531601_82_dialog_content = "lo tengo aqui",
  ui_story_5053_50531601_83_dialog_content = "\"Después de un estresante procedimiento de emergencia, Lady Joshua finalmente salió del estado crítico. Unos días después, se despertó\".",
  ui_story_5053_50531601_84_dialog_content = "\"Desafortunadamente... había perdido todos sus recuerdos\".",
  ui_story_5053_50531601_85_dialog_content = "¿Cómo...? ¿Cómo pudo haber sucedido esto? ¿Estuvo en coma durante demasiado tiempo? ¿O fue esa explosión de antes?",
  ui_story_5053_50531601_86_dialog_content = "Cualquiera que sea el caso, parece que mi hermana ya no sufre de doble personalidad. Pero cómo...?",
  ui_story_5053_50531601_87_dialog_content = "¿Podría tener algo que ver con el Cristal de la Memoria Eterna, Jakine?",
  ui_story_5053_50531601_88_dialog_content = "Hm... Yo no estaría tan seguro.",
  ui_story_5053_50531601_89_dialog_content = "¿Y qué se supone que significa eso? Esto es serio, ¿sabes?",
  ui_story_5053_50531601_90_dialog_content = "\"Con el fin de reparar el Cristal de la Memoria Eterna, así como ayudar con la recuperación de Lady Joshua...\"",
  ui_story_5053_50531601_91_dialog_content = "\"Jakine decidió quedarse en Lumopolis por un tiempo más y comenzó a realizar investigaciones junto a Caleb\".",
  ui_story_5053_50531601_92_dialog_content = "\"Incluso le dio el título de \"Académica visitante de la Dawn Academy\", solo para hacerla feliz\".",
  ui_story_5053_50531601_93_dialog_content = "\"No creo que el título tenga ninguna autoridad real, pero mientras Jakine no se entera...\"",
  ui_story_5053_50531601_94_dialog_content = "En este momento, todo lo que sabemos es que, por alguna razón, el Demonio Blanco y el Oscuro Angel se contactaron entre sí al final.",
  ui_story_5053_50531601_94X1_dialog_content = "Cuando ambas personalidades en conflicto desaparecieron, Lady JoshuaEl estado mental de volvió a la normalidad.",
  ui_story_5053_50531601_95_dialog_content = "En cuanto a la Semilla, todavía tenemos que estudiarla en profundidad, pero solo podemos contar con Caleb para eso.",
  ui_story_5053_50531601_96_dialog_content = "Bien hecho, emisario Jakine de Northland. Gracias por permanecer en Lumopolis estos días y ayudar a Caleb en el esfuerzo.",
  ui_story_5053_50531601_97_dialog_content = "¡Es un honor! ¡No me siento como un extraño después de todo lo que hemos pasado juntos!",
  ui_story_5053_50531601_98_dialog_content = "Además de eso, se suponía que debía reponer el Cristal de la Memoria Eterna con agua del Lago Mirror, no romperlo...",
  ui_story_5053_50531601_99_dialog_content = "¡Oh, hablando de eso, el Cristal está arreglado! Y ahora esa señora Joshua está de vuelta, ¡puedes usarlo en cualquier momento!",
  ui_story_5053_50531601_100_dialog_content = "Gracias. Lo mantendré a salvo para evitar que otros entren accidentalmente.",
  ui_story_5053_50531601_101_dialog_content = "Sí... Pero en realidad estoy un poco preocupado por Caleb. desde señora Joshua se despertó, ¡él ha estado cerca de ella todo el tiempo!",
  ui_story_5053_50531601_102_dialog_content = "También escuché que quería renunciar a la Dawn Academia para quedarse en casa y cuidar a Lady Joshua tiempo completo... Me pregunto si entendió las implicaciones en absoluto.",
  ui_story_5053_50531601_103_dialog_content = "Qué perpetuamente inmaduro de su parte... Escuché que estás buscando a un caballero llamado Sharona. ¿Es eso cierto?",
  ui_story_5053_50531601_104_dialog_content = "Soy. ¡Veo que su red tiene las narices en el suelo, mi señor! ¿Te importaría presentármela?",
  ui_story_5053_50531601_105_dialog_content = "Lo siento, Jakine, pero Sharona dejó Lumopolis hace un tiempo. No soy capaz de cumplir con su solicitud.",
  ui_story_5053_50531601_106_dialog_content = "¿Qué? ¿Pero no es su sueño convertirse en el caballero más poderoso...?",
  ui_story_5053_50531601_107_dialog_content = "Puedes buscarla en Illumina, pero nunca me menciones a Lumopolis.",
  ui_story_5053_50531601_108_dialog_content = "Y no olvides que lo que sucedió en el Cristal no fue real, por más fuerte que se formó un vínculo entre ustedes dos...",
  ui_story_5053_50531601_109_dialog_content = "No era más que una aspiración. Mucho ha cambiado en los doce años.",
  ui_story_5053_50531601_110_dialog_content = "Ya veo... Está bien, mientras nos mantengamos fieles a lo que somos, ¡todavía podemos convertirnos en amigos!",
  ui_story_5053_50531601_111_dialog_content = "Manteniéndote fiel a quien eres, dijiste... Tienes razón.",
  ui_story_5053_50531601_112_dialog_content = "\"Pensé señora Joshua perder la memoria volvería a sumir a su familia en el dolor\".",
  ui_story_5053_50531601_113_dialog_content = "\"Excepto que no se sintieron derrotados, sino que rápidamente se regocijaron en la reunión después de una breve decepción\".",
  ui_story_5053_50531601_114_dialog_content = "\"Es bueno ver a la familia feliz y completa... Qué vínculo tan simple pero perfecto que todos compartieron\".",
  ui_story_5053_50531601_115_dialog_content = "\"Pero el <color=#FFB400>Señor de la ciudad y su familia</color> están demasiado en el centro de atención para que puedan disfrutar de la dicha de una familia normal.",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>Magnus Manor, hogar de Caleb</color>",
  ui_story_5053_50531601_117_dialog_content = "¡Estoy de vuelta, hermana! Mira esto. Es el último té de frutas de Umbraton. ¡Apuesto a que te encantará!",
  ui_story_5053_50531601_118_dialog_content = "Bienvenido a casa, tío.",
  ui_story_5053_50531601_119_dialog_content = "Bienvenido de nuevo. Uh, ¿no es un día de trabajo hoy? ¿No estás trabajando, Caleb?",
  ui_story_5053_50531601_120_dialog_content = "Ningún trabajo es tan importante como tú. entregué mi renuncia a la Dawn Academia ya. Estaré contigo a partir de ahora.",
  ui_story_5053_50531601_121_dialog_content = "¿Qué, renunciaste? ¿Vas a abandonar tu carrera y tus aspiraciones por mí?",
  ui_story_5053_50531601_122_dialog_content = "No lo digas de esa manera, hermana. Nada es tan grande como vivir una vida feliz con tu familia.",
  ui_story_5053_50531601_123_dialog_content = "Y Mia también ha querido volver con su familia en Lumopolis. ¿No es así? Mia?",
  ui_story_5053_50531601_124_dialog_content = "Bueno... En realidad, eso es de lo que estoy aquí para hablar con mamá. Me gustaría quedarme en Umbraton.",
  ui_story_5053_50531601_125_dialog_content = "¿Qué? ¿Por qué pensarías eso ahora? Hizo Schwartz intimidarte de nuevo?",
  ui_story_5053_50531601_126_dialog_content = "No, fue mi propia decisión. Padre también está detrás de esto.",
  ui_story_5053_50531601_127_dialog_content = "Fui débil y desventurado en el pasado, forzado a irme y soportar penurias...",
  ui_story_5053_50531601_128_dialog_content = "Pero también pude ver la verdad del mundo fuera de Lumopolis y eso me hizo quien soy hoy. Sin embargo, siento que eso no es suficiente.",
  ui_story_5053_50531601_129_dialog_content = "Ya deberías saber que contigo tomándote mucho tiempo libre y yo yendo y viniendo en un velo, los rumores están comenzando a volar en Lumopolis Gardens.",
  ui_story_5053_50531601_130_dialog_content = "Padre ni siquiera pudo venir aquí a ver a Madre por eso... a pesar de que la escondimos.",
  ui_story_5053_50531601_131_dialog_content = "¡Lo se! Y he estado buscando una solución. En el peor de los casos, ¡simplemente nos mudaremos de Lumopolis!",
  ui_story_5053_50531601_132_dialog_content = "¿Y qué si la esposa del Señor de la Ciudad reviviera después de todos estos años...",
  ui_story_5053_50531601_133_dialog_content = "Necesitas poder real para desafiar Schwartz! ¡Solo confiar en el escándalo político no servirá!",
  ui_story_5053_50531601_134_dialog_content = "Sí, sé que nada de eso es culpa de la familia, pero aún así es algo que tenemos que soportar.",
  ui_story_5053_50531601_135_dialog_content = "Finalmente entiendo cómo se siente Padre ahora... Por eso ya no codicio el abrazo de mi madre.",
  ui_story_5053_50531601_136_dialog_content = "Ya que no puedo sobrevivir bajo los reflectores en Lumopolis, déjame quedarme en la oscuridad como una sombra.",
  ui_story_5053_50531601_137_dialog_content = "Aprenderé tanto del Sr. Istvan en Umbraton como sea posible, pasando de ser un debilucho que necesita protección a un valiente caballero.",
  ui_story_5053_50531601_138_dialog_content = "¡Entonces será mi turno de proteger a todos!",
  ui_story_5053_50531601_139_dialog_content = "Porque te sientes asi? ¿No crees que podrías confiar y depender de mí? ¡Háblala de eso, hermana!",
  ui_story_5053_50531601_140_dialog_content = "Caleb, soy <color=#FFB400>alguien sin memoria</color>. No tengo un pasado, ni me detengo en él.",
  ui_story_5053_50531601_141_dialog_content = "Estoy muy feliz de que hayas encontrado tu sueño, Mia. Solo trabaja duro, cariño, y estoy seguro de que tendrás un futuro emocionante por delante.",
  ui_story_5053_50531601_142_dialog_content = "Madre... Gracias.",
  ui_story_5053_50531601_143_dialog_content = "Me acabas de recordar, Mia, también hay un mundo emocionante ahí fuera. Debería verlo por mí mismo.",
  ui_story_5053_50531601_144_dialog_content = "Espera un minuto, ¿qué quieres decir con eso, hermana?",
  ui_story_5053_50531601_145_dialog_content = "\"Sí, después de todo lo que pasó, Mia todavía optó por irse\".",
  ui_story_5053_50531601_146_dialog_content = "\"Tomó la decisión por su cuenta, y sinceramente me siento feliz por ella\".",
  ui_story_5053_50531601_147_dialog_content = "\"Mientras tanto, la renuncia de Caleb fue rechazada\".",
  ui_story_5053_50531601_148_dialog_content = "\"Parecía que a menudo presentaba todo tipo de excusas imprudentes para renunciar, por lo que la Academia simplemente lo rechazó por costumbre\".",
  ui_story_5053_50531601_149_dialog_content = "\"Para dama Joshua, parecía estar inspirada y comenzó a tener sus propias ideas\".",
  ui_story_5053_50531601_150_dialog_content = "\"Se escapó de Lumopolis en un viaje en solitario\".",
  ui_story_5053_50531601_151_dialog_content = "Gracias, PlayerName, por sacarme de contrabando en el Coloso.",
  ui_story_5053_50531601_152_dialog_content = "Feliz de hacer eso. ¿Pero cómo es que no les dijiste adiós?",
  ui_story_5053_50531601_153_dialog_content = "Eres más inteligente que eso. Nunca me dejarían ir si supieran que me voy.",
  ui_story_5053_50531601_154_dialog_content = "Pero debo irme, no solo para protegerlos, sino como una lección final para ellos como madre y hermana.",
  ui_story_5053_50531601_155_dialog_content = "¿De verdad has perdido la memoria, señora? Joshua?",
  ui_story_5053_50531601_156_dialog_content = "Por supuesto. ¡No uses tus poderes Caelestite para echar un vistazo a los secretos de una dama ahora!",
  ui_story_5053_50531601_157_dialog_content = "Está bien, entonces les diré que te fuiste cuando regrese... Eso no es mentirle a tus superiores, ¿verdad?",
  ui_story_5053_50531601_158_dialog_content = "Bueno, lo es para mí.",
  ui_story_5053_50531601_159_dialog_content = "¡¿Qué?!",
  ui_story_5053_50531601_160_dialog_content = "¡Es una broma! Probablemente Daniel ya lo descubrió. No necesitamos muchas palabras para comunicarnos.",
  ui_story_5053_50531601_161_dialog_content = "Como para Carleen, se parece mucho a Daniel... Escuché que eres muy cercano a ella, así que también deberías saberlo.",
  ui_story_5053_50531601_162_dialog_content = "Parece tan fuerte y competente cuando en realidad solo aguanta. Es un secreto a voces que todos saben que no deben mencionarle.",
  ui_story_5053_50531601_163_dialog_content = "Ciertamente es lo suficientemente capaz como para encontrar cualquier verdad que desee descubrir. Si ella no...",
  ui_story_5053_50531601_164_dialog_content = "Eso significa que todavía no está lista para aceptar la verdad.",
  ui_story_5053_50531601_165_dialog_content = "Sin embargo, a pesar de todo ese discurso, también tengo un lado oculto.",
  ui_story_5053_50531601_166_dialog_content = "Si no estuviera implantado, probablemente nunca me daría cuenta de que he estado reprimiendo un lado oscuro en mí.",
  ui_story_5053_50531601_167_dialog_content = "Dama Joshua...",
  ui_story_5053_50531601_168_dialog_content = "Además de aceptar a los demás con amabilidad, también es necesario impulsarlos con severidad hacia adelante. Esa es otra forma de demostrar que te importa, ¿verdad?",
  ui_story_5053_50531601_169_dialog_content = "Correcto, incluso un refugio seguro podría ser un obstáculo para el crecimiento.",
  ui_story_5053_50531601_170_dialog_content = "Carleen ahora necesita amigos confiables y de ideas afines más que nunca.",
  ui_story_5053_50531601_171_dialog_content = "Entonces, ¿continuarás progresando junto con Carleen, PlayerName?",
  ui_story_5053_50531601_X171_option_content = "¡Claro, no hay problema!",
  ui_story_5053_50531601_X172_option_content = "¿Quién, yo...?",
  ui_story_5053_50531601_X173_dialog_content = "Como miembro de una raza completamente diferente a la nuestra, los aurorianos, Last Caelestite, veo un futuro brillante por delante.",
  ui_story_5053_50531601_X174_dialog_content = "Cosa que además no tiene precio y siempre se pasa por alto en un entorno cercano como Lumopolis.",
  ui_story_5053_50531601_X175_dialog_content = "Creo completamente que puedes guiar Carleen... No, guía a más personas hacia un mañana más brillante.",
  ui_story_5053_50531601_X176_dialog_content = "Tu presencia y el coraje de Mia me mostraron el potencial que hay en el mundo.",
  ui_story_5053_50531601_X177_dialog_content = "Tal vez encuentre lo que realmente estoy buscando después de verlo.",
  ui_story_5053_50531601_X178_dialog_content = "Entonces lleve esa iluminación a mis seres queridos algún día...",
  ui_story_5053_50531601_X179_dialog_content = "\"Por lo tanto, me despido de ti y traje la noticia de tu partida a Lumopolis\".",
  ui_story_5053_50531601_X180_dialog_content = "\"Algunos sonrieron y saludaron. Algunos lo aceptaron felices después de recuperarse de la sorpresa\".",
  ui_story_5053_50531601_X181_dialog_content = "\"Algunos no pudieron entenderlo y se fueron enojados. Aún así, algunos parecían haberlo visto venir\".",
  ui_story_5053_50531601_X182_dialog_content = "\"Después de cierta conmoción, todos lo aceptaron y optaron por no interferir con la nueva vida del amnésico\".",
  ui_story_5053_50531601_X183_dialog_content = "\"En cuanto a mantener una correspondencia conmigo en secreto, será entre nosotros dos\".",
  ui_story_5053_50531601_X184_dialog_content = "\"También te mantendré informado sobre tu familia como prometí\".",
  ui_story_5053_50531601_172_dialog_content = "\"La próxima vez que nos encontremos, espero que podamos compartir nuestras aventuras como compañeros de viaje\".",
  ui_story_5053_50531601_173_dialog_content = "PlayerName! Deja el bolígrafo ya!!",
  ui_story_5053_50531601_174_dialog_content = "¡Bwaaa! M-Me asustaste otra vez, Jakine!!",
  ui_story_5053_50531601_175_dialog_content = "¡Oh no, no puedes culparme esta vez, amigo! Regresaré a Northland hoy, y tú y Mia prometió despedirme! ¡Ahora deja de derramar tu corazón y vamos!",
  ui_story_5053_50531601_176_dialog_content = "E-Espera un segundo, Jakine! ¡Se supone que un Mensajero estará aquí en cualquier momento para entregar mi carta!",
  ui_story_5053_50531601_177_dialog_content = "Además, nunca antes te había importado llegar tarde...",
  ui_story_5053_50531601_178_dialog_content = "¡Ey! ¡Escuché eso!",
  ui_story_5053_50531601_179_dialog_content = "Jejeje, supongo que tendremos que esperar un poco más.",
  ui_story_5053_50531601_180_dialog_content = "Por cierto, PlayerName, ¿recibiste una postal por correo recientemente?",
  ui_story_5053_50531601_181_dialog_content = "¿Una postal?",
  ui_story_5053_50531601_182_dialog_content = "Oh, te refieres a la postal de Lady Joshua, ¿bien? ¡Yo también tengo uno!",
  ui_story_5053_50531601_183_dialog_content = "¡Dijo que llegó a un pequeño pueblo en medio de la nada e incluso se encontró con un pájaro parlante!",
  ui_story_5053_50531601_184_dialog_content = "Hmm... Ella debe estar hablando de un demi-humano. Mamá dijo que se hicieron amigas íntimas en muy poco tiempo... ¡Estoy tan feliz por ella!",
  ui_story_5053_50531601_185_dialog_content = "¿Eh? ¿Soy el único que no recibió una postal...?",
  ui_story_5053_50531601_186_dialog_content = "Supongo que le debemos gustar más que tú, PlayerName! ¿Hiciste algo para molestarla?",
  ui_story_5053_50531601_187_dialog_content = "¡O-Claro que no! Estoy seguro de que mi postal llegará algún día de estos, ¡ya verás!",
  ui_story_5053_50531601_188_dialog_content = "¡TOC Toc! Eho el Correo, a su servicio!",
  ui_story_5053_50531601_189_dialog_content = "¡Buen momento!",
  ui_story_5053_50531601_190_dialog_content = "¡Próximo! Gracias de nuevo por entregar mi carta, Eho.",
  ui_story_5053_50531601_191_dialog_content = "¡No lo menciones! Me quedo con eso... ¡Y toma, este sobre es para ti!",
  ui_story_5053_50531601_192_dialog_content = "¿Para mí? ¡Oye, esto es...!",
  ui_story_5053_50531601_193_dialog_content = "¿Qué cosas divertidas tienes ahí?",
  ui_story_5053_50531601_194_dialog_content = "¿Qué te pasa, PlayerName?",
  ui_story_5053_50531601_195_dialog_content = "¿Podemos echarle un vistazo también? PlayerName?",
  ui_story_5053_50531601_196_dialog_content = "Lo siento, pero no puedo mostrártelo.",
